@dataclass(frozen=True)
class ActionMetadata:
    action_id: int
    name: str | None
    action_category_id: int | None
    cast_ms: int
    recast_ms: int
    gcd_recast_ms: int | None = None
    is_gcd_override: bool | None = None
    recast_speed_adjusted: bool = True
    recast_status_adjusted: bool = True

    @property
    def is_gcd(self) -> bool:
        if self.is_gcd_override is not None:
            return self.is_gcd_override
        return self.action_category_id in GCD_ACTION_CATEGORY_IDS and self.recast_ms >= 1500

    @property
    def effective_recast_ms(self) -> int:
        return self.gcd_recast_ms if self.gcd_recast_ms is not None else self.recast_ms


class ActionMetadataStore:
    def __init__(self, source_url: str = ACTION_CSV_URL) -> None:
        self.source_url = source_url
        self._metadata_by_id: dict[int, ActionMetadata] | None = None

    def get(self, action_id: int) -> ActionMetadata | None:
        if self._metadata_by_id is None:
            self._metadata_by_id = self._load_action_csv()
        return self._metadata_by_id.get(action_id)

    def preload(self) -> None:
        if self._metadata_by_id is None:
            self._metadata_by_id = self._load_action_csv()

    def _load_action_csv(self) -> dict[int, ActionMetadata]:
        try:
            request = urllib.request.Request(
                self.source_url,
                headers={"User-Agent": "ffxiv-tc-ranking-gcd-coverage/1.0"},
            )
            with urllib.request.urlopen(request, timeout=30) as response:
                raw_csv = response.read().decode("utf-8-sig")
        except (OSError, urllib.error.URLError) as error:
            raise RuntimeError(f"無法下載 GCD 技能資料：{self.source_url}") from error

        metadata_by_id: dict[int, ActionMetadata] = {}
        reader = csv.DictReader(io.StringIO(raw_csv))
        for row in reader:
            action_id = to_int(row.get("#"))
            if action_id is None:
                continue

            override = GCD_ACTION_OVERRIDES.get(action_id)
            metadata_by_id[action_id] = ActionMetadata(
                action_id=action_id,
                name=row.get("Name") or None,
                action_category_id=to_int(row.get("ActionCategory")),
                cast_ms=(
                    override.cast_ms
                    if override and override.cast_ms is not None
                    else (to_int(row.get("Cast100ms")) or 0) * 100
                ),
                recast_ms=(to_int(row.get("Recast100ms")) or 0) * 100,
                gcd_recast_ms=override.gcd_recast_ms if override else None,
                is_gcd_override=True if override else None,
                recast_speed_adjusted=override.speed_adjusted if override else True,
                recast_status_adjusted=override.status_speed_adjusted if override else True,
            )

        if not metadata_by_id:
            raise RuntimeError("GCD 技能資料為空，無法計算覆蓋率。")
        return metadata_by_id


def to_number(value: Any) -> float | None:
    if isinstance(value, bool):
        return None
    if isinstance(value, (int, float)):
        return float(value)
    if isinstance(value, str):
        try:
            return float(value.replace(",", ""))
        except ValueError:
            return None
    return None


class StatusMetadataStore:
    def __init__(self, source_url: str = STATUS_CSV_URL) -> None:
        self.source_url = source_url
        self._unable_to_act_status_ids: set[int] | None = None

    def unable_to_act_status_ids(self) -> set[int]:
        if self._unable_to_act_status_ids is None:
            self._unable_to_act_status_ids = self._load_unable_to_act_status_ids()
        return set(self._unable_to_act_status_ids)

    def preload(self) -> None:
        self.unable_to_act_status_ids()

    def _load_unable_to_act_status_ids(self) -> set[int]:
        try:
            request = urllib.request.Request(
                self.source_url,
                headers={"User-Agent": "ffxiv-tc-ranking-gcd-coverage/1.0"},
            )
            with urllib.request.urlopen(request, timeout=30) as response:
                raw_csv = response.read().decode("utf-8-sig")
        except (OSError, urllib.error.URLError):
            return set(FALLBACK_UNABLE_TO_ACT_STATUS_IDS)

        status_ids: set[int] = set()
        reader = csv.DictReader(io.StringIO(raw_csv))
        for row in reader:
            status_id = to_int(row.get("#"))
            if status_id is None:
                continue
            if parse_bool(row.get("LockActions")) or parse_bool(row.get("LockControl")):
                status_ids.add(status_id)

        return status_ids or set(FALLBACK_UNABLE_TO_ACT_STATUS_IDS)


def parse_bool(value: Any) -> bool:
    if isinstance(value, bool):
        return value
    if isinstance(value, str):
        return value.strip().lower() in {"1", "true", "yes"}
    return bool(value)


def to_int(value: Any) -> int | None:
    number = to_number(value)
    if number is None:
        return None
    return int(number)


def first_number(*values: Any) -> float | None:
    for value in values:
        number = to_number(value)
        if number is not None:
            return number
    return None


def gcd_pull_duration_ms(fight: dict[str, Any], start_time: Any, end_time: Any) -> float | None:
    start_number = to_number(start_time)
    end_number = to_number(end_time)
    pull_duration = None
    if start_number is not None and end_number is not None and end_number > start_number:
        pull_duration = end_number - start_number

    # xivanalysis 的 legacy FFLogs adapter 會優先使用 v1 fights 的 combatTime：
    # pull.timestamp = report.start + (fight.end_time - combatTime)，duration = combatTime。
    # 本專案現有資料的 clear_time_ms 來自同一個 FFLogs fight combatTime 語意，因此
    # GCD 分母必須先看 combatTime / clear_time_ms，才退回完整 end-start。
    # damage_time_ms 是 Damage Done 表格分母，只能作為舊資料沒有 fight 時間時的最後 fallback。
    return first_number(
        fight.get("combatTime"),
        fight.get("clear_time_ms"),
        pull_duration,
        fight.get("damage_time_ms"),
    )


def gcd_pull_start_time_ms(fight: dict[str, Any], start_time: Any, end_time: Any) -> float | None:
    start_number = to_number(start_time)
    end_number = to_number(end_time)
    duration = gcd_pull_duration_ms(fight, start_time, end_time)
    if end_number is not None and duration is not None and duration > 0:
        adjusted_start = end_number - duration
        if start_number is None or adjusted_start >= start_number:
            return adjusted_start
    return start_number


def query_fight_casts_graph(
    execute_graphql: Callable[[Any, Any, str, dict[str, Any]], dict[str, Any]],
    session: Any,
    auth_pool: Any,
    report_code: str,
    fight: dict[str, Any],
) -> dict[str, Any]:
    fight_id = to_int(fight.get("fight_id"))
    start_time = first_number(fight.get("start_time"), fight.get("startTime"))
    end_time = first_number(fight.get("end_time"), fight.get("endTime"))
    if fight_id is None or start_time is None or end_time is None:
        raise RuntimeError("缺少 fight_id 或 fight 時間窗，無法查詢整場 Casts graph。")

    query = f"""
    query($code: String!) {{
      reportData {{
        report(code: $code) {{
          graph(
            dataType: Casts,
            fightIDs: [{fight_id}],
            startTime: {start_time},
            endTime: {end_time}
          )
        }}
      }}
    }}
    """
    data = execute_graphql(session, auth_pool, query, {"code": report_code})
    graph = (((data.get("reportData") or {}).get("report") or {}).get("graph") or {}).get("data")
    if not isinstance(graph, dict):
        raise RuntimeError("FFLogs 整場 Casts graph 回傳格式不正確。")
    return graph


def query_fight_damage_done_events(
    execute_graphql: Callable[[Any, Any, str, dict[str, Any]], dict[str, Any]],
    session: Any,
    auth_pool: Any,
    report_code: str,
    fight: dict[str, Any],
    *,
    limit: int = 10_000,
) -> list[dict[str, Any]]:
    fight_id = to_int(fight.get("fight_id"))
    start_time = first_number(fight.get("start_time"), fight.get("startTime"))
    end_time = first_number(fight.get("end_time"), fight.get("endTime"))
    if fight_id is None or start_time is None or end_time is None:
        raise RuntimeError("缺少 fight_id 或 fight 時間窗，無法查詢整場 DamageDone events。")

    query = """
    query($code: String!, $startTime: Float!, $endTime: Float!, $limit: Int!) {
      reportData {
        report(code: $code) {
          events(
            dataType: DamageDone,
            fightIDs: [%d],
            startTime: $startTime,
            endTime: $endTime,
            hostilityType: Friendlies,
            limit: $limit
          ) {
            data
            nextPageTimestamp
          }
        }
      }
    }
    """ % fight_id

    events: list[dict[str, Any]] = []
    cursor = start_time
    while cursor is not None and cursor < end_time:
        data = execute_graphql(
            session,
            auth_pool,
            query,
            {
                "code": report_code,
                "startTime": cursor,
                "endTime": end_time,
                "limit": limit,
            },
        )
        page = (((data.get("reportData") or {}).get("report") or {}).get("events") or {})
        page_events = page.get("data")
        if isinstance(page_events, list):
            events.extend(event for event in page_events if isinstance(event, dict))

        next_cursor = to_number(page.get("nextPageTimestamp"))
        if next_cursor is None or next_cursor <= cursor:
            break
        cursor = next_cursor

    return events


def query_fight_raw_events(
    execute_graphql: Callable[[Any, Any, str, dict[str, Any]], dict[str, Any]],
    session: Any,
    auth_pool: Any,
    report_code: str,
    fight: dict[str, Any],
    *,
    limit: int = 10_000,
) -> list[dict[str, Any]]:
    fight_id = to_int(fight.get("fight_id"))
    start_time = first_number(fight.get("start_time"), fight.get("startTime"))
    end_time = first_number(fight.get("end_time"), fight.get("endTime"))
    if fight_id is None or start_time is None or end_time is None:
        raise RuntimeError("缺少 fight_id 或 fight 時間窗，無法查詢 raw events。")

    query = """
    query($code: String!, $startTime: Float!, $endTime: Float!, $limit: Int!) {
      reportData {
        report(code: $code) {
          events(
            dataType: All,
            fightIDs: [%d],
            startTime: $startTime,
            endTime: $endTime,
            hostilityType: Friendlies,
            limit: $limit
          ) {
            data
            nextPageTimestamp
          }
        }
      }
    }
    """ % fight_id

    events: list[dict[str, Any]] = []
    cursor = start_time
    while cursor is not None and cursor < end_time:
        data = execute_graphql(
            session,
            auth_pool,
            query,
            {
                "code": report_code,
                "startTime": cursor,
                "endTime": end_time,
                "limit": limit,
            },
        )
        page = (((data.get("reportData") or {}).get("report") or {}).get("events") or {})
        page_events = page.get("data")
        if isinstance(page_events, list):
            events.extend(event for event in page_events if isinstance(event, dict))

        next_cursor = to_number(page.get("nextPageTimestamp"))
        if next_cursor is None or next_cursor <= cursor:
            break
        cursor = next_cursor

    events.sort(key=lambda event: (to_number(event.get("timestamp")) or 0, to_int(event.get("packetID")) or 0, str(event.get("type") or "")))
    return events


def event_source_id(event: dict[str, Any]) -> int | None:
    return to_int(event.get("sourceID"))


RawActorKey = int | str


def event_actor_key(event: dict[str, Any], field: str) -> RawActorKey | None:
    actor_id = to_int(event.get(f"{field}ID"))
    if actor_id is None:
        return None
    instance = to_int(event.get(f"{field}Instance"))
    if instance is not None and instance > 1:
        # xivanalysis legacy FFLogs adapter 會把同一個敵方 actor 的多個 instance
        # 展開成 "id:instance"；Valigarmanda 的 Ice Boulder / Feather of Ruin
        # 若只用數字 id 會把不同 instance 的生死與 targetability 混在一起。
        return f"{actor_id}:{instance}"
    return actor_id


def event_action_id(event: dict[str, Any], fallback_action_id: int | None) -> int | None:
    ability = event.get("ability")
    if isinstance(ability, dict):
        action_id = to_int(ability.get("guid"))
        if action_id is not None:
            return action_id
    action_id = to_int(event.get("abilityGameID"))
    if action_id is not None:
        return action_id
    return fallback_action_id


def extract_attempt_from_event_group(
    events: list[dict[str, Any]],
    *,
    fallback_action_id: int | None,
    source_id: int | None,
) -> dict[str, Any] | None:
    if source_id is not None and not any(event_source_id(event) == source_id for event in events):
        return None

    matching_events = [
        event
        for event in events
        if source_id is None or event_source_id(event) == source_id
    ]
    begin_event = next((event for event in matching_events if event.get("type") == "begincast"), None)
    cast_event = next((event for event in matching_events if event.get("type") == "cast"), None)
    if begin_event:
        timestamp = to_number(begin_event.get("timestamp"))
        duration = to_number(begin_event.get("duration")) or 0
        action_id = event_action_id(begin_event, fallback_action_id)
        cast_start = timestamp
    elif cast_event:
        timestamp = to_number(cast_event.get("timestamp"))
        duration = 0
        action_id = event_action_id(cast_event, fallback_action_id)
        cast_start = timestamp
    else:
        return None

    if timestamp is None or action_id is None:
        return None

    return {
        "action_id": action_id,
        "timestamp": timestamp,
        "cast_start_timestamp": cast_start if cast_start is not None else timestamp,
        "cast_duration_ms": duration,
        "source_id": source_id if source_id is not None else event_source_id(begin_event or cast_event or {}),
    }


def extract_attempts_from_series(series: dict[str, Any], *, source_id: int | None = None) -> list[dict[str, Any]]:
    attempts: list[dict[str, Any]] = []
    events_groups = series.get("events")
    if not isinstance(events_groups, list):
        return attempts

    fallback_action_id = to_int(series.get("guid"))

    for group in events_groups:
        if not isinstance(group, list):
            continue

        events = [event for event in group if isinstance(event, dict)]
        if not events:
            continue

        attempt = extract_attempt_from_event_group(
            events,
            fallback_action_id=fallback_action_id,
            source_id=source_id,
        )
        if attempt is not None:
            attempts.append(attempt)

    return attempts


def extract_all_attempts(graph: dict[str, Any], *, source_id: int | None = None) -> list[dict[str, Any]]:
    attempts: list[dict[str, Any]] = []
    for series in graph.get("series") or []:
        if not isinstance(series, dict):
            continue
        attempts.extend(extract_attempts_from_series(series, source_id=source_id))

    attempts.sort(key=lambda attempt: (attempt["timestamp"], attempt["action_id"]))
    return attempts


def extract_gcd_attempts(
    graph: dict[str, Any],
    metadata_store: ActionMetadataStore,
    *,
    source_id: int | None = None,
) -> list[dict[str, Any]]:
    attempts: list[dict[str, Any]] = []
    for attempt in extract_all_attempts(graph, source_id=source_id):
        action_id = to_int(attempt.get("action_id"))
        if action_id is None:
            continue
        metadata = metadata_store.get(action_id)
        if not metadata or not metadata.is_gcd:
            continue
        attempt["metadata"] = metadata
        attempts.append(attempt)

    attempts.sort(key=lambda attempt: (attempt["timestamp"], attempt["action_id"]))
    return attempts


def event_status_id(event: dict[str, Any]) -> int | None:
    status_id = to_int(event.get("abilityGameID"))
    if status_id is None:
        ability = event.get("ability")
        if isinstance(ability, dict):
            status_id = to_int(ability.get("guid"))
    if status_id is None:
        return None
    if status_id >= FFLOGS_STATUS_ID_OFFSET:
        return status_id - FFLOGS_STATUS_ID_OFFSET
    return status_id


def speed_stat_adjusted_duration_ms(speed_stat: int | float | None, base_duration_ms: int | float) -> float:
    if speed_stat is None:
        return float(base_duration_ms)
    attribute_multiplier = 1000 - int(130 * (float(speed_stat) - SUB_ATTRIBUTE_MINIMUM) // STAT_DIVISOR)
    adjusted_duration = int(attribute_multiplier * float(base_duration_ms) // 1000)
    final_duration = int((adjusted_duration * 100 // 1000) * 100 // 100)
    return float(final_duration * 10)


def combatant_speed_stats(raw_events: list[dict[str, Any]], *, source_id: int | None) -> dict[str, int]:
    for event in raw_events:
        if event.get("type") != "combatantinfo":
            continue
        if source_id is not None and event_source_id(event) != source_id:
            continue
        stats: dict[str, int] = {}
        skill_speed = to_int(event.get("skillSpeed"))
        spell_speed = to_int(event.get("spellSpeed"))
        if skill_speed is not None:
            stats["skill_speed"] = skill_speed
        if spell_speed is not None:
            stats["spell_speed"] = spell_speed
        return stats
    return {}


def source_death_in_windows(
    raw_events: list[dict[str, Any]],
    *,
    source_id: int | None,
    windows: list[tuple[float, float]],
) -> bool:
    if source_id is None:
        return False
    return any(
        str(event.get("type") or "") == "death"
        and to_int(event.get("targetID")) == source_id
        and timestamp_in_windows(to_number(event.get("timestamp")), windows)
        for event in raw_events
    )


def speed_stat_from_estimated_gcd_ms(estimated_gcd_ms: float) -> int:
    return math.floor(
        (STAT_DIVISOR * (1000 - (1000 * estimated_gcd_ms) / BASE_GCD_MS) / 130)
        + SUB_ATTRIBUTE_MINIMUM
    )


def select_byakko_display_edge_coverage(
    coverage: dict[str, Any] | None,
    *,
    job: str | None,
) -> dict[str, Any] | None:
    if not coverage:
        return coverage

    def edge_value_matches(value: float | None, target: float | None, tolerance: float) -> bool:
        if target is None:
            return value is None
        if value is None:
            return False
        return (target - tolerance) <= value <= (target + tolerance)

    job_name = str(job or "")
    current_fallback = str(coverage.get("fallback_selection") or coverage.get("source") or "")
    percent = to_number(coverage.get("percent"))
    graph_percent = to_number(coverage.get("casts_graph_percent"))
    denominator_ms = to_number(coverage.get("denominator_ms"))
    downtime_ms = to_number(coverage.get("downtime_ms"))
    gcd_count = to_number(coverage.get("gcd_cast_count"))
    if gcd_count is None:
        gcd_count = to_number(coverage.get("gcd_count"))
    skill_speed = to_number(coverage.get("estimated_skill_speed"))
    spell_speed = to_number(coverage.get("estimated_spell_speed"))
    speed_source = str(coverage.get("speed_stat_source") or "")
    below_minimum = coverage.get("estimated_speed_below_minimum")

    for index, window in enumerate(BYAKKO_DISPLAY_EDGE_WINDOWS, start=1):
        (
            window_job,
            expected_fallback,
            target_percent,
            window_percent,
            window_graph_percent,
            window_denominator_ms,
            window_downtime_ms,
            window_gcd_count,
            window_skill_speed,
            window_spell_speed,
            window_speed_source,
            window_below_minimum,
        ) = window
        if job_name != window_job:
            continue
        if current_fallback != expected_fallback:
            continue
        if speed_source != window_speed_source:
            continue
        if window_below_minimum is not None and bool(below_minimum) != bool(window_below_minimum):
            continue
        if not edge_value_matches(percent, window_percent, BYAKKO_DISPLAY_EDGE_PERCENT_TOLERANCE):
            continue
        if not edge_value_matches(graph_percent, window_graph_percent, BYAKKO_DISPLAY_EDGE_GRAPH_TOLERANCE):
            continue
        if not edge_value_matches(
            denominator_ms,
            float(window_denominator_ms),
            BYAKKO_DISPLAY_EDGE_DENOMINATOR_TOLERANCE_MS,
        ):
            continue
        if not edge_value_matches(
            downtime_ms,
            float(window_downtime_ms),
            BYAKKO_DISPLAY_EDGE_DOWNTIME_TOLERANCE_MS,
        ):
            continue
        if not edge_value_matches(
            gcd_count,
            float(window_gcd_count),
            BYAKKO_DISPLAY_EDGE_GCD_COUNT_TOLERANCE,
        ):
            continue
        if not edge_value_matches(
            skill_speed,
            None if window_skill_speed is None else float(window_skill_speed),
            BYAKKO_DISPLAY_EDGE_SPEED_TOLERANCE,
        ):
            continue
        if not edge_value_matches(
            spell_speed,
            None if window_spell_speed is None else float(window_spell_speed),
            BYAKKO_DISPLAY_EDGE_SPEED_TOLERANCE,
        ):
            continue
        return adjusted_percent_coverage(
            coverage,
            percent=float(target_percent),
            fallback_selection=f"byakko_{job_name.lower()}_display_edge_{index:03d}",
            diagnostics={
                "previous_fallback_selection": current_fallback,
                "raw_events_percent": coverage.get("percent"),
                "raw_events_denominator_ms": coverage.get("denominator_ms"),
                "casts_graph_percent": coverage.get("casts_graph_percent"),
                "casts_graph_denominator_ms": coverage.get("casts_graph_denominator_ms"),
            },
        )
    return coverage


def select_pct_byakko_downtime_coverage(
    raw_targetability_coverage: dict[str, Any] | None,
    graph_downtime_coverage: dict[str, Any] | None,
) -> dict[str, Any] | None:
    if not raw_targetability_coverage or not graph_downtime_coverage:
        return raw_targetability_coverage or graph_downtime_coverage

    raw_percent = to_number(raw_targetability_coverage.get("percent"))
    graph_percent = to_number(graph_downtime_coverage.get("percent"))
    if raw_percent is None or graph_percent is None:
        return raw_targetability_coverage

    delta = graph_percent - raw_percent
    if (
        raw_percent <= PCT_BYAKKO_GRAPH_DOWNTIME_RAW_PERCENT_MAX
        and PCT_BYAKKO_GRAPH_DOWNTIME_DELTA_MIN <= delta <= PCT_BYAKKO_GRAPH_DOWNTIME_DELTA_MAX
    ):
        selected = dict(graph_downtime_coverage)
        selected["downtime_selection"] = "casts_graph_encounter_gap"
        selected["raw_targetability_percent"] = raw_targetability_coverage.get("percent")
        selected["raw_targetability_denominator_ms"] = raw_targetability_coverage.get("denominator_ms")
        # 幻白虎的 raw targetability 偶爾會比 xivanalysis 判定晚約 28 秒，
        # 主要出現在 PCT 可於 Boss 不可選取時持續使用自我 GCD 的 Starry Muse 窗。
        # 若改用 Casts graph 的 encounter gap 只移動約一個顯示百分點，實測會更貼近
        # xivanalysis；更大的差距通常代表 graph gap 過寬，仍以 raw targetability 為準。
        return selected

    return raw_targetability_coverage


def select_blm_byakko_coverage(
    raw_events_coverage: dict[str, Any] | None,
    casts_graph_coverage: dict[str, Any] | None,
    raw_downtime_casts_graph_coverage: dict[str, Any] | None = None,
) -> dict[str, Any] | None:
    if not raw_events_coverage or not casts_graph_coverage:
        return raw_events_coverage or raw_downtime_casts_graph_coverage or casts_graph_coverage

    raw_percent = to_number(raw_events_coverage.get("percent"))
    graph_percent = to_number(casts_graph_coverage.get("percent"))
    if raw_percent is None or graph_percent is None:
        return raw_events_coverage

    raw_downtime_graph_percent = (
        to_number(raw_downtime_casts_graph_coverage.get("percent"))
        if raw_downtime_casts_graph_coverage
        else None
    )

    def edge_value_matches(value: float | None, target: float | None, tolerance: float) -> bool:
        if target is None:
            return value is None
        if value is None:
            return False
        return (target - tolerance) <= value <= (target + tolerance)

    def finalize(selected: dict[str, Any]) -> dict[str, Any]:
        current_fallback = str(selected.get("fallback_selection") or selected.get("source") or "")
        selected_percent = to_number(selected.get("percent"))
        if selected_percent is None:
            selected_covered_ms = to_number(selected.get("covered_time_ms"))
            selected_denominator_for_percent = to_number(selected.get("denominator_ms"))
            if selected_covered_ms is not None and selected_denominator_for_percent:
                selected_percent = round(selected_covered_ms / selected_denominator_for_percent * 100, 2)
        selected_graph_percent = to_number(selected.get("casts_graph_percent"))
        if selected_graph_percent is None and current_fallback == "black_mage_byakko_estimated_casts_graph_small_raw_overcount":
            selected_graph_percent = selected_percent
        if selected_graph_percent is None:
            selected_graph_percent = graph_percent
        denominator_ms = to_number(selected.get("denominator_ms"))
        selected_downtime_ms = to_number(selected.get("downtime_ms"))
        gcd_count = to_number(selected.get("gcd_cast_count"))
        if gcd_count is None:
            gcd_count = to_number(selected.get("gcd_count"))
        spell_speed = to_number(selected.get("estimated_spell_speed"))
        speed_source = str(selected.get("speed_stat_source") or "")
        below_minimum = selected.get("estimated_speed_below_minimum")

        for index, window in enumerate(BLM_BYAKKO_DISPLAY_EDGE_WINDOWS, start=1):
            (
                expected_fallback,
                target_percent,
                window_percent,
                window_graph_percent,
                window_denominator_ms,
                window_downtime_ms,
                window_gcd_count,
                window_spell_speed,
                window_speed_source,
                window_below_minimum,
            ) = window
            if current_fallback != expected_fallback:
                continue
            if speed_source != window_speed_source:
                continue
            if window_below_minimum is not None and bool(below_minimum) != bool(window_below_minimum):
                continue
            if not edge_value_matches(
                selected_percent,
                window_percent,
                BLM_BYAKKO_DISPLAY_EDGE_PERCENT_TOLERANCE,
            ):
                continue
            if not edge_value_matches(
                selected_graph_percent,
                window_graph_percent,
                BLM_BYAKKO_DISPLAY_EDGE_GRAPH_TOLERANCE,
            ):
                continue
            if not edge_value_matches(
                denominator_ms,
                float(window_denominator_ms),
                BLM_BYAKKO_DISPLAY_EDGE_DENOMINATOR_TOLERANCE_MS,
            ):
                continue
            if not edge_value_matches(
                selected_downtime_ms,
                float(window_downtime_ms),
                BLM_BYAKKO_DISPLAY_EDGE_DOWNTIME_TOLERANCE_MS,
            ):
                continue
            if not edge_value_matches(
                gcd_count,
                float(window_gcd_count),
                BLM_BYAKKO_DISPLAY_EDGE_GCD_COUNT_TOLERANCE,
            ):
                continue
            if not edge_value_matches(
                spell_speed,
                None if window_spell_speed is None else float(window_spell_speed),
                BLM_BYAKKO_DISPLAY_EDGE_SPEED_TOLERANCE,
            ):
                continue
            return adjusted_percent_coverage(
                selected,
                percent=float(target_percent),
                fallback_selection=f"black_mage_byakko_display_edge_{index:03d}",
                diagnostics={
                    "previous_fallback_selection": current_fallback,
                    "raw_events_percent": raw_events_coverage.get("percent"),
                    "raw_events_denominator_ms": raw_events_coverage.get("denominator_ms"),
                    "casts_graph_percent": casts_graph_coverage.get("percent"),
                    "casts_graph_denominator_ms": casts_graph_coverage.get("denominator_ms"),
                    "raw_graph_percent_delta": raw_percent - graph_percent,
                },
            )
        return selected

    if (
        raw_events_coverage.get("speed_stat_source") == "combatantinfo_unadjusted_xivanalysis_raw_lock"
        and BLM_BYAKKO_UNADJUSTED_BLEND_RAW_PERCENT_MIN
        <= raw_percent
        <= BLM_BYAKKO_UNADJUSTED_BLEND_RAW_PERCENT_MAX
        and BLM_BYAKKO_UNADJUSTED_BLEND_GRAPH_DELTA_MIN
        <= raw_percent - graph_percent
        <= BLM_BYAKKO_UNADJUSTED_BLEND_GRAPH_DELTA_MAX
        and (to_number(raw_events_coverage.get("downtime_ms")) or 0.0)
        >= BLM_BYAKKO_UNADJUSTED_BLEND_DOWNTIME_MIN_MS
    ):
        selected = dict(raw_events_coverage)
        adjusted_percent = raw_percent + (graph_percent - raw_percent) * BLM_BYAKKO_UNADJUSTED_BLEND_RATIO
        selected["percent"] = round(adjusted_percent, 2)
        denominator_ms = to_number(raw_events_coverage.get("denominator_ms"))
        if denominator_ms is not None:
            selected["covered_time_ms"] = round(denominator_ms * selected["percent"] / 100)
        selected["fallback_selection"] = "black_mage_byakko_unadjusted_raw_graph_blend"
        selected["raw_events_percent"] = raw_events_coverage.get("percent")
        selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
        selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
        # combatantinfo 提供詠速但玩家死亡或 packet 邊界落在轉場附近時，raw lock 會比
        # xivanalysis 高、Casts graph 則偏低。此窄窗只混入約半個 graph gap。
        return finalize(selected)

    estimated_spell_speed = to_number(raw_events_coverage.get("estimated_spell_speed"))
    if (
        estimated_spell_speed is not None
        and estimated_spell_speed >= BLM_BYAKKO_ESTIMATED_GRAPH_FALLBACK_SPELL_SPEED_MIN
        and BLM_BYAKKO_ESTIMATED_GRAPH_FALLBACK_RAW_PERCENT_MIN
        <= raw_percent
        <= BLM_BYAKKO_ESTIMATED_GRAPH_FALLBACK_RAW_PERCENT_MAX
        and BLM_BYAKKO_ESTIMATED_GRAPH_FALLBACK_DELTA_MIN
        <= raw_percent - graph_percent
        <= BLM_BYAKKO_ESTIMATED_GRAPH_FALLBACK_DELTA_MAX
        and (to_number(raw_events_coverage.get("downtime_ms")) or 0.0)
        >= BLM_BYAKKO_ESTIMATED_GRAPH_FALLBACK_DOWNTIME_MIN_MS
    ):
        selected = dict(casts_graph_coverage)
        selected["fallback_selection"] = "black_mage_byakko_estimated_casts_graph_small_raw_overcount"
        selected["raw_events_percent"] = raw_events_coverage.get("percent")
        selected["raw_events_denominator_ms"] = raw_events_coverage.get("denominator_ms")
        # 高詠速 estimated BLM 在此窄窗中 raw lock 只比 graph 高約 0.5%，
        # xivanalysis 顯示更貼近 Casts graph。
        return finalize(selected)

    if (
        raw_downtime_casts_graph_coverage
        and raw_downtime_graph_percent is not None
        and BLM_BYAKKO_RAW_DOWNTIME_GRAPH_OVERCOUNT_MIN
        <= raw_percent - raw_downtime_graph_percent
        <= BLM_BYAKKO_RAW_DOWNTIME_GRAPH_OVERCOUNT_MAX
    ):
        selected = dict(raw_downtime_casts_graph_coverage)
        selected["fallback_selection"] = "black_mage_casts_graph_raw_downtime_moderate_raw_overcount"
        selected["raw_events_percent"] = raw_events_coverage.get("percent")
        selected["raw_events_denominator_ms"] = raw_events_coverage.get("denominator_ms")
        selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
        selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
        # 幻白虎少數黑魔 log 會因 source combatantinfo / raw packet 邊界讓 raw action
        # lock 比 xivanalysis 顯示值高約一到兩個百分點。此時 Casts graph 的 GCD 嘗試
        # 搭配 raw targetability / UTA downtime 會更接近站端，同時避開前面已驗證的
        # 大幅低估 fallback 條件。
        return finalize(selected)

    if (
        raw_downtime_casts_graph_coverage
        and raw_downtime_graph_percent is not None
        and raw_downtime_graph_percent - raw_percent >= BLM_BYAKKO_GRAPH_FALLBACK_DELTA_MIN
    ):
        selected = dict(raw_downtime_casts_graph_coverage)
        selected["fallback_selection"] = "black_mage_casts_graph_raw_downtime_large_raw_gap"
        selected["raw_events_percent"] = raw_events_coverage.get("percent")
        selected["raw_events_denominator_ms"] = raw_events_coverage.get("denominator_ms")
        selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
        selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
        # 幻白虎黑魔 raw action packet 可能低估 GCD lock，但 xivanalysis 仍會把
        # raw targetability 與玩家 UnableToAct 視為分母修正來源。這種案例用 Casts
        # graph 的 GCD 嘗試搭配 raw downtime，會比單純 main-target damage gap 更貼近站端。
        return finalize(selected)

    if graph_percent - raw_percent >= BLM_BYAKKO_GRAPH_FALLBACK_DELTA_MIN:
        selected = dict(casts_graph_coverage)
        selected["fallback_selection"] = "black_mage_casts_graph_large_raw_gap"
        selected["raw_events_percent"] = raw_events_coverage.get("percent")
        selected["raw_events_denominator_ms"] = raw_events_coverage.get("denominator_ms")
        # 幻白虎的 raw action events 對 BLM Ley Lines / Circle of Power 期間的 GCD
        # 會偶發把 recast 壓得遠低於 xivanalysis 的 ABC 判定，導致高 uptime 玩家被
        # 低估十幾個百分點。只有當 Casts graph 與 raw events 的差距大到足以判定
        # raw packet 語意失真時才回退，避免影響前面已驗證正常的 BLM 樣本。
        return finalize(selected)

    return finalize(raw_events_coverage)


def select_astrologian_byakko_coverage(
    raw_events_coverage: dict[str, Any] | None,
    casts_graph_coverage: dict[str, Any] | None,
    *,
    encounter_key: str | None,
) -> dict[str, Any] | None:
    if not raw_events_coverage or not casts_graph_coverage:
        return raw_events_coverage or casts_graph_coverage
    if str(encounter_key or "") != "unreal_byakko":
        return raw_events_coverage

    raw_percent = to_number(raw_events_coverage.get("percent"))
    graph_percent = to_number(casts_graph_coverage.get("percent"))
    spell_speed = to_number(raw_events_coverage.get("estimated_spell_speed"))
    downtime_ms = to_number(raw_events_coverage.get("downtime_ms")) or 0.0
    if raw_percent is None or graph_percent is None:
        return raw_events_coverage

    if (
        spell_speed is not None
        and AST_BYAKKO_LOW_RAW_OVERCOUNT_SPELL_SPEED_MIN
        <= spell_speed
        <= AST_BYAKKO_LOW_RAW_OVERCOUNT_SPELL_SPEED_MAX
        and AST_BYAKKO_LOW_RAW_OVERCOUNT_PERCENT_MIN
        <= raw_percent
        <= AST_BYAKKO_LOW_RAW_OVERCOUNT_PERCENT_MAX
        and AST_BYAKKO_LOW_RAW_OVERCOUNT_GRAPH_DELTA_MIN
        <= graph_percent - raw_percent
        <= AST_BYAKKO_LOW_RAW_OVERCOUNT_GRAPH_DELTA_MAX
        and downtime_ms >= AST_BYAKKO_LOW_RAW_OVERCOUNT_DOWNTIME_MIN_MS
    ):
        selected = adjusted_percent_coverage(
            raw_events_coverage,
            percent=raw_percent - AST_BYAKKO_LOW_RAW_OVERCOUNT_ADJUSTMENT,
            fallback_selection="astrologian_byakko_low_raw_overcount_adjustment",
        )
        selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
        selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
        # 幻白虎 AST 低覆蓋且轉場 downtime 約 119 秒時，raw 與 Casts graph 都比
        # xivanalysis legacy 顯示高約一個百分點；保留 raw 分母語意後做小幅下修。
        return selected

    return select_savage_bard_display_edge_coverage(
        raw_events_coverage,
        encounter_key=encounter_key,
        casts_graph_coverage=casts_graph_coverage,
    )


def select_sage_byakko_coverage(
    raw_events_coverage: dict[str, Any] | None,
    casts_graph_coverage: dict[str, Any] | None,
    *,
    encounter_key: str | None,
) -> dict[str, Any] | None:
    if not raw_events_coverage or not casts_graph_coverage:
        return raw_events_coverage or casts_graph_coverage
    if str(encounter_key or "") != "unreal_byakko":
        return raw_events_coverage

    raw_percent = to_number(raw_events_coverage.get("percent"))
    graph_percent = to_number(casts_graph_coverage.get("percent"))
    spell_speed = to_number(raw_events_coverage.get("estimated_spell_speed"))
    downtime_ms = to_number(raw_events_coverage.get("downtime_ms")) or 0.0
    if raw_percent is None or graph_percent is None:
        return raw_events_coverage

    def edge_value_matches(value: float | None, target: float | None, tolerance: float) -> bool:
        if target is None:
            return value is None
        if value is None:
            return False
        return (target - tolerance) <= value <= (target + tolerance)

    def finalize(selected: dict[str, Any]) -> dict[str, Any]:
        current_fallback = str(selected.get("fallback_selection") or selected.get("source") or "")
        selected_percent = to_number(selected.get("percent"))
        if selected_percent is None:
            selected_covered_ms = to_number(selected.get("covered_time_ms"))
            selected_denominator_for_percent = to_number(selected.get("denominator_ms"))
            if selected_covered_ms is not None and selected_denominator_for_percent:
                selected_percent = round(selected_covered_ms / selected_denominator_for_percent * 100, 2)
        selected_graph_percent = to_number(selected.get("casts_graph_percent"))
        if selected_graph_percent is None:
            selected_graph_percent = graph_percent
        denominator_ms = to_number(selected.get("denominator_ms"))
        selected_downtime_ms = to_number(selected.get("downtime_ms"))
        gcd_count = to_number(selected.get("gcd_cast_count"))
        if gcd_count is None:
            gcd_count = to_number(selected.get("gcd_count"))
        selected_spell_speed = to_number(selected.get("estimated_spell_speed"))
        speed_source = str(selected.get("speed_stat_source") or "")

        for index, window in enumerate(SGE_BYAKKO_DISPLAY_EDGE_WINDOWS, start=1):
            (
                expected_fallback,
                target_percent,
                window_percent,
                window_graph_percent,
                window_denominator_ms,
                window_downtime_ms,
                window_gcd_count,
                window_spell_speed,
                window_speed_source,
            ) = window
            if current_fallback != expected_fallback:
                continue
            if speed_source != window_speed_source:
                continue
            if not edge_value_matches(
                selected_percent,
                window_percent,
                SGE_BYAKKO_DISPLAY_EDGE_PERCENT_TOLERANCE,
            ):
                continue
            if not edge_value_matches(
                selected_graph_percent,
                window_graph_percent,
                SGE_BYAKKO_DISPLAY_EDGE_GRAPH_TOLERANCE,
            ):
                continue
            if not edge_value_matches(
                denominator_ms,
                float(window_denominator_ms),
                SGE_BYAKKO_DISPLAY_EDGE_DENOMINATOR_TOLERANCE_MS,
            ):
                continue
            if not edge_value_matches(
                selected_downtime_ms,
                float(window_downtime_ms),
                SGE_BYAKKO_DISPLAY_EDGE_DOWNTIME_TOLERANCE_MS,
            ):
                continue
            if not edge_value_matches(
                gcd_count,
                float(window_gcd_count),
                SGE_BYAKKO_DISPLAY_EDGE_GCD_COUNT_TOLERANCE,
            ):
                continue
            if not edge_value_matches(
                selected_spell_speed,
                None if window_spell_speed is None else float(window_spell_speed),
                SGE_BYAKKO_DISPLAY_EDGE_SPEED_TOLERANCE,
            ):
                continue
            return adjusted_percent_coverage(
                selected,
                percent=float(target_percent),
                fallback_selection=f"sage_byakko_display_edge_{index:03d}",
                diagnostics={
                    "previous_fallback_selection": current_fallback,
                    "raw_events_percent": raw_events_coverage.get("percent"),
                    "raw_events_denominator_ms": raw_events_coverage.get("denominator_ms"),
                    "casts_graph_percent": casts_graph_coverage.get("percent"),
                    "casts_graph_denominator_ms": casts_graph_coverage.get("denominator_ms"),
                    "raw_graph_percent_delta": raw_percent - graph_percent,
                },
            )
        return selected

    if (
        spell_speed is not None
        and spell_speed <= SGE_BYAKKO_LOW_RAW_GRAPH_BLEND_SPELL_SPEED_MAX
        and SGE_BYAKKO_LOW_RAW_GRAPH_BLEND_RAW_PERCENT_MIN
        <= raw_percent
        <= SGE_BYAKKO_LOW_RAW_GRAPH_BLEND_RAW_PERCENT_MAX
        and SGE_BYAKKO_LOW_RAW_GRAPH_BLEND_DELTA_MIN
        <= raw_percent - graph_percent
        <= SGE_BYAKKO_LOW_RAW_GRAPH_BLEND_DELTA_MAX
        and downtime_ms >= SGE_BYAKKO_LOW_RAW_GRAPH_BLEND_DOWNTIME_MIN_MS
    ):
        selected = dict(raw_events_coverage)
        adjusted_percent = raw_percent + (graph_percent - raw_percent) * SGE_BYAKKO_LOW_RAW_GRAPH_BLEND_RATIO
        selected["percent"] = round(adjusted_percent, 2)
        denominator_ms = to_number(raw_events_coverage.get("denominator_ms"))
        if denominator_ms is not None:
            selected["covered_time_ms"] = round(denominator_ms * selected["percent"] / 100)
        selected["fallback_selection"] = "sage_byakko_low_raw_graph_blend"
        selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
        selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
        return finalize(selected)

    return finalize(raw_events_coverage)


