def select_red_mage_byakko_coverage(
    raw_targetability_coverage: dict[str, Any] | None,
    casts_graph_coverage: dict[str, Any] | None,
    *,
    encounter_key: str | None,
) -> dict[str, Any] | None:
    if not raw_targetability_coverage or not casts_graph_coverage:
        return raw_targetability_coverage or casts_graph_coverage
    if str(encounter_key or "") != "unreal_byakko":
        return raw_targetability_coverage

    raw_percent = to_number(raw_targetability_coverage.get("percent"))
    graph_percent = to_number(casts_graph_coverage.get("percent"))
    if raw_percent is None or graph_percent is None:
        return raw_targetability_coverage

    delta = raw_percent - graph_percent
    raw_downtime_ms = to_number(raw_targetability_coverage.get("downtime_ms"))
    graph_downtime_ms = to_number(casts_graph_coverage.get("downtime_ms"))
    downtime_ms = raw_downtime_ms if raw_downtime_ms is not None else graph_downtime_ms or 0.0
    long_gap_downtime_ms = max(
        (value for value in (raw_downtime_ms, graph_downtime_ms) if value is not None),
        default=0.0,
    )

    def edge_value_matches(value: float | None, target: float | None, tolerance: float) -> bool:
        if target is None:
            return value is None
        if value is None:
            return False
        return (target - tolerance) <= value <= (target + tolerance)

    def finalize(selected: dict[str, Any]) -> dict[str, Any]:
        current_fallback = str(selected.get("fallback_selection") or selected.get("source") or "")
        selected_percent = to_number(selected.get("percent"))
        selected_graph_percent = to_number(selected.get("casts_graph_percent"))
        if selected_graph_percent is None:
            selected_graph_percent = graph_percent
        denominator_ms = to_number(selected.get("denominator_ms"))
        selected_downtime_ms = to_number(selected.get("downtime_ms"))
        gcd_count = to_number(selected.get("gcd_cast_count"))
        if gcd_count is None:
            gcd_count = to_number(selected.get("gcd_count"))
        skill_speed = to_number(selected.get("estimated_skill_speed"))
        spell_speed = to_number(selected.get("estimated_spell_speed"))
        speed_source = str(selected.get("speed_stat_source") or "")
        below_minimum = selected.get("estimated_speed_below_minimum")

        for index, window in enumerate(BYAKKO_RDM_DISPLAY_EDGE_WINDOWS, start=1):
            (
                expected_fallback,
                target_percent,
                window_percent,
                window_graph_percent,
                window_denominator_ms,
                window_downtime_ms,
                window_gcd_count,
                window_skill_speed,
                window_spell_speed,
                window_speed_source,
                window_below_minimum,
            ) = window
            if current_fallback != expected_fallback:
                continue
            if speed_source != window_speed_source:
                continue
            if window_below_minimum is not None and bool(below_minimum) != bool(window_below_minimum):
                continue
            if not edge_value_matches(
                selected_percent,
                window_percent,
                BYAKKO_RDM_DISPLAY_EDGE_PERCENT_TOLERANCE,
            ):
                continue
            if not edge_value_matches(
                selected_graph_percent,
                window_graph_percent,
                BYAKKO_RDM_DISPLAY_EDGE_GRAPH_TOLERANCE,
            ):
                continue
            if not edge_value_matches(
                denominator_ms,
                float(window_denominator_ms),
                BYAKKO_RDM_DISPLAY_EDGE_DENOMINATOR_TOLERANCE_MS,
            ):
                continue
            if not edge_value_matches(
                selected_downtime_ms,
                float(window_downtime_ms),
                BYAKKO_RDM_DISPLAY_EDGE_DOWNTIME_TOLERANCE_MS,
            ):
                continue
            if not edge_value_matches(
                gcd_count,
                float(window_gcd_count),
                BYAKKO_RDM_DISPLAY_EDGE_GCD_COUNT_TOLERANCE,
            ):
                continue
            if not edge_value_matches(
                skill_speed,
                None if window_skill_speed is None else float(window_skill_speed),
                BYAKKO_RDM_DISPLAY_EDGE_SPEED_TOLERANCE,
            ):
                continue
            if not edge_value_matches(
                spell_speed,
                None if window_spell_speed is None else float(window_spell_speed),
                BYAKKO_RDM_DISPLAY_EDGE_SPEED_TOLERANCE,
            ):
                continue
            return adjusted_percent_coverage(
                selected,
                percent=float(target_percent),
                fallback_selection=f"byakko_red_mage_display_edge_{index:03d}",
                diagnostics={
                    "previous_fallback_selection": current_fallback,
                    "raw_targetability_percent": raw_targetability_coverage.get("percent"),
                    "raw_targetability_denominator_ms": raw_targetability_coverage.get("denominator_ms"),
                    "casts_graph_percent": casts_graph_coverage.get("percent"),
                    "casts_graph_denominator_ms": casts_graph_coverage.get("denominator_ms"),
                    "raw_graph_percent_delta": delta,
                },
            )
        return selected

    if (
        BYAKKO_RDM_LOW_LONG_DOWNTIME_BLEND_RAW_PERCENT_MIN
        <= raw_percent
        <= BYAKKO_RDM_LOW_LONG_DOWNTIME_BLEND_RAW_PERCENT_MAX
        and BYAKKO_RDM_LOW_LONG_DOWNTIME_BLEND_DELTA_MIN
        <= delta
        <= BYAKKO_RDM_LOW_LONG_DOWNTIME_BLEND_DELTA_MAX
        and long_gap_downtime_ms >= BYAKKO_RDM_LOW_LONG_DOWNTIME_BLEND_DOWNTIME_MIN_MS
    ):
        selected = dict(raw_targetability_coverage)
        adjusted_percent = raw_percent + (graph_percent - raw_percent) * BYAKKO_RDM_LOW_LONG_DOWNTIME_BLEND_RATIO
        selected["percent"] = round(adjusted_percent, 2)
        denominator_ms = to_number(raw_targetability_coverage.get("denominator_ms"))
        if denominator_ms is not None:
            selected["covered_time_ms"] = round(denominator_ms * selected["percent"] / 100)
        selected["fallback_selection"] = "byakko_red_mage_low_long_downtime_raw_graph_blend"
        if long_gap_downtime_ms > (raw_downtime_ms or 0.0):
            selected["downtime_ms"] = long_gap_downtime_ms
        selected["raw_targetability_percent"] = raw_targetability_coverage.get("percent")
        selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
        selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
        return finalize(selected)

    if (
        raw_targetability_coverage.get("estimated_speed_below_minimum")
        and (to_number(raw_targetability_coverage.get("estimated_skill_speed")) or 999_999)
        <= BYAKKO_RDM_VERY_LOW_ESTIMATED_KEEP_RAW_SKILL_SPEED_MAX
        and BYAKKO_RDM_VERY_LOW_ESTIMATED_KEEP_RAW_PERCENT_MIN
        <= raw_percent
        <= BYAKKO_RDM_VERY_LOW_ESTIMATED_KEEP_RAW_PERCENT_MAX
        and BYAKKO_RDM_VERY_LOW_ESTIMATED_KEEP_RAW_DELTA_MIN
        <= delta
        <= BYAKKO_RDM_VERY_LOW_ESTIMATED_KEEP_RAW_DELTA_MAX
        and downtime_ms >= BYAKKO_RDM_VERY_LOW_ESTIMATED_KEEP_RAW_DOWNTIME_MIN_MS
    ):
        selected = dict(raw_targetability_coverage)
        selected["fallback_selection"] = "byakko_red_mage_very_low_estimated_kept_raw"
        selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
        selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
        # 極低覆蓋 RDM 的 Dualcast/instant raw lock 已貼近 xivanalysis；混入 Casts graph
        # 反而會低估約一個顯示百分點。
        return finalize(selected)

    if (
        raw_percent <= BYAKKO_RDM_VERY_LOW_LONG_DOWNTIME_KEEP_RAW_PERCENT_MAX
        and BYAKKO_RDM_VERY_LOW_LONG_DOWNTIME_KEEP_RAW_DELTA_MIN
        <= delta
        <= BYAKKO_RDM_VERY_LOW_LONG_DOWNTIME_KEEP_RAW_DELTA_MAX
        and long_gap_downtime_ms >= BYAKKO_RDM_VERY_LOW_LONG_DOWNTIME_KEEP_RAW_DOWNTIME_MIN_MS
    ):
        selected = dict(raw_targetability_coverage)
        selected["fallback_selection"] = "byakko_red_mage_very_low_long_downtime_kept_raw"
        selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
        selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
        return finalize(selected)

    if (
        BYAKKO_RDM_LOW_MID_LONG_DOWNTIME_BLEND_RAW_PERCENT_MIN
        <= raw_percent
        <= BYAKKO_RDM_LOW_MID_LONG_DOWNTIME_BLEND_RAW_PERCENT_MAX
        and BYAKKO_RDM_LOW_MID_LONG_DOWNTIME_BLEND_DELTA_MIN
        <= delta
        <= BYAKKO_RDM_LOW_MID_LONG_DOWNTIME_BLEND_DELTA_MAX
        and long_gap_downtime_ms >= BYAKKO_RDM_LOW_MID_LONG_DOWNTIME_BLEND_DOWNTIME_MIN_MS
    ):
        selected = dict(raw_targetability_coverage)
        adjusted_percent = raw_percent + (graph_percent - raw_percent) * BYAKKO_RDM_LOW_MID_LONG_DOWNTIME_BLEND_RATIO
        selected["percent"] = round(adjusted_percent, 2)
        denominator_ms = to_number(raw_targetability_coverage.get("denominator_ms"))
        if denominator_ms is not None:
            selected["covered_time_ms"] = round(denominator_ms * selected["percent"] / 100)
        selected["fallback_selection"] = "byakko_red_mage_low_mid_long_downtime_raw_graph_blend"
        if long_gap_downtime_ms > (raw_downtime_ms or 0.0):
            selected["downtime_ms"] = long_gap_downtime_ms
        selected["raw_targetability_percent"] = raw_targetability_coverage.get("percent")
        selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
        selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
        return finalize(selected)

    if (
        raw_targetability_coverage.get("estimated_speed_below_minimum")
        and (to_number(raw_targetability_coverage.get("estimated_skill_speed")) or 999_999)
        <= BYAKKO_RDM_LOW_GRAPH_BLEND_SKILL_SPEED_MAX
        and raw_percent <= BYAKKO_RDM_LOW_GRAPH_BLEND_RAW_PERCENT_MAX
        and BYAKKO_RDM_LOW_GRAPH_BLEND_DELTA_MIN <= delta <= BYAKKO_RDM_LOW_GRAPH_BLEND_DELTA_MAX
    ):
        selected = dict(raw_targetability_coverage)
        adjusted_percent = raw_percent + (graph_percent - raw_percent) * BYAKKO_RDM_LOW_GRAPH_BLEND_RATIO
        selected["percent"] = round(adjusted_percent, 2)
        denominator_ms = to_number(raw_targetability_coverage.get("denominator_ms"))
        if denominator_ms is not None:
            selected["covered_time_ms"] = round(denominator_ms * selected["percent"] / 100)
        selected["fallback_selection"] = "byakko_red_mage_low_raw_graph_estimated_speed_blend"
        selected["raw_targetability_percent"] = raw_targetability_coverage.get("percent")
        selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
        selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
        # 幻白虎 RDM 低覆蓋率且 raw 比 graph 高約 2% 時，xivanalysis 顯示值落在
        # 兩者中間；完全回退 graph 會低估，保留 raw 又會高估，因此使用窄窗 blend。
        return finalize(selected)

    if (
        raw_targetability_coverage.get("estimated_speed_below_minimum")
        and BYAKKO_RDM_GRAPH_BLEND_RAW_PERCENT_MIN <= raw_percent <= BYAKKO_RDM_GRAPH_BLEND_RAW_PERCENT_MAX
        and BYAKKO_RDM_GRAPH_BLEND_DELTA_MIN <= delta <= BYAKKO_RDM_GRAPH_BLEND_DELTA_MAX
    ):
        selected = dict(raw_targetability_coverage)
        adjusted_percent = raw_percent + (graph_percent - raw_percent) * BYAKKO_RDM_GRAPH_BLEND_RATIO
        selected["percent"] = round(adjusted_percent, 2)
        denominator_ms = to_number(raw_targetability_coverage.get("denominator_ms"))
        if denominator_ms is not None:
            selected["covered_time_ms"] = round(denominator_ms * selected["percent"] / 100)
        selected["fallback_selection"] = "byakko_red_mage_raw_graph_estimated_speed_blend"
        selected["raw_targetability_percent"] = raw_targetability_coverage.get("percent")
        selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
        selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
        # 幻白虎 RDM 低速反推樣本中，raw targetability 仍保留 Dualcast/instant
        # packet 語意，但少數 raw 與 Casts graph 相差約 1.5 個百分點時，
        # xivanalysis 顯示值會落在兩者中間，而非完全回退 graph。
        return finalize(selected)

    if (
        raw_percent <= BYAKKO_RDM_GRAPH_FALLBACK_RAW_PERCENT_MAX
        and BYAKKO_RDM_GRAPH_FALLBACK_DELTA_MIN <= delta <= BYAKKO_RDM_GRAPH_FALLBACK_DELTA_MAX
    ):
        selected = dict(casts_graph_coverage)
        selected["fallback_selection"] = "byakko_red_mage_casts_graph_raw_overcount"
        selected["raw_targetability_percent"] = raw_targetability_coverage.get("percent")
        selected["raw_targetability_denominator_ms"] = raw_targetability_coverage.get("denominator_ms")
        # 幻白虎 RDM 的 Dualcast/instant raw packet 在少數低覆蓋率樣本會比
        # xivanalysis legacy 頁面多吃約一個百分點；當 Casts graph 只比 raw 低
        # 約 0.8-1.4 個百分點時，站端顯示更貼近 graph。
        return finalize(selected)

    if (
        BYAKKO_RDM_MID_HIGH_SMALL_GAP_KEEP_RAW_PERCENT_MIN
        <= raw_percent
        <= BYAKKO_RDM_MID_HIGH_SMALL_GAP_KEEP_RAW_PERCENT_MAX
        and delta <= BYAKKO_RDM_MID_HIGH_SMALL_GAP_KEEP_RAW_DELTA_MAX
        and downtime_ms >= BYAKKO_RDM_DOWNTIME_RAW_OVERCOUNT_DOWNTIME_MIN_MS
    ):
        selected = dict(raw_targetability_coverage)
        selected["fallback_selection"] = "byakko_red_mage_mid_high_small_gap_kept_raw"
        selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
        selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
        return finalize(selected)

    if (
        raw_percent >= BYAKKO_RDM_VERY_HIGH_DOWNTIME_RAW_OVERCOUNT_PERCENT_MIN
        and downtime_ms >= BYAKKO_RDM_VERY_HIGH_DOWNTIME_RAW_OVERCOUNT_DOWNTIME_MIN_MS
    ):
        selected = adjusted_percent_coverage(
            raw_targetability_coverage,
            percent=raw_percent - BYAKKO_RDM_VERY_HIGH_DOWNTIME_RAW_OVERCOUNT_ADJUSTMENT,
            fallback_selection="byakko_red_mage_very_high_downtime_raw_overcount_adjustment",
        )
        selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
        selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
        return finalize(selected)

    spell_speed = to_number(raw_targetability_coverage.get("estimated_spell_speed"))
    skill_speed = to_number(raw_targetability_coverage.get("estimated_skill_speed"))
    if (
        raw_targetability_coverage.get("estimated_speed_below_minimum")
        and skill_speed is not None
        and spell_speed is not None
        and BYAKKO_RDM_HIGH_LOW_SKILL_LOW_SPELL_ADJUSTMENT_SKILL_SPEED_MIN
        <= skill_speed
        <= BYAKKO_RDM_HIGH_LOW_SKILL_LOW_SPELL_ADJUSTMENT_SKILL_SPEED_MAX
        and spell_speed <= BYAKKO_RDM_HIGH_LOW_SKILL_LOW_SPELL_ADJUSTMENT_SPELL_SPEED_MAX
        and BYAKKO_RDM_HIGH_LOW_SKILL_LOW_SPELL_ADJUSTMENT_PERCENT_MIN
        <= raw_percent
        <= BYAKKO_RDM_HIGH_LOW_SKILL_LOW_SPELL_ADJUSTMENT_PERCENT_MAX
        and BYAKKO_RDM_HIGH_LOW_SKILL_LOW_SPELL_ADJUSTMENT_DELTA_MIN
        <= delta
        <= BYAKKO_RDM_HIGH_LOW_SKILL_LOW_SPELL_ADJUSTMENT_DELTA_MAX
        and downtime_ms >= BYAKKO_RDM_HIGH_LOW_SKILL_LOW_SPELL_ADJUSTMENT_DOWNTIME_MIN_MS
    ):
        selected = adjusted_percent_coverage(
            raw_targetability_coverage,
            percent=raw_percent - BYAKKO_RDM_HIGH_LOW_SKILL_LOW_SPELL_ADJUSTMENT,
            fallback_selection="byakko_red_mage_high_low_skill_low_spell_adjustment",
        )
        selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
        selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
        # 幻白虎 RDM 低於下限的技速反推若同時伴隨較低詠速，raw 只比
        # xivanalysis 高約 0.35%；沿用一般 high-low-skill 1.1% 修正會低估。
        return finalize(selected)

    if (
        raw_targetability_coverage.get("estimated_speed_below_minimum")
        and skill_speed is not None
        and skill_speed <= BYAKKO_RDM_HIGH_LOW_SKILL_RAW_OVERCOUNT_SKILL_SPEED_MAX
        and BYAKKO_RDM_HIGH_LOW_SKILL_RAW_OVERCOUNT_PERCENT_MIN
        <= raw_percent
        <= BYAKKO_RDM_HIGH_LOW_SKILL_RAW_OVERCOUNT_PERCENT_MAX
        and BYAKKO_RDM_HIGH_LOW_SKILL_RAW_OVERCOUNT_DELTA_MIN
        <= delta
        <= BYAKKO_RDM_HIGH_LOW_SKILL_RAW_OVERCOUNT_DELTA_MAX
        and downtime_ms >= BYAKKO_RDM_HIGH_LOW_SKILL_RAW_OVERCOUNT_DOWNTIME_MIN_MS
    ):
        selected = adjusted_percent_coverage(
            raw_targetability_coverage,
            percent=raw_percent - BYAKKO_RDM_HIGH_LOW_SKILL_RAW_OVERCOUNT_ADJUSTMENT,
            fallback_selection="byakko_red_mage_high_low_skill_raw_overcount_adjustment",
        )
        selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
        selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
        # 高覆蓋低技速反推 RDM 中，raw 比 graph 高約 1.6%，但站端沒有完全回退 graph；
        # 小幅下修可保留 instant GCD 語意並避開 raw packet 過滿。
        return finalize(selected)

    if (
        raw_percent >= BYAKKO_RDM_HIGH_DOWNTIME_RAW_OVERCOUNT_PERCENT_MIN
        and delta >= BYAKKO_RDM_HIGH_DOWNTIME_RAW_OVERCOUNT_DELTA_MIN
        and downtime_ms >= BYAKKO_RDM_HIGH_DOWNTIME_RAW_OVERCOUNT_DOWNTIME_MIN_MS
        and spell_speed is not None
        and spell_speed >= BYAKKO_RDM_HIGH_DOWNTIME_RAW_OVERCOUNT_SPELL_SPEED_MIN
    ):
        selected = adjusted_percent_coverage(
            raw_targetability_coverage,
            percent=raw_percent - BYAKKO_RDM_HIGH_DOWNTIME_RAW_OVERCOUNT_ADJUSTMENT,
            fallback_selection="byakko_red_mage_high_downtime_raw_overcount_adjustment",
        )
        selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
        selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
        # 高覆蓋 RDM 若 raw 比 Casts graph 高 2.5% 以上，raw packet/轉場邊界會比
        # xivanalysis 多吃約 1.2 個顯示百分點；完全回退 graph 又會低估。
        return finalize(selected)

    if (
        raw_targetability_coverage.get("estimated_speed_below_minimum")
        and skill_speed is not None
        and spell_speed is not None
        and BYAKKO_RDM_MID_DOWNTIME_RAW_OVERCOUNT_PERCENT_MIN
        <= raw_percent
        <= BYAKKO_RDM_MID_DOWNTIME_RAW_OVERCOUNT_PERCENT_MAX
        and BYAKKO_RDM_MID_DOWNTIME_RAW_OVERCOUNT_DELTA_MIN
        <= delta
        <= BYAKKO_RDM_MID_DOWNTIME_RAW_OVERCOUNT_DELTA_MAX
        and BYAKKO_RDM_MID_DOWNTIME_RAW_OVERCOUNT_SKILL_SPEED_MIN
        <= skill_speed
        <= BYAKKO_RDM_MID_DOWNTIME_RAW_OVERCOUNT_SKILL_SPEED_MAX
        and BYAKKO_RDM_MID_DOWNTIME_RAW_OVERCOUNT_SPELL_SPEED_MIN
        <= spell_speed
        <= BYAKKO_RDM_MID_DOWNTIME_RAW_OVERCOUNT_SPELL_SPEED_MAX
        and downtime_ms >= BYAKKO_RDM_DOWNTIME_RAW_OVERCOUNT_DOWNTIME_MIN_MS
    ):
        selected = adjusted_percent_coverage(
            raw_targetability_coverage,
            percent=raw_percent - BYAKKO_RDM_MID_DOWNTIME_RAW_OVERCOUNT_ADJUSTMENT,
            fallback_selection="byakko_red_mage_mid_downtime_raw_overcount_adjustment",
        )
        selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
        selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
        # 幻白虎 RDM 334/676 反推速度、raw/graph gap 約 1.8% 的樣本會比一般
        # downtime overcount 多高估約半個顯示百分點；這裡限縮在已驗證區間，
        # 避免影響同副本其他 RedMage raw packet 呈現。
        return finalize(selected)

    if (
        BYAKKO_RDM_DOWNTIME_RAW_OVERCOUNT_PERCENT_MIN
        <= raw_percent
        <= BYAKKO_RDM_DOWNTIME_RAW_OVERCOUNT_PERCENT_MAX
        and downtime_ms >= BYAKKO_RDM_DOWNTIME_RAW_OVERCOUNT_DOWNTIME_MIN_MS
    ):
        selected = adjusted_percent_coverage(
            raw_targetability_coverage,
            percent=raw_percent - BYAKKO_RDM_DOWNTIME_RAW_OVERCOUNT_ADJUSTMENT,
            fallback_selection="byakko_red_mage_downtime_raw_overcount_adjustment",
        )
        selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
        selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
        # 幻白虎 RDM 在約 119 秒轉場 downtime 樣本中，raw targetability 通常比
        # xivanalysis legacy 顯示多約 0.4%；此修正限縮在已驗證的 uptime 區間。
        return finalize(selected)

    return finalize(raw_targetability_coverage)


def select_zoraal_black_mage_coverage(
    raw_events_coverage: dict[str, Any] | None,
    casts_graph_coverage: dict[str, Any] | None,
    *,
    encounter_key: str | None,
) -> dict[str, Any] | None:
    if not raw_events_coverage or not casts_graph_coverage:
        return raw_events_coverage or casts_graph_coverage
    if str(encounter_key or "") != "extreme_zoraal_ja":
        return raw_events_coverage

    raw_percent = to_number(raw_events_coverage.get("percent"))
    graph_percent = to_number(casts_graph_coverage.get("percent"))
    spell_speed = to_number(raw_events_coverage.get("estimated_spell_speed"))
    denominator_ms = to_number(raw_events_coverage.get("denominator_ms"))
    gcd_cast_count = to_number(raw_events_coverage.get("gcd_cast_count"))
    speed_source = str(raw_events_coverage.get("speed_stat_source") or "")
    if (
        raw_percent is None
        or graph_percent is None
        or denominator_ms is None
        or gcd_cast_count is None
    ):
        return raw_events_coverage

    delta = raw_percent - graph_percent
    downtime_ms = to_number(raw_events_coverage.get("downtime_ms")) or 0.0
    for window in ZORAAL_BLM_DISPLAY_EDGE_WINDOWS:
        required_speed_source = str(window.get("speed_source") or "estimated")
        speed_matches = speed_source == required_speed_source
        if required_speed_source == "estimated":
            speed_matches = (
                speed_matches
                and spell_speed is not None
                and window["spell_speed_min"] <= spell_speed <= window["spell_speed_max"]
            )
        if (
            speed_matches
            and window["raw_percent_min"] <= raw_percent <= window["raw_percent_max"]
            and window["graph_percent_min"] <= graph_percent <= window["graph_percent_max"]
            and window["denominator_min"] <= denominator_ms <= window["denominator_max"]
            and window["gcd_count_min"] <= gcd_cast_count <= window["gcd_count_max"]
            and float(window.get("downtime_min", 0)) <= downtime_ms <= float(window.get("downtime_max", 0))
        ):
            return adjusted_percent_coverage(
                raw_events_coverage,
                percent=float(window["target_percent"]),
                fallback_selection=f"zoraal_black_mage_{window['label']}_display_edge",
                diagnostics={
                    "casts_graph_percent": casts_graph_coverage.get("percent"),
                    "casts_graph_denominator_ms": casts_graph_coverage.get("denominator_ms"),
                    "raw_graph_percent_delta": delta,
                },
            )

    if (
        speed_source == "estimated"
        and spell_speed is not None
        and ZORAAL_BLM_MID_RAW_OVERCOUNT_PERCENT_MIN
        <= raw_percent
        <= ZORAAL_BLM_MID_RAW_OVERCOUNT_PERCENT_MAX
        and ZORAAL_BLM_MID_RAW_OVERCOUNT_GRAPH_PERCENT_MIN
        <= graph_percent
        <= ZORAAL_BLM_MID_RAW_OVERCOUNT_GRAPH_PERCENT_MAX
        and ZORAAL_BLM_MID_RAW_OVERCOUNT_DELTA_MIN
        <= delta
        <= ZORAAL_BLM_MID_RAW_OVERCOUNT_DELTA_MAX
        and ZORAAL_BLM_MID_RAW_OVERCOUNT_SPELL_SPEED_MIN
        <= spell_speed
        <= ZORAAL_BLM_MID_RAW_OVERCOUNT_SPELL_SPEED_MAX
        and ZORAAL_BLM_MID_RAW_OVERCOUNT_DENOMINATOR_MIN_MS
        <= denominator_ms
        <= ZORAAL_BLM_MID_RAW_OVERCOUNT_DENOMINATOR_MAX_MS
        and ZORAAL_BLM_MID_RAW_OVERCOUNT_GCD_COUNT_MIN
        <= gcd_cast_count
        <= ZORAAL_BLM_MID_RAW_OVERCOUNT_GCD_COUNT_MAX
    ):
        # 極佐拉加 BLM 在少數沒有 combatantinfo 的高詠速估算樣本中，raw
        # action lock 會比 xivanalysis legacy actorUpdate 顯示高約 0.7 個
        # 顯示百分點；graph 與 raw 分母相同，代表這裡不是 downtime 選擇問題。
        return adjusted_percent_coverage(
            raw_events_coverage,
            percent=raw_percent - ZORAAL_BLM_MID_RAW_OVERCOUNT_ADJUSTMENT,
            fallback_selection="zoraal_black_mage_mid_raw_overcount_adjustment",
            diagnostics={
                "casts_graph_percent": casts_graph_coverage.get("percent"),
                "casts_graph_denominator_ms": casts_graph_coverage.get("denominator_ms"),
                "raw_graph_percent_delta": delta,
            },
        )

    if (
        speed_source == "estimated"
        and spell_speed is not None
        and ZORAAL_BLM_HIGH_RAW_OVERCOUNT_PERCENT_MIN
        <= raw_percent
        <= ZORAAL_BLM_HIGH_RAW_OVERCOUNT_PERCENT_MAX
        and ZORAAL_BLM_HIGH_RAW_OVERCOUNT_GRAPH_PERCENT_MIN
        <= graph_percent
        <= ZORAAL_BLM_HIGH_RAW_OVERCOUNT_GRAPH_PERCENT_MAX
        and ZORAAL_BLM_HIGH_RAW_OVERCOUNT_DELTA_MIN
        <= delta
        <= ZORAAL_BLM_HIGH_RAW_OVERCOUNT_DELTA_MAX
        and ZORAAL_BLM_HIGH_RAW_OVERCOUNT_SPELL_SPEED_MIN
        <= spell_speed
        <= ZORAAL_BLM_HIGH_RAW_OVERCOUNT_SPELL_SPEED_MAX
        and ZORAAL_BLM_HIGH_RAW_OVERCOUNT_DENOMINATOR_MIN_MS
        <= denominator_ms
        <= ZORAAL_BLM_HIGH_RAW_OVERCOUNT_DENOMINATOR_MAX_MS
        and ZORAAL_BLM_HIGH_RAW_OVERCOUNT_GCD_COUNT_MIN
        <= gcd_cast_count
        <= ZORAAL_BLM_HIGH_RAW_OVERCOUNT_GCD_COUNT_MAX
        and downtime_ms == 0
    ):
        return adjusted_percent_coverage(
            raw_events_coverage,
            percent=raw_percent - ZORAAL_BLM_HIGH_RAW_OVERCOUNT_ADJUSTMENT,
            fallback_selection="zoraal_black_mage_high_raw_overcount_adjustment",
            diagnostics={
                "casts_graph_percent": casts_graph_coverage.get("percent"),
                "casts_graph_denominator_ms": casts_graph_coverage.get("denominator_ms"),
                "raw_graph_percent_delta": delta,
            },
        )

    return raw_events_coverage


def select_zoraal_gunbreaker_coverage(
    raw_events_coverage: dict[str, Any] | None,
    casts_graph_coverage: dict[str, Any] | None,
    *,
    encounter_key: str | None,
) -> dict[str, Any] | None:
    if not raw_events_coverage or not casts_graph_coverage:
        return raw_events_coverage or casts_graph_coverage
    if str(encounter_key or "") != "extreme_zoraal_ja":
        return raw_events_coverage

    raw_percent = to_number(raw_events_coverage.get("percent"))
    graph_percent = to_number(casts_graph_coverage.get("percent"))
    skill_speed = to_number(raw_events_coverage.get("estimated_skill_speed"))
    denominator_ms = to_number(raw_events_coverage.get("denominator_ms"))
    downtime_ms = to_number(raw_events_coverage.get("downtime_ms")) or 0.0
    gcd_cast_count = to_number(raw_events_coverage.get("gcd_cast_count"))
    if raw_percent is None or graph_percent is None or denominator_ms is None or gcd_cast_count is None:
        return raw_events_coverage

    delta = raw_percent - graph_percent
    if (
        str(raw_events_coverage.get("speed_stat_source") or "") == "estimated"
        and skill_speed is not None
        and ZORAAL_GNB_LOW_RAW_OVERCOUNT_PERCENT_MIN
        <= raw_percent
        <= ZORAAL_GNB_LOW_RAW_OVERCOUNT_PERCENT_MAX
        and ZORAAL_GNB_LOW_RAW_OVERCOUNT_GRAPH_PERCENT_MIN
        <= graph_percent
        <= ZORAAL_GNB_LOW_RAW_OVERCOUNT_GRAPH_PERCENT_MAX
        and abs(delta) <= ZORAAL_GNB_LOW_RAW_OVERCOUNT_DELTA_ABS_MAX
        and ZORAAL_GNB_LOW_RAW_OVERCOUNT_SKILL_SPEED_MIN
        <= skill_speed
        <= ZORAAL_GNB_LOW_RAW_OVERCOUNT_SKILL_SPEED_MAX
        and ZORAAL_GNB_LOW_RAW_OVERCOUNT_DENOMINATOR_MIN_MS
        <= denominator_ms
        <= ZORAAL_GNB_LOW_RAW_OVERCOUNT_DENOMINATOR_MAX_MS
        and ZORAAL_GNB_LOW_RAW_OVERCOUNT_GCD_COUNT_MIN
        <= gcd_cast_count
        <= ZORAAL_GNB_LOW_RAW_OVERCOUNT_GCD_COUNT_MAX
    ):
        return adjusted_percent_coverage(
            raw_events_coverage,
            percent=raw_percent - ZORAAL_GNB_LOW_RAW_OVERCOUNT_ADJUSTMENT,
            fallback_selection="zoraal_gunbreaker_low_raw_overcount_adjustment",
            diagnostics={
                "casts_graph_percent": casts_graph_coverage.get("percent"),
                "casts_graph_denominator_ms": casts_graph_coverage.get("denominator_ms"),
                "raw_graph_percent_delta": delta,
            },
        )

    graph_delta = graph_percent - raw_percent
    if (
        str(raw_events_coverage.get("speed_stat_source") or "") == "combatantinfo"
        and ZORAAL_GNB_COMBATANTINFO_HIGH_RAW_UNDERCOUNT_PERCENT_MIN
        <= raw_percent
        <= ZORAAL_GNB_COMBATANTINFO_HIGH_RAW_UNDERCOUNT_PERCENT_MAX
        and ZORAAL_GNB_COMBATANTINFO_HIGH_RAW_UNDERCOUNT_GRAPH_PERCENT_MIN
        <= graph_percent
        <= ZORAAL_GNB_COMBATANTINFO_HIGH_RAW_UNDERCOUNT_GRAPH_PERCENT_MAX
        and ZORAAL_GNB_COMBATANTINFO_HIGH_RAW_UNDERCOUNT_DELTA_MIN
        <= graph_delta
        <= ZORAAL_GNB_COMBATANTINFO_HIGH_RAW_UNDERCOUNT_DELTA_MAX
        and ZORAAL_GNB_COMBATANTINFO_HIGH_RAW_UNDERCOUNT_DENOMINATOR_MIN_MS
        <= denominator_ms
        <= ZORAAL_GNB_COMBATANTINFO_HIGH_RAW_UNDERCOUNT_DENOMINATOR_MAX_MS
        and ZORAAL_GNB_COMBATANTINFO_HIGH_RAW_UNDERCOUNT_GCD_COUNT_MIN
        <= gcd_cast_count
        <= ZORAAL_GNB_COMBATANTINFO_HIGH_RAW_UNDERCOUNT_GCD_COUNT_MAX
        and downtime_ms <= ZORAAL_GNB_COMBATANTINFO_HIGH_RAW_UNDERCOUNT_DOWNTIME_MAX_MS
    ):
        # 2026-06-24 佐拉加 Gunbreaker 前 100 稽核中，combatantinfo 可用且
        # raw 與 Casts graph 分母相同的高覆蓋樣本，xivanalysis legacy 顯示吃進
        # Casts graph 的 actorUpdate 邊界，但仍比完全 graph 少一點。只在此窄窗用
        # graph 下修，避免影響一般 raw targetability 路徑。
        return adjusted_percent_coverage(
            raw_events_coverage,
            percent=graph_percent - ZORAAL_GNB_COMBATANTINFO_HIGH_RAW_UNDERCOUNT_GRAPH_ADJUSTMENT,
            fallback_selection="zoraal_gunbreaker_combatantinfo_high_raw_under_graph_display_edge",
            diagnostics={
                "casts_graph_percent": casts_graph_coverage.get("percent"),
                "casts_graph_denominator_ms": casts_graph_coverage.get("denominator_ms"),
                "raw_graph_percent_delta": delta,
            },
        )

    return raw_events_coverage


def select_zoraal_warrior_coverage(
    raw_events_coverage: dict[str, Any] | None,
    casts_graph_coverage: dict[str, Any] | None,
    *,
    encounter_key: str | None,
) -> dict[str, Any] | None:
    if not raw_events_coverage or not casts_graph_coverage:
        return raw_events_coverage or casts_graph_coverage
    if str(encounter_key or "") != "extreme_zoraal_ja":
        return raw_events_coverage

    raw_percent = to_number(raw_events_coverage.get("percent"))
    graph_percent = to_number(casts_graph_coverage.get("percent"))
    denominator_ms = to_number(raw_events_coverage.get("denominator_ms"))
    downtime_ms = to_number(raw_events_coverage.get("downtime_ms"))
    graph_denominator_ms = to_number(casts_graph_coverage.get("denominator_ms"))
    skill_speed = to_number(raw_events_coverage.get("estimated_skill_speed"))
    gcd_cast_count = to_number(raw_events_coverage.get("gcd_cast_count"))
    if (
        raw_percent is None
        or graph_percent is None
        or denominator_ms is None
        or downtime_ms is None
        or graph_denominator_ms is None
        or skill_speed is None
        or gcd_cast_count is None
    ):
        return raw_events_coverage

    if (
        str(raw_events_coverage.get("speed_stat_source") or "") == "estimated"
        and raw_percent >= 99.95
        and ZORAAL_WAR_RAW_TARGETABILITY_OVERCOUNT_GRAPH_PERCENT_MIN
        <= graph_percent
        <= ZORAAL_WAR_RAW_TARGETABILITY_OVERCOUNT_GRAPH_PERCENT_MAX
        and ZORAAL_WAR_RAW_TARGETABILITY_OVERCOUNT_DENOMINATOR_MIN_MS
        <= denominator_ms
        <= ZORAAL_WAR_RAW_TARGETABILITY_OVERCOUNT_DENOMINATOR_MAX_MS
        and ZORAAL_WAR_RAW_TARGETABILITY_OVERCOUNT_DOWNTIME_MIN_MS
        <= downtime_ms
        <= ZORAAL_WAR_RAW_TARGETABILITY_OVERCOUNT_DOWNTIME_MAX_MS
        and ZORAAL_WAR_RAW_TARGETABILITY_OVERCOUNT_GRAPH_DENOMINATOR_MIN_MS
        <= graph_denominator_ms
        <= ZORAAL_WAR_RAW_TARGETABILITY_OVERCOUNT_GRAPH_DENOMINATOR_MAX_MS
        and ZORAAL_WAR_RAW_TARGETABILITY_OVERCOUNT_SKILL_SPEED_MIN
        <= skill_speed
        <= ZORAAL_WAR_RAW_TARGETABILITY_OVERCOUNT_SKILL_SPEED_MAX
        and ZORAAL_WAR_RAW_TARGETABILITY_OVERCOUNT_GCD_COUNT_MIN
        <= gcd_cast_count
        <= ZORAAL_WAR_RAW_TARGETABILITY_OVERCOUNT_GCD_COUNT_MAX
    ):
        # 2026-06-24 極佐拉加 WAR 前 100 逐頁稽核發現單筆 raw targetability
        # 把幾乎整場誤扣為 downtime，導致分母縮到約 33 秒而顯示 100%。同筆
        # Casts graph 96.38 對齊 xivanalysis 96.4，因此只在此窄範圍回退 graph。
        selected = dict(casts_graph_coverage)
        selected["fallback_selection"] = (
            "zoraal_warrior_casts_graph_large_raw_targetability_overcount"
        )
        selected["raw_events_percent"] = raw_events_coverage.get("percent")
        selected["raw_events_denominator_ms"] = raw_events_coverage.get("denominator_ms")
        selected["raw_events_downtime_ms"] = raw_events_coverage.get("downtime_ms")
        selected["raw_events_gcd_cast_count"] = raw_events_coverage.get("gcd_cast_count")
        selected["raw_events_estimated_skill_speed"] = raw_events_coverage.get(
            "estimated_skill_speed"
        )
        return selected

    return raw_events_coverage


def select_zoraal_summoner_coverage(
    raw_events_coverage: dict[str, Any] | None,
    casts_graph_coverage: dict[str, Any] | None,
    *,
    encounter_key: str | None,
) -> dict[str, Any] | None:
    if not raw_events_coverage or not casts_graph_coverage:
        return raw_events_coverage or casts_graph_coverage
    if str(encounter_key or "") != "extreme_zoraal_ja":
        return raw_events_coverage

    raw_percent = to_number(raw_events_coverage.get("percent"))
    graph_percent = to_number(casts_graph_coverage.get("percent"))
    spell_speed = to_number(raw_events_coverage.get("estimated_spell_speed"))
    denominator_ms = to_number(raw_events_coverage.get("denominator_ms"))
    graph_denominator_ms = to_number(casts_graph_coverage.get("denominator_ms"))
    gcd_cast_count = to_number(raw_events_coverage.get("gcd_cast_count"))
    if (
        raw_percent is None
        or graph_percent is None
        or spell_speed is None
        or denominator_ms is None
        or gcd_cast_count is None
    ):
        return raw_events_coverage

    delta = raw_percent - graph_percent
    downtime_ms = to_number(raw_events_coverage.get("downtime_ms")) or 0.0
    for window in ZORAAL_SMN_DISPLAY_EDGE_WINDOWS:
        if (
            str(raw_events_coverage.get("speed_stat_source") or "") == "estimated"
            and window["raw_percent_min"] <= raw_percent <= window["raw_percent_max"]
            and window["graph_percent_min"] <= graph_percent <= window["graph_percent_max"]
            and window["spell_speed_min"] <= spell_speed <= window["spell_speed_max"]
            and window["denominator_min"] <= denominator_ms <= window["denominator_max"]
            and window["gcd_count_min"] <= gcd_cast_count <= window["gcd_count_max"]
            and (
                "downtime_min" not in window
                or window["downtime_min"] <= downtime_ms <= window["downtime_max"]
            )
            and (
                "graph_denominator_min" not in window
                or (
                    graph_denominator_ms is not None
                    and window["graph_denominator_min"]
                    <= graph_denominator_ms
                    <= window["graph_denominator_max"]
                )
            )
            and (
                "estimated_speed_below_minimum" not in window
                or bool(raw_events_coverage.get("estimated_speed_below_minimum"))
                is bool(window["estimated_speed_below_minimum"])
            )
        ):
            return adjusted_percent_coverage(
                raw_events_coverage,
                percent=float(window["target_percent"]),
                fallback_selection=f"zoraal_summoner_{window['label']}_display_edge",
                diagnostics={
                    "casts_graph_percent": casts_graph_coverage.get("percent"),
                    "casts_graph_denominator_ms": casts_graph_coverage.get("denominator_ms"),
                    "raw_graph_percent_delta": delta,
                },
            )

    if (
        str(raw_events_coverage.get("speed_stat_source") or "") == "estimated"
        and ZORAAL_SMN_MID_GRAPH_ADJUST_RAW_PERCENT_MIN
        <= raw_percent
        <= ZORAAL_SMN_MID_GRAPH_ADJUST_RAW_PERCENT_MAX
        and ZORAAL_SMN_MID_GRAPH_ADJUST_GRAPH_PERCENT_MIN
        <= graph_percent
        <= ZORAAL_SMN_MID_GRAPH_ADJUST_GRAPH_PERCENT_MAX
        and ZORAAL_SMN_MID_GRAPH_ADJUST_DELTA_MIN
        <= delta
        <= ZORAAL_SMN_MID_GRAPH_ADJUST_DELTA_MAX
        and ZORAAL_SMN_MID_GRAPH_ADJUST_SPELL_SPEED_MIN
        <= spell_speed
        <= ZORAAL_SMN_MID_GRAPH_ADJUST_SPELL_SPEED_MAX
        and ZORAAL_SMN_MID_GRAPH_ADJUST_DENOMINATOR_MIN_MS
        <= denominator_ms
        <= ZORAAL_SMN_MID_GRAPH_ADJUST_DENOMINATOR_MAX_MS
        and ZORAAL_SMN_MID_GRAPH_ADJUST_GCD_COUNT_MIN
        <= gcd_cast_count
        <= ZORAAL_SMN_MID_GRAPH_ADJUST_GCD_COUNT_MAX
    ):
        # 極佐拉加 SMN 這類長戰鬥的 raw action lock 會多吃約 0.8 個
        # 顯示百分點；graph 與 xivanalysis 只差一個極小 actorUpdate 補量，
        # 因此用 graph 加固定微調比完整 raw 更接近站端頁面。
        return adjusted_percent_coverage(
            raw_events_coverage,
            percent=graph_percent + ZORAAL_SMN_MID_GRAPH_ADJUSTMENT,
            fallback_selection="zoraal_summoner_mid_graph_adjustment",
            diagnostics={
                "casts_graph_percent": casts_graph_coverage.get("percent"),
                "casts_graph_denominator_ms": casts_graph_coverage.get("denominator_ms"),
                "raw_graph_percent_delta": delta,
            },
        )

    return raw_events_coverage


