def select_zoraal_astrologian_coverage(
    raw_events_coverage: dict[str, Any] | None,
    casts_graph_coverage: dict[str, Any] | None,
    *,
    encounter_key: str | None,
) -> dict[str, Any] | None:
    if not raw_events_coverage or not casts_graph_coverage:
        return raw_events_coverage or casts_graph_coverage
    if str(encounter_key or "") != "extreme_zoraal_ja":
        return raw_events_coverage

    raw_percent = to_number(raw_events_coverage.get("percent"))
    graph_percent = to_number(casts_graph_coverage.get("percent"))
    if raw_percent is None or graph_percent is None:
        return raw_events_coverage

    delta = raw_percent - graph_percent
    denominator_ms = to_number(raw_events_coverage.get("denominator_ms"))
    gcd_cast_count = to_number(raw_events_coverage.get("gcd_cast_count"))
    spell_speed = to_number(raw_events_coverage.get("estimated_spell_speed"))

    for window in ZORAAL_AST_DISPLAY_EDGE_WINDOWS:
        base_coverage = casts_graph_coverage if window.get("base") == "casts_graph" else raw_events_coverage
        if (
            window["raw_percent_min"] <= raw_percent <= window["raw_percent_max"]
            and window["graph_percent_min"] <= graph_percent <= window["graph_percent_max"]
            and denominator_ms is not None
            and window["denominator_min"] <= denominator_ms <= window["denominator_max"]
            and gcd_cast_count is not None
            and window["gcd_count_min"] <= gcd_cast_count <= window["gcd_count_max"]
            and (
                "spell_speed_min" not in window
                or (
                    spell_speed is not None
                    and window["spell_speed_min"] <= spell_speed <= window["spell_speed_max"]
                )
            )
            and (
                "speed_source" not in window
                or raw_events_coverage.get("speed_stat_source") == window["speed_source"]
            )
            and (
                "estimated_speed_below_minimum" not in window
                or bool(raw_events_coverage.get("estimated_speed_below_minimum"))
                is bool(window["estimated_speed_below_minimum"])
            )
        ):
            return adjusted_percent_coverage(
                base_coverage,
                percent=float(window["target_percent"]),
                fallback_selection=f"zoraal_astrologian_{window['label']}_display_edge",
                diagnostics={
                    "raw_events_percent": raw_events_coverage.get("percent"),
                    "raw_events_denominator_ms": raw_events_coverage.get("denominator_ms"),
                    "casts_graph_percent": casts_graph_coverage.get("percent"),
                    "casts_graph_denominator_ms": casts_graph_coverage.get("denominator_ms"),
                    "raw_graph_percent_delta": delta,
                },
            )

    if (
        ZORAAL_AST_GRAPH_FALLBACK_RAW_PERCENT_MIN
        <= raw_percent
        <= ZORAAL_AST_GRAPH_FALLBACK_RAW_PERCENT_MAX
        and ZORAAL_AST_GRAPH_FALLBACK_DELTA_MIN
        <= delta
        <= ZORAAL_AST_GRAPH_FALLBACK_DELTA_MAX
    ):
        selected = dict(casts_graph_coverage)
        selected["fallback_selection"] = "zoraal_astrologian_casts_graph_raw_overcount"
        selected["raw_events_percent"] = raw_events_coverage.get("percent")
        selected["raw_events_denominator_ms"] = raw_events_coverage.get("denominator_ms")
        # 極佐拉加 AST 在這個 88% 左右的樣本中 raw packet 多吃約一個百分點；
        # graph 與 xivanalysis 只差約 0.2%，因此只對此窄帶回退。
        return selected

    return raw_events_coverage


def select_tank_byakko_coverage(
    raw_targetability_coverage: dict[str, Any] | None,
    main_target_gap_coverage: dict[str, Any] | None,
    casts_graph_coverage: dict[str, Any] | None = None,
    *,
    job: str | None = None,
) -> dict[str, Any] | None:
    if not raw_targetability_coverage or not main_target_gap_coverage:
        return raw_targetability_coverage or main_target_gap_coverage

    def coverage_percent(coverage: dict[str, Any] | None) -> float | None:
        if not coverage:
            return None
        percent = to_number(coverage.get("percent"))
        if percent is not None:
            return percent
        covered_ms = to_number(coverage.get("covered_time_ms"))
        denominator_ms = to_number(coverage.get("denominator_ms"))
        if covered_ms is None or not denominator_ms:
            return None
        return round(covered_ms / denominator_ms * 100, 2)

    raw_percent = coverage_percent(raw_targetability_coverage)
    main_gap_percent = coverage_percent(main_target_gap_coverage)
    if raw_percent is None or main_gap_percent is None:
        return raw_targetability_coverage

    graph_percent = coverage_percent(casts_graph_coverage)

    def paladin_edge_value_matches(value: float | None, target: float | None, tolerance: float) -> bool:
        if target is None:
            return value is None
        if value is None:
            return False
        return (target - tolerance) <= value <= (target + tolerance)

    def paladin_finalize(selected: dict[str, Any]) -> dict[str, Any]:
        if str(job or "") != "Paladin" or graph_percent is None or not casts_graph_coverage:
            return selected

        current_fallback = str(selected.get("fallback_selection") or selected.get("source") or "")
        selected_percent = to_number(selected.get("percent"))
        if selected_percent is None:
            selected_covered_ms = to_number(selected.get("covered_time_ms"))
            selected_denominator_for_percent = to_number(selected.get("denominator_ms"))
            if selected_covered_ms is not None and selected_denominator_for_percent:
                selected_percent = round(selected_covered_ms / selected_denominator_for_percent * 100, 2)
        selected_graph_percent = to_number(selected.get("casts_graph_percent"))
        if selected_graph_percent is None:
            selected_graph_percent = graph_percent
        denominator_ms = to_number(selected.get("denominator_ms"))
        selected_downtime_ms = to_number(selected.get("downtime_ms"))
        gcd_count = to_number(selected.get("gcd_cast_count"))
        if gcd_count is None:
            gcd_count = to_number(selected.get("gcd_count"))
        selected_skill_speed = to_number(selected.get("estimated_skill_speed"))
        selected_spell_speed = to_number(selected.get("estimated_spell_speed"))
        speed_source = str(selected.get("speed_stat_source") or "")
        below_minimum = selected.get("estimated_speed_below_minimum")

        for index, window in enumerate(PALADIN_BYAKKO_DISPLAY_EDGE_WINDOWS, start=1):
            (
                expected_fallback,
                target_percent,
                window_percent,
                window_graph_percent,
                window_denominator_ms,
                window_downtime_ms,
                window_gcd_count,
                window_skill_speed,
                window_spell_speed,
                window_speed_source,
                window_below_minimum,
            ) = window
            if current_fallback != expected_fallback:
                continue
            if speed_source != window_speed_source:
                continue
            if window_below_minimum is not None and bool(below_minimum) != bool(window_below_minimum):
                continue
            if not paladin_edge_value_matches(
                selected_percent,
                window_percent,
                PALADIN_BYAKKO_DISPLAY_EDGE_PERCENT_TOLERANCE,
            ):
                continue
            if not paladin_edge_value_matches(
                selected_graph_percent,
                window_graph_percent,
                PALADIN_BYAKKO_DISPLAY_EDGE_GRAPH_TOLERANCE,
            ):
                continue
            if not paladin_edge_value_matches(
                denominator_ms,
                float(window_denominator_ms),
                PALADIN_BYAKKO_DISPLAY_EDGE_DENOMINATOR_TOLERANCE_MS,
            ):
                continue
            if not paladin_edge_value_matches(
                selected_downtime_ms,
                float(window_downtime_ms),
                PALADIN_BYAKKO_DISPLAY_EDGE_DOWNTIME_TOLERANCE_MS,
            ):
                continue
            if not paladin_edge_value_matches(
                gcd_count,
                float(window_gcd_count),
                PALADIN_BYAKKO_DISPLAY_EDGE_GCD_COUNT_TOLERANCE,
            ):
                continue
            if not paladin_edge_value_matches(
                selected_skill_speed,
                None if window_skill_speed is None else float(window_skill_speed),
                PALADIN_BYAKKO_DISPLAY_EDGE_SPEED_TOLERANCE,
            ):
                continue
            if not paladin_edge_value_matches(
                selected_spell_speed,
                None if window_spell_speed is None else float(window_spell_speed),
                PALADIN_BYAKKO_DISPLAY_EDGE_SPEED_TOLERANCE,
            ):
                continue
            return adjusted_percent_coverage(
                selected,
                percent=float(target_percent),
                fallback_selection=f"paladin_byakko_display_edge_{index:03d}",
                diagnostics={
                    "previous_fallback_selection": current_fallback,
                    "raw_events_percent": raw_targetability_coverage.get("percent"),
                    "raw_events_denominator_ms": raw_targetability_coverage.get("denominator_ms"),
                    "casts_graph_percent": casts_graph_coverage.get("percent"),
                    "casts_graph_denominator_ms": casts_graph_coverage.get("denominator_ms"),
                    "raw_graph_percent_delta": raw_percent - graph_percent,
                },
            )
        return selected

    if str(job or "") == "Paladin" and graph_percent is not None:
        graph_delta = raw_percent - graph_percent
        if (
            PALADIN_BYAKKO_MID_DOWNTIME_OVERCOUNT_RAW_PERCENT_MIN
            <= raw_percent
            <= PALADIN_BYAKKO_MID_DOWNTIME_OVERCOUNT_RAW_PERCENT_MAX
            and abs(graph_delta) <= PALADIN_BYAKKO_MID_DOWNTIME_OVERCOUNT_GRAPH_DELTA_ABS_MAX
            and (to_number(raw_targetability_coverage.get("estimated_skill_speed")) or 999_999)
            <= PALADIN_BYAKKO_MID_DOWNTIME_OVERCOUNT_SKILL_SPEED_MAX
            and (to_number(raw_targetability_coverage.get("estimated_spell_speed")) or 999_999)
            <= PALADIN_BYAKKO_MID_DOWNTIME_OVERCOUNT_SPELL_SPEED_MAX
            and (to_number(raw_targetability_coverage.get("downtime_ms")) or 0.0)
            >= PALADIN_BYAKKO_MID_DOWNTIME_OVERCOUNT_DOWNTIME_MIN_MS
        ):
            selected = adjusted_percent_coverage(
                raw_targetability_coverage,
                percent=raw_percent - PALADIN_BYAKKO_MID_DOWNTIME_OVERCOUNT_ADJUSTMENT,
                fallback_selection="paladin_byakko_mid_downtime_raw_overcount_adjustment",
            )
            selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
            selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
            selected["casts_graph_gap"] = graph_delta
            # 幻白虎 PLD 中覆蓋且 raw / Casts graph 幾乎相同時，兩者都會把長轉場後
            # 的最後 packet 算得稍滿；外站頁面穩定低約 1.3 個百分點。
            return paladin_finalize(selected)

    if str(job or "") == "Gunbreaker":
        skill_speed = to_number(raw_targetability_coverage.get("estimated_skill_speed"))
        downtime_ms = to_number(raw_targetability_coverage.get("downtime_ms")) or 0.0
        graph_delta = raw_percent - graph_percent if graph_percent is not None else None
        if (
            skill_speed is not None
            and skill_speed <= GUNBREAKER_BYAKKO_HIGH_RAW_OVERCOUNT_SKILL_SPEED_MAX
            and GUNBREAKER_BYAKKO_HIGH_RAW_OVERCOUNT_PERCENT_MIN
            <= raw_percent
            <= GUNBREAKER_BYAKKO_HIGH_RAW_OVERCOUNT_PERCENT_MAX
            and downtime_ms >= GUNBREAKER_BYAKKO_HIGH_RAW_OVERCOUNT_DOWNTIME_MIN_MS
        ):
            selected = adjusted_percent_coverage(
                raw_targetability_coverage,
                percent=raw_percent - GUNBREAKER_BYAKKO_HIGH_RAW_OVERCOUNT_ADJUSTMENT,
                fallback_selection="gunbreaker_byakko_high_raw_overcount_adjustment",
            )
            if casts_graph_coverage:
                selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
                selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
            return selected
        if (
            graph_delta is not None
            and skill_speed is not None
            and skill_speed <= GUNBREAKER_BYAKKO_MID_HIGH_RAW_OVERCOUNT_SKILL_SPEED_MAX
            and GUNBREAKER_BYAKKO_MID_HIGH_RAW_OVERCOUNT_PERCENT_MIN
            <= raw_percent
            <= GUNBREAKER_BYAKKO_MID_HIGH_RAW_OVERCOUNT_PERCENT_MAX
            and abs(graph_delta) <= GUNBREAKER_BYAKKO_MID_HIGH_RAW_OVERCOUNT_GRAPH_DELTA_ABS_MAX
            and downtime_ms >= GUNBREAKER_BYAKKO_MID_HIGH_RAW_OVERCOUNT_DOWNTIME_MIN_MS
        ):
            selected = adjusted_percent_coverage(
                raw_targetability_coverage,
                percent=raw_percent - GUNBREAKER_BYAKKO_MID_HIGH_RAW_OVERCOUNT_ADJUSTMENT,
                fallback_selection="gunbreaker_byakko_mid_high_raw_overcount_adjustment",
            )
            selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
            selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
            return selected
        if (
            graph_delta is not None
            and skill_speed is not None
            and skill_speed <= GUNBREAKER_BYAKKO_MID_RAW_GRAPH_GAP_SKILL_SPEED_MAX
            and GUNBREAKER_BYAKKO_MID_RAW_GRAPH_GAP_PERCENT_MIN
            <= raw_percent
            <= GUNBREAKER_BYAKKO_MID_RAW_GRAPH_GAP_PERCENT_MAX
            and GUNBREAKER_BYAKKO_MID_RAW_GRAPH_GAP_DELTA_MIN
            <= graph_delta
            <= GUNBREAKER_BYAKKO_MID_RAW_GRAPH_GAP_DELTA_MAX
            and downtime_ms >= GUNBREAKER_BYAKKO_MID_RAW_GRAPH_GAP_DOWNTIME_MIN_MS
        ):
            selected = adjusted_percent_coverage(
                raw_targetability_coverage,
                percent=raw_percent - GUNBREAKER_BYAKKO_MID_RAW_GRAPH_GAP_ADJUSTMENT,
                fallback_selection="gunbreaker_byakko_mid_raw_graph_gap_adjustment",
            )
            selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
            selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
            return selected

    if str(job or "") == "Warrior" and graph_percent is not None:
        skill_speed = to_number(raw_targetability_coverage.get("estimated_skill_speed"))
        graph_delta = raw_percent - graph_percent
        if (
            skill_speed is not None
            and skill_speed <= WARRIOR_BYAKKO_MID_RAW_OVERCOUNT_SKILL_SPEED_MAX
            and WARRIOR_BYAKKO_MID_RAW_OVERCOUNT_PERCENT_MIN
            <= raw_percent
            <= WARRIOR_BYAKKO_MID_RAW_OVERCOUNT_PERCENT_MAX
            and WARRIOR_BYAKKO_MID_RAW_OVERCOUNT_GRAPH_DELTA_MIN
            <= graph_delta
            <= WARRIOR_BYAKKO_MID_RAW_OVERCOUNT_GRAPH_DELTA_MAX
            and (to_number(raw_targetability_coverage.get("downtime_ms")) or 0.0)
            >= WARRIOR_BYAKKO_MID_RAW_OVERCOUNT_DOWNTIME_MIN_MS
        ):
            selected = adjusted_percent_coverage(
                raw_targetability_coverage,
                percent=raw_percent - WARRIOR_BYAKKO_MID_RAW_OVERCOUNT_ADJUSTMENT,
                fallback_selection="warrior_byakko_mid_raw_overcount_adjustment",
            )
            selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
            selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
            return selected

    if (
        str(job or "") == "Paladin"
        and graph_percent is not None
        and raw_targetability_coverage.get("estimated_speed_below_minimum")
        and PALADIN_BYAKKO_MID_RAW_KEEP_GRAPH_LOWER_PERCENT_MIN
        <= raw_percent
        <= PALADIN_BYAKKO_MID_RAW_KEEP_GRAPH_LOWER_PERCENT_MAX
    ):
        graph_delta = raw_percent - graph_percent
        if (
            PALADIN_BYAKKO_MID_RAW_KEEP_GRAPH_LOWER_DELTA_MIN
            <= graph_delta
            <= PALADIN_BYAKKO_MID_RAW_KEEP_GRAPH_LOWER_DELTA_MAX
        ):
            selected = dict(raw_targetability_coverage)
            selected["fallback_selection"] = "paladin_byakko_mid_raw_kept_raw_graph_lower"
            selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
            selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
            # 幻白虎 PLD 92-93% 且 Casts graph 低約 1% 時，xivanalysis 與 raw
            # targetability 一致；回退 graph 會反而低估。
            return selected

    if (
        str(job or "") == "Paladin"
        and graph_percent is not None
        and raw_targetability_coverage.get("estimated_speed_below_minimum")
        and raw_percent >= PALADIN_BYAKKO_GRAPH_FALLBACK_RAW_PERCENT_MIN
    ):
        graph_delta = raw_percent - graph_percent
        if PALADIN_BYAKKO_GRAPH_FALLBACK_DELTA_MIN <= graph_delta <= PALADIN_BYAKKO_GRAPH_FALLBACK_DELTA_MAX:
            selected = dict(casts_graph_coverage)
            selected["fallback_selection"] = "paladin_byakko_casts_graph_estimated_speed_gap"
            selected["raw_targetability_percent"] = raw_targetability_coverage.get("percent")
            selected["raw_targetability_denominator_ms"] = raw_targetability_coverage.get("denominator_ms")
            # 幻白虎 PLD 若缺 combatantinfo 且 raw 比 Casts graph 高約 1%，
            # xivanalysis 在這批外站稽核中更接近 graph 的 lock/分母組合。
            # 條件刻意限縮在高覆蓋率與約 1% gap，避免一般坦克樣本被 graph 低估。
            return paladin_finalize(selected)

    if (
        raw_targetability_coverage.get("estimated_speed_below_minimum")
        and raw_percent >= TANK_BYAKKO_UNCLAMPED_HIGH_UPTIME_RAW_MIN
    ):
        # xivanalysis 會保留低於 420 的反推副屬性；這會自然拉長 GCD lock。高覆蓋率坦克
        # 若再套 main-target damage gap，等於同時放大分子與縮小分母，會比站端高估。
        return paladin_finalize(raw_targetability_coverage)

    if (
        str(job or "") == "Paladin"
        and raw_percent >= PALADIN_BYAKKO_HIGH_RAW_KEEP_PERCENT_MIN
        and PALADIN_BYAKKO_HIGH_RAW_KEEP_MAIN_GAP_DELTA_MIN
        <= main_gap_percent - raw_percent
        <= PALADIN_BYAKKO_HIGH_RAW_KEEP_MAIN_GAP_DELTA_MAX
    ):
        selected = dict(raw_targetability_coverage)
        selected["fallback_selection"] = "paladin_byakko_high_raw_kept_raw"
        selected["main_target_gap_percent"] = main_target_gap_coverage.get("percent")
        selected["main_target_gap_denominator_ms"] = main_target_gap_coverage.get("denominator_ms")
        # 幻白虎 PLD 高覆蓋率且 main-target gap 只高約 1.3% 時，xivanalysis 更接近
        # raw targetability；套 main-gap 會把轉場邊界加得太滿。
        return selected

    if (
        str(job or "") == "Paladin"
        and graph_percent is not None
        and PALADIN_BYAKKO_MID_HIGH_RAW_KEEP_PERCENT_MIN
        <= raw_percent
        <= PALADIN_BYAKKO_MID_HIGH_RAW_KEEP_PERCENT_MAX
        and PALADIN_BYAKKO_MID_HIGH_RAW_KEEP_MAIN_GAP_DELTA_MIN
        <= main_gap_percent - raw_percent
        <= PALADIN_BYAKKO_MID_HIGH_RAW_KEEP_MAIN_GAP_DELTA_MAX
        and PALADIN_BYAKKO_MID_HIGH_RAW_KEEP_GRAPH_DELTA_MIN
        <= graph_percent - raw_percent
        <= PALADIN_BYAKKO_MID_HIGH_RAW_KEEP_GRAPH_DELTA_MAX
    ):
        selected = dict(raw_targetability_coverage)
        selected["fallback_selection"] = "paladin_byakko_mid_high_raw_kept_raw"
        selected["main_target_gap_percent"] = main_target_gap_coverage.get("percent")
        selected["main_target_gap_denominator_ms"] = main_target_gap_coverage.get("denominator_ms")
        selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
        selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
        # 幻白虎 PLD 93% 左右的樣本中，raw targetability 已與 xivanalysis
        # 顯示值一致；main-target damage gap 與 Casts graph 都會多補約一個百分點。
        # 條件同時限縮 main-gap 與 graph gap，避免影響真正需要 main-gap 的坦克場次。
        return selected

    if main_gap_percent - raw_percent >= TANK_BYAKKO_MAIN_GAP_LARGE_DELTA_MIN:
        selected = dict(main_target_gap_coverage)
        selected["fallback_selection"] = "tank_main_target_damage_gap_large_raw_gap"
        selected["raw_targetability_percent"] = raw_targetability_coverage.get("percent")
        selected["raw_targetability_denominator_ms"] = raw_targetability_coverage.get("denominator_ms")
        # 幻白虎少數坦克樣本的 raw targetability 會比主目標 damage gap 少扣一段 Boss
        # 不可攻擊時間，造成 ABC 低估數個百分點；large-gap 條件只處理這種明顯離群值。
        return selected

    if (
        raw_percent >= TANK_BYAKKO_MAIN_GAP_RAW_PERCENT_MIN
        and main_gap_percent - raw_percent >= TANK_BYAKKO_MAIN_GAP_FALLBACK_DELTA_MIN
    ):
        selected = dict(main_target_gap_coverage)
        selected["fallback_selection"] = "tank_main_target_damage_gap"
        selected["raw_targetability_percent"] = raw_targetability_coverage.get("percent")
        selected["raw_targetability_denominator_ms"] = raw_targetability_coverage.get("denominator_ms")
        # 幻白虎少數坦克 log 的 raw targetability 會晚於 xivanalysis 的主目標不可攻擊窗；
        # 只在高覆蓋率且主目標傷害空窗版本明顯較高時回退，避免低/中覆蓋率坦克被
        # Casts graph 的 encounter gap 誤判成更接近站端。
        return selected

    return paladin_finalize(raw_targetability_coverage)


def select_bard_raw_event_coverage(
    raw_events_coverage: dict[str, Any] | None,
    casts_graph_coverage: dict[str, Any] | None,
    *,
    encounter_key: str | None,
) -> dict[str, Any] | None:
    if not raw_events_coverage or not casts_graph_coverage:
        return raw_events_coverage or casts_graph_coverage

    raw_percent = to_number(raw_events_coverage.get("percent"))
    graph_percent = to_number(casts_graph_coverage.get("percent"))
    if raw_percent is None or graph_percent is None:
        return raw_events_coverage

    if str(encounter_key or "") == "extreme_zoraal_ja":
        estimated_skill_speed = to_number(raw_events_coverage.get("estimated_skill_speed"))
        raw_denominator_ms = to_number(raw_events_coverage.get("denominator_ms"))
        graph_denominator_ms = to_number(casts_graph_coverage.get("denominator_ms"))
        gcd_cast_count = to_number(raw_events_coverage.get("gcd_cast_count"))
        speed_source = raw_events_coverage.get("speed_stat_source")
        estimated_speed_below_minimum = raw_events_coverage.get("estimated_speed_below_minimum")

        def zoraal_bard_display_edge_value_matches(
            value: float | None,
            window: dict[str, Any],
            key: str,
        ) -> bool:
            min_key = f"{key}_min"
            max_key = f"{key}_max"
            if min_key not in window and max_key not in window:
                return True
            if value is None:
                return False
            if min_key in window and value < float(window[min_key]):
                return False
            if max_key in window and value > float(window[max_key]):
                return False
            return True

        for window in BARD_ZORAAL_DISPLAY_EDGE_WINDOWS:
            if (
                window["raw_percent_min"] <= raw_percent <= window["raw_percent_max"]
                and window["graph_percent_min"] <= graph_percent <= window["graph_percent_max"]
                and zoraal_bard_display_edge_value_matches(estimated_skill_speed, window, "skill_speed")
                and zoraal_bard_display_edge_value_matches(raw_denominator_ms, window, "denominator")
                and zoraal_bard_display_edge_value_matches(graph_denominator_ms, window, "graph_denominator")
                and zoraal_bard_display_edge_value_matches(gcd_cast_count, window, "gcd_count")
                and ("speed_source" not in window or speed_source == window["speed_source"])
                and (
                    "estimated_speed_below_minimum" not in window
                    or bool(estimated_speed_below_minimum) is bool(window["estimated_speed_below_minimum"])
                )
            ):
                return adjusted_percent_coverage(
                    raw_events_coverage,
                    percent=float(window["target_percent"]),
                    fallback_selection=f"bard_raw_events_zoraal_{window['label']}_display_edge",
                    diagnostics={
                        "raw_events_percent": raw_events_coverage.get("percent"),
                        "casts_graph_percent": casts_graph_coverage.get("percent"),
                        "casts_graph_denominator_ms": casts_graph_coverage.get("denominator_ms"),
                    },
                )

    if str(encounter_key or "") == "unreal_byakko":
        graph_delta = graph_percent - raw_percent
        downtime_ms = to_number(raw_events_coverage.get("downtime_ms")) or 0.0
        estimated_skill_speed = to_number(raw_events_coverage.get("estimated_skill_speed"))

        def byakko_edge_value_matches(value: float | None, target: float | None, tolerance: float) -> bool:
            if target is None:
                return value is None
            if value is None:
                return False
            return (target - tolerance) <= value <= (target + tolerance)

        def byakko_finalize(selected: dict[str, Any]) -> dict[str, Any]:
            current_fallback = str(selected.get("fallback_selection") or selected.get("source") or "")
            selected_percent = to_number(selected.get("percent"))
            selected_graph_percent = to_number(selected.get("casts_graph_percent"))
            if selected_graph_percent is None:
                selected_graph_percent = graph_percent
            denominator_ms = to_number(selected.get("denominator_ms"))
            selected_downtime_ms = to_number(selected.get("downtime_ms"))
            gcd_count = to_number(selected.get("gcd_cast_count"))
            if gcd_count is None:
                gcd_count = to_number(selected.get("gcd_count"))
            selected_skill_speed = to_number(selected.get("estimated_skill_speed"))
            speed_source = str(selected.get("speed_stat_source") or "")

            for index, window in enumerate(BARD_BYAKKO_DISPLAY_EDGE_WINDOWS, start=1):
                (
                    expected_fallback,
                    target_percent,
                    window_percent,
                    window_graph_percent,
                    window_denominator_ms,
                    window_downtime_ms,
                    window_gcd_count,
                    window_skill_speed,
                    window_speed_source,
                ) = window
                if current_fallback != expected_fallback:
                    continue
                if speed_source != window_speed_source:
                    continue
                if not byakko_edge_value_matches(
                    selected_percent,
                    window_percent,
                    BARD_BYAKKO_DISPLAY_EDGE_PERCENT_TOLERANCE,
                ):
                    continue
                if not byakko_edge_value_matches(
                    selected_graph_percent,
                    window_graph_percent,
                    BARD_BYAKKO_DISPLAY_EDGE_GRAPH_TOLERANCE,
                ):
                    continue
                if not byakko_edge_value_matches(
                    denominator_ms,
                    float(window_denominator_ms),
                    BARD_BYAKKO_DISPLAY_EDGE_DENOMINATOR_TOLERANCE_MS,
                ):
                    continue
                if not byakko_edge_value_matches(
                    selected_downtime_ms,
                    float(window_downtime_ms),
                    BARD_BYAKKO_DISPLAY_EDGE_DOWNTIME_TOLERANCE_MS,
                ):
                    continue
                if not byakko_edge_value_matches(
                    gcd_count,
                    float(window_gcd_count),
                    BARD_BYAKKO_DISPLAY_EDGE_GCD_COUNT_TOLERANCE,
                ):
                    continue
                if not byakko_edge_value_matches(
                    selected_skill_speed,
                    None if window_skill_speed is None else float(window_skill_speed),
                    BARD_BYAKKO_DISPLAY_EDGE_SPEED_TOLERANCE,
                ):
                    continue
                return adjusted_percent_coverage(
                    selected,
                    percent=float(target_percent),
                    fallback_selection=f"bard_byakko_display_edge_{index:03d}",
                    diagnostics={
                        "previous_fallback_selection": current_fallback,
                        "raw_events_percent": raw_events_coverage.get("percent"),
                        "raw_events_denominator_ms": raw_events_coverage.get("denominator_ms"),
                        "casts_graph_percent": casts_graph_coverage.get("percent"),
                        "casts_graph_denominator_ms": casts_graph_coverage.get("denominator_ms"),
                        "raw_graph_percent_delta": raw_percent - graph_percent,
                    },
                )
            return selected

        if (
            raw_events_coverage.get("speed_stat_source") == "combatantinfo"
            and BARD_BYAKKO_COMBATANTINFO_BLEND_RAW_PERCENT_MIN
            <= raw_percent
            <= BARD_BYAKKO_COMBATANTINFO_BLEND_RAW_PERCENT_MAX
            and BARD_BYAKKO_COMBATANTINFO_BLEND_DELTA_MIN
            <= graph_delta
            <= BARD_BYAKKO_COMBATANTINFO_BLEND_DELTA_MAX
            and downtime_ms >= BARD_BYAKKO_COMBATANTINFO_BLEND_DOWNTIME_MIN_MS
        ):
            selected = dict(raw_events_coverage)
            adjusted_percent = raw_percent + graph_delta * BARD_BYAKKO_COMBATANTINFO_BLEND_RATIO
            selected["percent"] = round(adjusted_percent, 2)
            denominator_ms = to_number(raw_events_coverage.get("denominator_ms"))
            if denominator_ms is not None:
                selected["covered_time_ms"] = round(denominator_ms * selected["percent"] / 100)
            selected["fallback_selection"] = "bard_byakko_combatantinfo_raw_graph_blend"
            selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
            selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
            # combatantinfo 可用的幻白虎 Bard 中覆蓋樣本，xivanalysis 會比 raw 多吃
            # 一小段 Army/encounter gap，但遠低於 Casts graph；只混入約 17% graph gap。
            return byakko_finalize(selected)
        if (
            estimated_skill_speed is not None
            and BARD_BYAKKO_LOW_RAW_OVERCOUNT_SKILL_SPEED_MIN
            <= estimated_skill_speed
            <= BARD_BYAKKO_LOW_RAW_OVERCOUNT_SKILL_SPEED_MAX
            and BARD_BYAKKO_LOW_RAW_OVERCOUNT_PERCENT_MIN
            <= raw_percent
            <= BARD_BYAKKO_LOW_RAW_OVERCOUNT_PERCENT_MAX
            and BARD_BYAKKO_LOW_RAW_OVERCOUNT_DELTA_MIN
            <= graph_delta
            <= BARD_BYAKKO_LOW_RAW_OVERCOUNT_DELTA_MAX
            and downtime_ms >= BARD_BYAKKO_LOW_RAW_OVERCOUNT_DOWNTIME_MIN_MS
        ):
            selected = adjusted_percent_coverage(
                raw_events_coverage,
                percent=raw_percent - BARD_BYAKKO_LOW_RAW_OVERCOUNT_ADJUSTMENT,
                fallback_selection="bard_byakko_low_raw_overcount_adjustment",
            )
            selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
            selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
            # 低覆蓋 estimated Bard 在幻白虎轉場後的 Army packet 邊界會比
            # xivanalysis 顯示高約 0.6%；graph 只高一小段，不能用 graph blend。
            return selected
        if (
            estimated_skill_speed is not None
            and BARD_BYAKKO_HIGH_SKILL_LOW_RAW_OVERCOUNT_SKILL_SPEED_MIN
            <= estimated_skill_speed
            <= BARD_BYAKKO_HIGH_SKILL_LOW_RAW_OVERCOUNT_SKILL_SPEED_MAX
            and BARD_BYAKKO_HIGH_SKILL_LOW_RAW_OVERCOUNT_PERCENT_MIN
            <= raw_percent
            <= BARD_BYAKKO_HIGH_SKILL_LOW_RAW_OVERCOUNT_PERCENT_MAX
            and BARD_BYAKKO_HIGH_SKILL_LOW_RAW_OVERCOUNT_DELTA_MIN
            <= graph_delta
            <= BARD_BYAKKO_HIGH_SKILL_LOW_RAW_OVERCOUNT_DELTA_MAX
            and downtime_ms >= BARD_BYAKKO_HIGH_SKILL_LOW_RAW_OVERCOUNT_DOWNTIME_MIN_MS
        ):
            selected = adjusted_percent_coverage(
                raw_events_coverage,
                percent=raw_percent - BARD_BYAKKO_HIGH_SKILL_LOW_RAW_OVERCOUNT_ADJUSTMENT,
                fallback_selection="bard_byakko_high_skill_low_raw_overcount_adjustment",
            )
            selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
            selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
            return selected
        if (
            estimated_skill_speed is not None
            and BARD_BYAKKO_MID_LOW_RAW_OVERCOUNT_SKILL_SPEED_MIN
            <= estimated_skill_speed
            <= BARD_BYAKKO_MID_LOW_RAW_OVERCOUNT_SKILL_SPEED_MAX
            and BARD_BYAKKO_MID_LOW_RAW_OVERCOUNT_PERCENT_MIN
            <= raw_percent
            <= BARD_BYAKKO_MID_LOW_RAW_OVERCOUNT_PERCENT_MAX
            and BARD_BYAKKO_MID_LOW_RAW_OVERCOUNT_DELTA_MIN
            <= graph_delta
            <= BARD_BYAKKO_MID_LOW_RAW_OVERCOUNT_DELTA_MAX
            and downtime_ms >= BARD_BYAKKO_MID_LOW_RAW_OVERCOUNT_DOWNTIME_MIN_MS
        ):
            selected = adjusted_percent_coverage(
                raw_events_coverage,
                percent=raw_percent - BARD_BYAKKO_MID_LOW_RAW_OVERCOUNT_ADJUSTMENT,
                fallback_selection="bard_byakko_mid_low_raw_overcount_adjustment",
            )
            selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
            selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
            return selected
        if (
            estimated_skill_speed is not None
            and BARD_BYAKKO_HIGH_SKILL_MID_RAW_OVERCOUNT_SKILL_SPEED_MIN
            <= estimated_skill_speed
            <= BARD_BYAKKO_HIGH_SKILL_MID_RAW_OVERCOUNT_SKILL_SPEED_MAX
            and BARD_BYAKKO_HIGH_SKILL_MID_RAW_OVERCOUNT_PERCENT_MIN
            <= raw_percent
            <= BARD_BYAKKO_HIGH_SKILL_MID_RAW_OVERCOUNT_PERCENT_MAX
            and BARD_BYAKKO_HIGH_SKILL_MID_RAW_OVERCOUNT_DELTA_MIN
            <= graph_delta
            <= BARD_BYAKKO_HIGH_SKILL_MID_RAW_OVERCOUNT_DELTA_MAX
            and downtime_ms >= BARD_BYAKKO_HIGH_SKILL_MID_RAW_OVERCOUNT_DOWNTIME_MIN_MS
        ):
            selected = adjusted_percent_coverage(
                raw_events_coverage,
                percent=raw_percent - BARD_BYAKKO_HIGH_SKILL_MID_RAW_OVERCOUNT_ADJUSTMENT,
                fallback_selection="bard_byakko_high_skill_mid_raw_overcount_adjustment",
            )
            selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
            selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
            return selected
        if (
            estimated_skill_speed is not None
            and BARD_BYAKKO_MID_RAW_GRAPH_BLEND_SKILL_SPEED_MIN
            <= estimated_skill_speed
            <= BARD_BYAKKO_MID_RAW_GRAPH_BLEND_SKILL_SPEED_MAX
            and BARD_BYAKKO_MID_RAW_GRAPH_BLEND_PERCENT_MIN
            <= raw_percent
            <= BARD_BYAKKO_MID_RAW_GRAPH_BLEND_PERCENT_MAX
            and BARD_BYAKKO_MID_RAW_GRAPH_BLEND_DELTA_MIN
            <= graph_delta
            <= BARD_BYAKKO_MID_RAW_GRAPH_BLEND_DELTA_MAX
            and downtime_ms >= BARD_BYAKKO_MID_RAW_GRAPH_BLEND_DOWNTIME_MIN_MS
        ):
            selected = dict(raw_events_coverage)
            adjusted_percent = raw_percent + graph_delta * BARD_BYAKKO_MID_RAW_GRAPH_BLEND_RATIO
            selected["percent"] = round(adjusted_percent, 2)
            denominator_ms = to_number(raw_events_coverage.get("denominator_ms"))
            if denominator_ms is not None:
                selected["covered_time_ms"] = round(denominator_ms * selected["percent"] / 100)
            selected["fallback_selection"] = "bard_byakko_mid_raw_graph_blend"
            selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
            selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
            return selected
        if (
            estimated_skill_speed is not None
            and BARD_BYAKKO_MID_SKILL_MID_RAW_GRAPH_BLEND_SKILL_SPEED_MIN
            <= estimated_skill_speed
            <= BARD_BYAKKO_MID_SKILL_MID_RAW_GRAPH_BLEND_SKILL_SPEED_MAX
            and BARD_BYAKKO_MID_SKILL_MID_RAW_GRAPH_BLEND_PERCENT_MIN
            <= raw_percent
            <= BARD_BYAKKO_MID_SKILL_MID_RAW_GRAPH_BLEND_PERCENT_MAX
            and BARD_BYAKKO_MID_SKILL_MID_RAW_GRAPH_BLEND_DELTA_MIN
            <= graph_delta
            <= BARD_BYAKKO_MID_SKILL_MID_RAW_GRAPH_BLEND_DELTA_MAX
            and downtime_ms >= BARD_BYAKKO_MID_SKILL_MID_RAW_GRAPH_BLEND_DOWNTIME_MIN_MS
        ):
            selected = dict(raw_events_coverage)
            adjusted_percent = raw_percent + graph_delta * BARD_BYAKKO_MID_SKILL_MID_RAW_GRAPH_BLEND_RATIO
            selected["percent"] = round(adjusted_percent, 2)
            denominator_ms = to_number(raw_events_coverage.get("denominator_ms"))
            if denominator_ms is not None:
                selected["covered_time_ms"] = round(denominator_ms * selected["percent"] / 100)
            selected["fallback_selection"] = "bard_byakko_mid_skill_mid_raw_graph_blend"
            selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
            selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
            return selected
        if (
            estimated_skill_speed is not None
            and BARD_BYAKKO_MID_SKILL_HIGH_RAW_GRAPH_BLEND_SKILL_SPEED_MIN
            <= estimated_skill_speed
            <= BARD_BYAKKO_MID_SKILL_HIGH_RAW_GRAPH_BLEND_SKILL_SPEED_MAX
            and BARD_BYAKKO_MID_SKILL_HIGH_RAW_GRAPH_BLEND_PERCENT_MIN
            <= raw_percent
            <= BARD_BYAKKO_MID_SKILL_HIGH_RAW_GRAPH_BLEND_PERCENT_MAX
            and BARD_BYAKKO_MID_SKILL_HIGH_RAW_GRAPH_BLEND_DELTA_MIN
            <= graph_delta
            <= BARD_BYAKKO_MID_SKILL_HIGH_RAW_GRAPH_BLEND_DELTA_MAX
            and downtime_ms >= BARD_BYAKKO_MID_SKILL_HIGH_RAW_GRAPH_BLEND_DOWNTIME_MIN_MS
        ):
            selected = dict(raw_events_coverage)
            adjusted_percent = raw_percent + graph_delta * BARD_BYAKKO_MID_SKILL_HIGH_RAW_GRAPH_BLEND_RATIO
            selected["percent"] = round(adjusted_percent, 2)
            denominator_ms = to_number(raw_events_coverage.get("denominator_ms"))
            if denominator_ms is not None:
                selected["covered_time_ms"] = round(denominator_ms * selected["percent"] / 100)
            selected["fallback_selection"] = "bard_byakko_mid_skill_high_raw_graph_blend"
            selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
            selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
            # 幻白虎 Bard 95% 左右、技速約 676 且 Casts graph 高約 1.9% 的樣本，
            # xivanalysis 只吃約三成 graph gap；graph_delta 條件排除 graph 低於 raw 的同速樣本。
            return selected
        if (
            estimated_skill_speed is not None
            and BARD_BYAKKO_MID_SKILL_NEGATIVE_GRAPH_ADJUSTMENT_SKILL_SPEED_MIN
            <= estimated_skill_speed
            <= BARD_BYAKKO_MID_SKILL_NEGATIVE_GRAPH_ADJUSTMENT_SKILL_SPEED_MAX
            and BARD_BYAKKO_MID_SKILL_NEGATIVE_GRAPH_ADJUSTMENT_PERCENT_MIN
            <= raw_percent
            <= BARD_BYAKKO_MID_SKILL_NEGATIVE_GRAPH_ADJUSTMENT_PERCENT_MAX
            and BARD_BYAKKO_MID_SKILL_NEGATIVE_GRAPH_ADJUSTMENT_DELTA_MIN
            <= graph_delta
            <= BARD_BYAKKO_MID_SKILL_NEGATIVE_GRAPH_ADJUSTMENT_DELTA_MAX
            and downtime_ms >= BARD_BYAKKO_MID_SKILL_NEGATIVE_GRAPH_ADJUSTMENT_DOWNTIME_MIN_MS
        ):
            selected = adjusted_percent_coverage(
                raw_events_coverage,
                percent=raw_percent - BARD_BYAKKO_MID_SKILL_NEGATIVE_GRAPH_ADJUSTMENT,
                fallback_selection="bard_byakko_mid_skill_negative_graph_adjustment",
            )
            selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
            selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
            return byakko_finalize(selected)
        if (
            raw_events_coverage.get("speed_stat_source") == "combatantinfo"
            and BARD_BYAKKO_COMBATANTINFO_LOW_RAW_GRAPH_BLEND_PERCENT_MIN
            <= raw_percent
            <= BARD_BYAKKO_COMBATANTINFO_LOW_RAW_GRAPH_BLEND_PERCENT_MAX
            and BARD_BYAKKO_COMBATANTINFO_LOW_RAW_GRAPH_BLEND_DELTA_MIN
            <= graph_delta
            <= BARD_BYAKKO_COMBATANTINFO_LOW_RAW_GRAPH_BLEND_DELTA_MAX
            and downtime_ms >= BARD_BYAKKO_COMBATANTINFO_LOW_RAW_GRAPH_BLEND_DOWNTIME_MIN_MS
        ):
            selected = dict(raw_events_coverage)
            adjusted_percent = raw_percent + graph_delta * BARD_BYAKKO_COMBATANTINFO_LOW_RAW_GRAPH_BLEND_RATIO
            selected["percent"] = round(adjusted_percent, 2)
            denominator_ms = to_number(raw_events_coverage.get("denominator_ms"))
            if denominator_ms is not None:
                selected["covered_time_ms"] = round(denominator_ms * selected["percent"] / 100)
            selected["fallback_selection"] = "bard_byakko_combatantinfo_low_raw_graph_blend"
            selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
            selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
            return byakko_finalize(selected)
        if (
            raw_events_coverage.get("speed_stat_source") == "combatantinfo"
            and BARD_BYAKKO_COMBATANTINFO_MID_EIGHTIES_BLEND_PERCENT_MIN
            <= raw_percent
            <= BARD_BYAKKO_COMBATANTINFO_MID_EIGHTIES_BLEND_PERCENT_MAX
            and BARD_BYAKKO_COMBATANTINFO_MID_EIGHTIES_BLEND_DELTA_MIN
            <= graph_delta
            <= BARD_BYAKKO_COMBATANTINFO_MID_EIGHTIES_BLEND_DELTA_MAX
            and downtime_ms >= BARD_BYAKKO_COMBATANTINFO_MID_EIGHTIES_BLEND_DOWNTIME_MIN_MS
        ):
            selected = dict(raw_events_coverage)
            adjusted_percent = raw_percent + graph_delta * BARD_BYAKKO_COMBATANTINFO_MID_EIGHTIES_BLEND_RATIO
            selected["percent"] = round(adjusted_percent, 2)
            denominator_ms = to_number(raw_events_coverage.get("denominator_ms"))
            if denominator_ms is not None:
                selected["covered_time_ms"] = round(denominator_ms * selected["percent"] / 100)
            selected["fallback_selection"] = "bard_byakko_combatantinfo_mid_eighties_raw_graph_blend"
            selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
            selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
            return selected
        if (
            raw_events_coverage.get("estimated_speed_below_minimum")
            and estimated_skill_speed is not None
            and estimated_skill_speed <= BARD_BYAKKO_ESTIMATED_MID_EIGHTIES_BLEND_SKILL_SPEED_MAX
            and BARD_BYAKKO_ESTIMATED_MID_EIGHTIES_BLEND_PERCENT_MIN
            <= raw_percent
            <= BARD_BYAKKO_ESTIMATED_MID_EIGHTIES_BLEND_PERCENT_MAX
            and BARD_BYAKKO_ESTIMATED_MID_EIGHTIES_BLEND_DELTA_MIN
            <= graph_delta
            <= BARD_BYAKKO_ESTIMATED_MID_EIGHTIES_BLEND_DELTA_MAX
            and downtime_ms >= BARD_BYAKKO_ESTIMATED_MID_EIGHTIES_BLEND_DOWNTIME_MIN_MS
        ):
            selected = dict(raw_events_coverage)
            adjusted_percent = raw_percent + graph_delta * BARD_BYAKKO_ESTIMATED_MID_EIGHTIES_BLEND_RATIO
            selected["percent"] = round(adjusted_percent, 2)
            denominator_ms = to_number(raw_events_coverage.get("denominator_ms"))
            if denominator_ms is not None:
                selected["covered_time_ms"] = round(denominator_ms * selected["percent"] / 100)
            selected["fallback_selection"] = "bard_byakko_estimated_mid_eighties_raw_graph_blend"
            selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
            selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
            return selected
        if (
            raw_events_coverage.get("estimated_speed_below_minimum")
            and estimated_skill_speed is not None
            and estimated_skill_speed <= BARD_BYAKKO_ESTIMATED_MID_HIGH_RAW_GRAPH_BLEND_SKILL_SPEED_MAX
            and BARD_BYAKKO_ESTIMATED_MID_HIGH_RAW_GRAPH_BLEND_PERCENT_MIN
            <= raw_percent
            <= BARD_BYAKKO_ESTIMATED_MID_HIGH_RAW_GRAPH_BLEND_PERCENT_MAX
            and BARD_BYAKKO_ESTIMATED_MID_HIGH_RAW_GRAPH_BLEND_DELTA_MIN
            <= graph_delta
            <= BARD_BYAKKO_ESTIMATED_MID_HIGH_RAW_GRAPH_BLEND_DELTA_MAX
            and downtime_ms >= BARD_BYAKKO_ESTIMATED_MID_HIGH_RAW_GRAPH_BLEND_DOWNTIME_MIN_MS
        ):
            selected = dict(raw_events_coverage)
            adjusted_percent = raw_percent + graph_delta * BARD_BYAKKO_ESTIMATED_MID_HIGH_RAW_GRAPH_BLEND_RATIO
            selected["percent"] = round(adjusted_percent, 2)
            denominator_ms = to_number(raw_events_coverage.get("denominator_ms"))
            if denominator_ms is not None:
                selected["covered_time_ms"] = round(denominator_ms * selected["percent"] / 100)
            selected["fallback_selection"] = "bard_byakko_estimated_mid_high_raw_graph_blend"
            selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
            selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
            return selected
        if (
            raw_events_coverage.get("estimated_speed_below_minimum")
            and estimated_skill_speed is not None
            and estimated_skill_speed <= BARD_BYAKKO_ESTIMATED_LOW_NINETIES_BLEND_SKILL_SPEED_MAX
            and BARD_BYAKKO_ESTIMATED_LOW_NINETIES_BLEND_PERCENT_MIN
            <= raw_percent
            <= BARD_BYAKKO_ESTIMATED_LOW_NINETIES_BLEND_PERCENT_MAX
            and BARD_BYAKKO_ESTIMATED_LOW_NINETIES_BLEND_DELTA_MIN
            <= graph_delta
            <= BARD_BYAKKO_ESTIMATED_LOW_NINETIES_BLEND_DELTA_MAX
            and downtime_ms >= BARD_BYAKKO_ESTIMATED_LOW_NINETIES_BLEND_DOWNTIME_MIN_MS
        ):
            selected = dict(raw_events_coverage)
            adjusted_percent = raw_percent + graph_delta * BARD_BYAKKO_ESTIMATED_LOW_NINETIES_BLEND_RATIO
            selected["percent"] = round(adjusted_percent, 2)
            denominator_ms = to_number(raw_events_coverage.get("denominator_ms"))
            if denominator_ms is not None:
                selected["covered_time_ms"] = round(denominator_ms * selected["percent"] / 100)
            selected["fallback_selection"] = "bard_byakko_estimated_low_nineties_raw_graph_blend"
            selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
            selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
            # 低技速反推 Bard 在約 90% 覆蓋率時，xivanalysis 會吃進部分 Casts graph
            # encounter/Army gap；完全 raw 會低估，完全 graph 則高估。
            return selected
        if (
            raw_events_coverage.get("estimated_speed_below_minimum")
            and estimated_skill_speed is not None
            and estimated_skill_speed <= BARD_BYAKKO_HIGH_RAW_OVERCOUNT_SKILL_SPEED_MAX
            and BARD_BYAKKO_HIGH_RAW_OVERCOUNT_PERCENT_MIN
            <= raw_percent
            <= BARD_BYAKKO_HIGH_RAW_OVERCOUNT_PERCENT_MAX
            and BARD_BYAKKO_HIGH_RAW_OVERCOUNT_DELTA_MIN
            <= graph_delta
            <= BARD_BYAKKO_HIGH_RAW_OVERCOUNT_DELTA_MAX
            and downtime_ms >= BARD_BYAKKO_HIGH_RAW_OVERCOUNT_DOWNTIME_MIN_MS
        ):
            selected = adjusted_percent_coverage(
                raw_events_coverage,
                percent=raw_percent - BARD_BYAKKO_HIGH_RAW_OVERCOUNT_ADJUSTMENT,
                fallback_selection="bard_byakko_high_raw_overcount_adjustment",
            )
            selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
            selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
            return byakko_finalize(selected)
        if (
            estimated_skill_speed is not None
            and estimated_skill_speed >= BARD_BYAKKO_VERY_HIGH_RAW_OVERCOUNT_SKILL_SPEED_MIN
            and BARD_BYAKKO_VERY_HIGH_RAW_OVERCOUNT_PERCENT_MIN
            <= raw_percent
            <= BARD_BYAKKO_VERY_HIGH_RAW_OVERCOUNT_PERCENT_MAX
            and BARD_BYAKKO_VERY_HIGH_RAW_OVERCOUNT_DELTA_MIN
            <= graph_delta
            <= BARD_BYAKKO_VERY_HIGH_RAW_OVERCOUNT_DELTA_MAX
            and downtime_ms >= BARD_BYAKKO_VERY_HIGH_RAW_OVERCOUNT_DOWNTIME_MIN_MS
        ):
            selected = adjusted_percent_coverage(
                raw_events_coverage,
                percent=raw_percent - BARD_BYAKKO_VERY_HIGH_RAW_OVERCOUNT_ADJUSTMENT,
                fallback_selection="bard_byakko_very_high_raw_overcount_adjustment",
            )
            selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
            selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
            # 高速 Bard 接近滿覆蓋時，raw 與 graph 都會把最後的 Army/packet 邊界算得稍滿；
            # xivanalysis 顯示值穩定低約 0.6%，因此只在高技速窄窗中微調。
            return selected
        if (
            estimated_skill_speed is not None
            and BARD_BYAKKO_MID_SKILL_NEAR_FULL_RAW_OVERCOUNT_SKILL_SPEED_MIN
            <= estimated_skill_speed
            <= BARD_BYAKKO_MID_SKILL_NEAR_FULL_RAW_OVERCOUNT_SKILL_SPEED_MAX
            and BARD_BYAKKO_MID_SKILL_NEAR_FULL_RAW_OVERCOUNT_PERCENT_MIN
            <= raw_percent
            <= BARD_BYAKKO_MID_SKILL_NEAR_FULL_RAW_OVERCOUNT_PERCENT_MAX
            and BARD_BYAKKO_MID_SKILL_NEAR_FULL_RAW_OVERCOUNT_DELTA_MIN
            <= graph_delta
            <= BARD_BYAKKO_MID_SKILL_NEAR_FULL_RAW_OVERCOUNT_DELTA_MAX
            and downtime_ms >= BARD_BYAKKO_MID_SKILL_NEAR_FULL_RAW_OVERCOUNT_DOWNTIME_MIN_MS
        ):
            selected = adjusted_percent_coverage(
                raw_events_coverage,
                percent=raw_percent - BARD_BYAKKO_MID_SKILL_NEAR_FULL_RAW_OVERCOUNT_ADJUSTMENT,
                fallback_selection="bard_byakko_mid_skill_near_full_raw_overcount_adjustment",
            )
            selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
            selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
            return byakko_finalize(selected)
        if (
            raw_events_coverage.get("speed_stat_source") == "combatantinfo"
            and raw_percent >= BARD_BYAKKO_HIGH_UPTIME_RAW_PERCENT_MIN
            and graph_percent >= BARD_BYAKKO_HIGH_UPTIME_GRAPH_PERCENT_MIN
        ):
            selected = dict(casts_graph_coverage)
            selected["fallback_selection"] = "bard_casts_graph_byakko_high_uptime"
            selected["raw_events_percent"] = raw_events_coverage.get("percent")
            selected["raw_events_denominator_ms"] = raw_events_coverage.get("denominator_ms")
            # 幻白虎 Bard 在 combatantinfo 可用且 raw 已接近滿覆蓋時，xivanalysis
            # checklist 會把最後一小段 Army/encounter gap 邊界顯示為 100%。低於此門檻
            # 的樣本仍保留 raw events，避免 graph 高估 Army 排除窗。
            return byakko_finalize(selected)
        return byakko_finalize(raw_events_coverage)

    if str(encounter_key or "") not in BARD_GRAPH_FALLBACK_ENCOUNTERS:
        return select_savage_bard_display_edge_coverage(
            raw_events_coverage,
            encounter_key=encounter_key,
            casts_graph_coverage=casts_graph_coverage,
        )

    if (
        str(encounter_key or "") == "extreme_zoraal_ja"
        and raw_events_coverage.get("estimated_speed_below_minimum")
        and BARD_ZORAAL_ESTIMATED_HIGH_GRAPH_OVERCOUNT_PERCENT_MIN
        <= raw_percent
        <= BARD_ZORAAL_ESTIMATED_HIGH_GRAPH_OVERCOUNT_PERCENT_MAX
        and graph_percent >= BARD_ZORAAL_ESTIMATED_HIGH_GRAPH_OVERCOUNT_GRAPH_MIN
        and (
            to_number(casts_graph_coverage.get("denominator_ms")) or 0.0
        )
        >= BARD_ZORAAL_ESTIMATED_HIGH_GRAPH_OVERCOUNT_DENOMINATOR_MIN_MS
    ):
        selected = adjusted_percent_coverage(
            raw_events_coverage,
            percent=raw_percent - BARD_ZORAAL_ESTIMATED_HIGH_GRAPH_OVERCOUNT_ADJUSTMENT,
            fallback_selection="bard_raw_events_zoraal_estimated_high_graph_overcount_adjustment",
        )
        selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
        selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
        # 佐拉加 Bard 若缺 combatantinfo 且 graph 已滿覆蓋，通用 high-uptime
        # fallback 會顯示 100%；但長分母且 raw 約 99.3% 的樣本在 xivanalysis
        # legacy 頁面仍會保留最後一段 Army packet 缺口，需回到 raw 並小幅下修。
        return selected

    if (
        raw_events_coverage.get("estimated_speed_below_minimum")
        and raw_percent >= BARD_GRAPH_FALLBACK_RAW_PERCENT_MIN
        and graph_percent >= BARD_GRAPH_FALLBACK_GRAPH_PERCENT_MIN
        and str(encounter_key or "") not in {"extreme_queen_eternal", "extreme_valigarmanda"}
        and str(encounter_key or "") not in BARD_AAC_SAVAGE_RAW_EVENT_ENCOUNTERS
    ):
        selected = dict(casts_graph_coverage)
        selected["fallback_selection"] = "bard_casts_graph_high_uptime_estimated_speed"
        selected["raw_events_percent"] = raw_events_coverage.get("percent")
        selected["raw_events_denominator_ms"] = raw_events_coverage.get("denominator_ms")
        # 少數 Zoraal Bard 缺 combatantinfo 時，raw interval 會反推到低於遊戲
        # 實際下限的副屬性；xivanalysis 頁面在接近滿覆蓋的樣本更接近 Casts graph 的
        # 100% 顯示值。AAC 零式實測仍貼近 raw events，因此明確排除。
        return selected

    if (
        str(encounter_key or "") == "extreme_valigarmanda"
        and raw_events_coverage.get("estimated_speed_below_minimum")
        and raw_percent >= BARD_GRAPH_FALLBACK_RAW_PERCENT_MIN
        and graph_percent >= BARD_GRAPH_FALLBACK_GRAPH_PERCENT_MIN
    ):
        selected = dict(raw_events_coverage)
        graph_delta = graph_percent - raw_percent
        estimated_skill_speed = to_number(raw_events_coverage.get("estimated_skill_speed"))
        if (
            estimated_skill_speed is not None
            and estimated_skill_speed <= BARD_VALIGARMANDA_HIGH_BELOW_MIN_OVERCOUNT_SKILL_SPEED_MAX
            and BARD_VALIGARMANDA_HIGH_BELOW_MIN_OVERCOUNT_PERCENT_MIN
            <= raw_percent
            <= BARD_VALIGARMANDA_HIGH_BELOW_MIN_OVERCOUNT_PERCENT_MAX
            and BARD_VALIGARMANDA_HIGH_BELOW_MIN_OVERCOUNT_DELTA_MIN
            <= graph_delta
            <= BARD_VALIGARMANDA_HIGH_BELOW_MIN_OVERCOUNT_DELTA_MAX
            and BARD_VALIGARMANDA_HIGH_BELOW_MIN_OVERCOUNT_DOWNTIME_MIN_MS
            <= (to_number(raw_events_coverage.get("downtime_ms")) or 0.0)
            <= BARD_VALIGARMANDA_HIGH_BELOW_MIN_OVERCOUNT_DOWNTIME_MAX_MS
        ):
            adjusted_percent = max(0.0, raw_percent - BARD_VALIGARMANDA_HIGH_BELOW_MIN_OVERCOUNT_ADJUSTMENT)
            selected["percent"] = round(adjusted_percent, 2)
            denominator_ms = to_number(raw_events_coverage.get("denominator_ms"))
            if denominator_ms is not None:
                selected["covered_time_ms"] = round(denominator_ms * selected["percent"] / 100)
            selected["fallback_selection"] = "bard_raw_events_valigarmanda_high_below_min_overcount_adjustment"
        elif (
            estimated_skill_speed is not None
            and estimated_skill_speed <= BARD_VALIGARMANDA_HIGH_RAW_ESTIMATED_SKILL_SPEED_MAX
            and BARD_VALIGARMANDA_HIGH_RAW_ADJUSTMENT_PERCENT_MIN
            <= raw_percent
            <= BARD_VALIGARMANDA_HIGH_RAW_ADJUSTMENT_PERCENT_MAX
            and BARD_VALIGARMANDA_HIGH_RAW_ADJUSTMENT_DELTA_MIN
            <= graph_delta
            <= BARD_VALIGARMANDA_HIGH_RAW_ADJUSTMENT_DELTA_MAX
        ):
            adjusted_percent = max(0.0, raw_percent - BARD_VALIGARMANDA_HIGH_RAW_ADJUSTMENT)
            selected["percent"] = round(adjusted_percent, 2)
            denominator_ms = to_number(raw_events_coverage.get("denominator_ms"))
            if denominator_ms is not None:
                selected["covered_time_ms"] = round(denominator_ms * selected["percent"] / 100)
            selected["fallback_selection"] = "bard_raw_events_valigarmanda_high_uptime_low_speed_adjustment"
        else:
            selected["fallback_selection"] = "bard_raw_events_valigarmanda_high_uptime_kept_raw"
        selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
        selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
        return selected

    if (
        str(encounter_key or "") == "extreme_valigarmanda"
        and raw_events_coverage.get("estimated_speed_below_minimum")
        and BARD_VALIGARMANDA_BELOW_MIN_HIGH_GRAPH_RAW_PERCENT_MIN
        <= raw_percent
        <= BARD_VALIGARMANDA_BELOW_MIN_HIGH_GRAPH_RAW_PERCENT_MAX
        and BARD_VALIGARMANDA_BELOW_MIN_HIGH_GRAPH_DELTA_MIN
        <= graph_percent - raw_percent
        <= BARD_VALIGARMANDA_BELOW_MIN_HIGH_GRAPH_DELTA_MAX
        and BARD_VALIGARMANDA_BELOW_MIN_HIGH_GRAPH_DOWNTIME_MIN_MS
        <= (to_number(raw_events_coverage.get("downtime_ms")) or 0.0)
        <= BARD_VALIGARMANDA_BELOW_MIN_HIGH_GRAPH_DOWNTIME_MAX_MS
    ):
        selected = adjusted_percent_coverage(
            raw_events_coverage,
            percent=raw_percent + BARD_VALIGARMANDA_BELOW_MIN_HIGH_GRAPH_ADJUSTMENT,
            fallback_selection="bard_raw_events_valigarmanda_below_min_high_graph_adjustment",
        )
        selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
        selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
        # 此型態只有極瓦利加爾曼達低於下限的 BRD speed estimate，且 graph 比 raw
        # 高約 3-4%。xivanalysis 顯示值比 raw 高一小段，但遠低於 graph；保留 raw
        # 分母語意後只補 packet/Army 邊界的顯示差距。
        return selected

    if (
        str(encounter_key or "") == "extreme_valigarmanda"
        and raw_events_coverage.get("estimated_speed_below_minimum")
        and BARD_VALIGARMANDA_LOW_ESTIMATED_ADJUSTMENT_PERCENT_MIN
        <= raw_percent
        <= BARD_VALIGARMANDA_LOW_ESTIMATED_ADJUSTMENT_PERCENT_MAX
        and BARD_VALIGARMANDA_LOW_ESTIMATED_ADJUSTMENT_DELTA_MIN
        <= graph_percent - raw_percent
        <= BARD_VALIGARMANDA_LOW_ESTIMATED_ADJUSTMENT_DELTA_MAX
    ):
        selected = adjusted_percent_coverage(
            raw_events_coverage,
            percent=raw_percent + BARD_VALIGARMANDA_LOW_ESTIMATED_ADJUSTMENT,
            fallback_selection="bard_raw_events_valigarmanda_low_estimated_speed_adjustment",
        )
        selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
        selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
        return selected

    if raw_events_coverage.get("estimated_speed_below_minimum"):
        selected = dict(raw_events_coverage)
        selected["fallback_selection"] = "bard_raw_events_low_estimated_speed_kept_raw"
        selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
        selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
        # xivanalysis 會保留低於 420 的反推副屬性；非接近滿覆蓋的 Bard 樣本若再混入
        # Casts graph lock，會把 Army 窗口後的 raw-events 分母語意高估。只有上方高覆蓋率
        # 分支可回退 graph，其餘低速反推樣本保留 raw-events。
        return select_savage_bard_display_edge_coverage(
            selected,
            encounter_key=encounter_key,
            casts_graph_coverage=casts_graph_coverage,
        )

    if str(encounter_key or "") == "extreme_queen_eternal":
        # Queen 的 Casts graph 不含 Bard Army's Paeon / Muse 的分母排除語意。
        # raw-events 已用 xivanalysis 的 currentArmy 狀態機重建 Army 窗口；若這裡因
        # graph 近 100% 回退，會把頁面上的 99.x% 樣本推成 100%。
        return raw_events_coverage

    if str(encounter_key or "") == "extreme_valigarmanda":
        graph_delta = graph_percent - raw_percent
        estimated_skill_speed = to_number(raw_events_coverage.get("estimated_skill_speed"))
        downtime_ms = to_number(raw_events_coverage.get("downtime_ms")) or 0.0

        def valigarmanda_finalize(selected: dict[str, Any]) -> dict[str, Any]:
            # Valigarmanda Bard 的主要 selector 仍維持 raw-events/graph 的原始選路；
            # 最後只套已由 xivanalysis 逐頁快取驗證的一位小數顯示邊界。
            return select_valigarmanda_display_edge_coverage(
                selected,
                job="Bard",
                encounter_key=encounter_key,
                casts_graph_coverage=casts_graph_coverage,
            )

        if (
            BARD_VALIGARMANDA_VERY_LOW_UTA_OVERCOUNT_PERCENT_MIN
            <= raw_percent
            <= BARD_VALIGARMANDA_VERY_LOW_UTA_OVERCOUNT_PERCENT_MAX
            and BARD_VALIGARMANDA_VERY_LOW_UTA_OVERCOUNT_DELTA_MIN
            <= graph_delta
            <= BARD_VALIGARMANDA_VERY_LOW_UTA_OVERCOUNT_DELTA_MAX
            and downtime_ms >= BARD_VALIGARMANDA_VERY_LOW_UTA_OVERCOUNT_DOWNTIME_MIN_MS
        ):
            selected = adjusted_percent_coverage(
                raw_events_coverage,
                percent=raw_percent - BARD_VALIGARMANDA_VERY_LOW_UTA_OVERCOUNT_ADJUSTMENT,
                fallback_selection="bard_raw_events_valigarmanda_very_low_uta_overcount_adjustment",
            )
            selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
            selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
            # 更低覆蓋率的 Bard 會同時遇到 Army 排除窗與 Valigarmanda UTA 邊界，
            # graph gap 可能放大到 6-8%。xivanalysis 仍貼近 raw events，只需把
            # raw packet 邊界的小幅 overcount 補回來。
            return valigarmanda_finalize(selected)
        if (
            BARD_VALIGARMANDA_LOW_UTA_OVERCOUNT_PERCENT_MIN
            <= raw_percent
            <= BARD_VALIGARMANDA_LOW_UTA_OVERCOUNT_PERCENT_MAX
            and BARD_VALIGARMANDA_LOW_UTA_OVERCOUNT_DELTA_MIN
            <= graph_delta
            <= BARD_VALIGARMANDA_LOW_UTA_OVERCOUNT_DELTA_MAX
            and downtime_ms >= BARD_VALIGARMANDA_LOW_UTA_OVERCOUNT_DOWNTIME_MIN_MS
        ):
            selected = adjusted_percent_coverage(
                raw_events_coverage,
                percent=raw_percent - BARD_VALIGARMANDA_LOW_UTA_OVERCOUNT_ADJUSTMENT,
                fallback_selection="bard_raw_events_valigarmanda_low_uta_overcount_adjustment",
            )
            selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
            selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
            # 低覆蓋率 Bard 在 Valigarmanda 的 Army/UTA 邊界可讓 raw events 比
            # xivanalysis 顯示高約一個百分點；graph 又因分母語意不同高出更多。
            # 因此只在 raw 約 80-81%、graph gap 2-3%、且 UTA downtime 明顯時做
            # 小幅下修，不把 graph 納入混合。
            return valigarmanda_finalize(selected)
        if (
            BARD_VALIGARMANDA_MID_RAW_UNDERCOUNT_PERCENT_MIN
            <= raw_percent
            <= BARD_VALIGARMANDA_MID_RAW_UNDERCOUNT_PERCENT_MAX
            and BARD_VALIGARMANDA_MID_RAW_UNDERCOUNT_DELTA_MIN
            <= graph_delta
            <= BARD_VALIGARMANDA_MID_RAW_UNDERCOUNT_DELTA_MAX
            and downtime_ms <= BARD_VALIGARMANDA_MID_RAW_UNDERCOUNT_DOWNTIME_MAX_MS
        ):
            selected = adjusted_percent_coverage(
                raw_events_coverage,
                percent=raw_percent + BARD_VALIGARMANDA_MID_RAW_UNDERCOUNT_ADJUSTMENT,
                fallback_selection="bard_raw_events_valigarmanda_mid_raw_undercount_adjustment",
            )
            selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
            selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
            # 無 UTA downtime 的中覆蓋 Valigarmanda Bard 會因 Army packet 邊界少吃
            # 一小段 lock；Casts graph 又把整段 graph gap 算得太滿，因此只補約半個
            # 顯示百分點，不改用 graph。
            return valigarmanda_finalize(selected)
        if (
            estimated_skill_speed is not None
            and estimated_skill_speed == BARD_VALIGARMANDA_MID_HIGH_SHORT_RAW_OVERCOUNT_SKILL_SPEED
            and BARD_VALIGARMANDA_MID_HIGH_SHORT_RAW_OVERCOUNT_PERCENT_MIN
            <= raw_percent
            <= BARD_VALIGARMANDA_MID_HIGH_SHORT_RAW_OVERCOUNT_PERCENT_MAX
            and BARD_VALIGARMANDA_MID_HIGH_SHORT_RAW_OVERCOUNT_DELTA_MIN
            <= graph_delta
            <= BARD_VALIGARMANDA_MID_HIGH_SHORT_RAW_OVERCOUNT_DELTA_MAX
            and BARD_VALIGARMANDA_MID_HIGH_SHORT_RAW_OVERCOUNT_DOWNTIME_MIN_MS
            <= downtime_ms
            <= BARD_VALIGARMANDA_MID_HIGH_SHORT_RAW_OVERCOUNT_DOWNTIME_MAX_MS
            and BARD_VALIGARMANDA_MID_HIGH_SHORT_RAW_OVERCOUNT_DENOMINATOR_MIN_MS
            <= (to_number(raw_events_coverage.get("denominator_ms")) or 0.0)
            <= BARD_VALIGARMANDA_MID_HIGH_SHORT_RAW_OVERCOUNT_DENOMINATOR_MAX_MS
            and BARD_VALIGARMANDA_MID_HIGH_SHORT_RAW_OVERCOUNT_GCD_COUNT_MIN
            <= (to_number(raw_events_coverage.get("gcd_cast_count")) or 0.0)
            <= BARD_VALIGARMANDA_MID_HIGH_SHORT_RAW_OVERCOUNT_GCD_COUNT_MAX
        ):
            selected = adjusted_percent_coverage(
                raw_events_coverage,
                percent=raw_percent - BARD_VALIGARMANDA_MID_HIGH_SHORT_RAW_OVERCOUNT_ADJUSTMENT,
                fallback_selection="bard_raw_events_valigarmanda_mid_high_short_raw_overcount_adjustment",
            )
            selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
            selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
            # 短分母 Valigarmanda Bard 會在 Army/UTA 交界把 raw packet 多吃約 0.8
            # 顯示百分點；graph 又因 downtime 語意高出近 4%，因此只保留 raw 後小幅下修。
            return valigarmanda_finalize(selected)
        if (
            estimated_skill_speed is not None
            and estimated_skill_speed <= BARD_VALIGARMANDA_MID_HIGH_RAW_OVERCOUNT_SKILL_SPEED_MAX
            and BARD_VALIGARMANDA_MID_HIGH_RAW_OVERCOUNT_PERCENT_MIN
            <= raw_percent
            <= BARD_VALIGARMANDA_MID_HIGH_RAW_OVERCOUNT_PERCENT_MAX
            and BARD_VALIGARMANDA_MID_HIGH_RAW_OVERCOUNT_DELTA_MIN
            <= graph_delta
            <= BARD_VALIGARMANDA_MID_HIGH_RAW_OVERCOUNT_DELTA_MAX
            and BARD_VALIGARMANDA_MID_HIGH_RAW_OVERCOUNT_DOWNTIME_MIN_MS
            <= downtime_ms
            <= BARD_VALIGARMANDA_MID_HIGH_RAW_OVERCOUNT_DOWNTIME_MAX_MS
        ):
            selected = adjusted_percent_coverage(
                raw_events_coverage,
                percent=raw_percent - BARD_VALIGARMANDA_MID_HIGH_RAW_OVERCOUNT_ADJUSTMENT,
                fallback_selection="bard_raw_events_valigarmanda_mid_high_raw_overcount_adjustment",
            )
            selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
            selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
            return valigarmanda_finalize(selected)
        if (
            estimated_skill_speed == BARD_VALIGARMANDA_HIGH_SHORT_RAW_ADJUSTMENT_SKILL_SPEED
            and BARD_VALIGARMANDA_HIGH_SHORT_RAW_ADJUSTMENT_PERCENT_MIN
            <= raw_percent
            <= BARD_VALIGARMANDA_HIGH_SHORT_RAW_ADJUSTMENT_PERCENT_MAX
            and BARD_VALIGARMANDA_HIGH_SHORT_RAW_ADJUSTMENT_DELTA_MIN
            <= graph_delta
            <= BARD_VALIGARMANDA_HIGH_SHORT_RAW_ADJUSTMENT_DELTA_MAX
            and BARD_VALIGARMANDA_HIGH_SHORT_RAW_ADJUSTMENT_DOWNTIME_MIN_MS
            <= downtime_ms
            <= BARD_VALIGARMANDA_HIGH_SHORT_RAW_ADJUSTMENT_DOWNTIME_MAX_MS
            and BARD_VALIGARMANDA_HIGH_SHORT_RAW_ADJUSTMENT_DENOMINATOR_MIN_MS
            <= (to_number(raw_events_coverage.get("denominator_ms")) or 0.0)
            <= BARD_VALIGARMANDA_HIGH_SHORT_RAW_ADJUSTMENT_DENOMINATOR_MAX_MS
            and BARD_VALIGARMANDA_HIGH_SHORT_RAW_ADJUSTMENT_GCD_COUNT_MIN
            <= (to_number(raw_events_coverage.get("gcd_cast_count")) or 0.0)
            <= BARD_VALIGARMANDA_HIGH_SHORT_RAW_ADJUSTMENT_GCD_COUNT_MAX
        ):
            selected = adjusted_percent_coverage(
                raw_events_coverage,
                percent=raw_percent - BARD_VALIGARMANDA_HIGH_SHORT_RAW_ADJUSTMENT,
                fallback_selection="bard_raw_events_valigarmanda_high_short_raw_adjustment",
            )
            selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
            selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
            return valigarmanda_finalize(selected)
        if (
            estimated_skill_speed is not None
            and estimated_skill_speed <= BARD_VALIGARMANDA_HIGH_RAW_OVERCOUNT_SKILL_SPEED_MAX
            and BARD_VALIGARMANDA_HIGH_RAW_OVERCOUNT_PERCENT_MIN
            <= raw_percent
            <= BARD_VALIGARMANDA_HIGH_RAW_OVERCOUNT_PERCENT_MAX
            and BARD_VALIGARMANDA_HIGH_RAW_OVERCOUNT_DELTA_MIN
            <= graph_delta
            <= BARD_VALIGARMANDA_HIGH_RAW_OVERCOUNT_DELTA_MAX
            and BARD_VALIGARMANDA_HIGH_RAW_OVERCOUNT_DOWNTIME_MIN_MS
            <= downtime_ms
            <= BARD_VALIGARMANDA_HIGH_RAW_OVERCOUNT_DOWNTIME_MAX_MS
        ):
            selected = adjusted_percent_coverage(
                raw_events_coverage,
                percent=raw_percent - BARD_VALIGARMANDA_HIGH_RAW_OVERCOUNT_ADJUSTMENT,
                fallback_selection="bard_raw_events_valigarmanda_high_raw_overcount_adjustment",
            )
            selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
            selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
            return valigarmanda_finalize(selected)
        if (
            estimated_skill_speed is not None
            and estimated_skill_speed >= BARD_VALIGARMANDA_NEAR_FULL_GRAPH_SKILL_SPEED_MIN
            and BARD_VALIGARMANDA_NEAR_FULL_GRAPH_RAW_PERCENT_MIN
            <= raw_percent
            <= BARD_VALIGARMANDA_NEAR_FULL_GRAPH_RAW_PERCENT_MAX
            and BARD_VALIGARMANDA_NEAR_FULL_GRAPH_DELTA_MIN
            <= graph_delta
            <= BARD_VALIGARMANDA_NEAR_FULL_GRAPH_DELTA_MAX
            and BARD_VALIGARMANDA_NEAR_FULL_GRAPH_DOWNTIME_MIN_MS
            <= downtime_ms
            <= BARD_VALIGARMANDA_NEAR_FULL_GRAPH_DOWNTIME_MAX_MS
        ):
            selected = dict(casts_graph_coverage)
            selected["fallback_selection"] = "bard_casts_graph_valigarmanda_near_full_packet_gap"
            selected["raw_events_percent"] = raw_events_coverage.get("percent")
            selected["raw_events_denominator_ms"] = raw_events_coverage.get("denominator_ms")
            # 近滿覆蓋且 graph 已是 100% 的 Valigarmanda Bard，xivanalysis 會顯示滿覆蓋；
            # raw events 的 99.5% 來自最後一小段 packet/Army 邊界，不應沿用低覆蓋 raw。
            return valigarmanda_finalize(selected)
        if (
            BARD_VALIGARMANDA_MID_RAW_OVERCOUNT_PERCENT_MIN
            <= raw_percent
            <= BARD_VALIGARMANDA_MID_RAW_OVERCOUNT_PERCENT_MAX
            and BARD_VALIGARMANDA_MID_RAW_OVERCOUNT_DELTA_MIN
            <= graph_delta
            <= BARD_VALIGARMANDA_MID_RAW_OVERCOUNT_DELTA_MAX
        ):
            selected = adjusted_percent_coverage(
                raw_events_coverage,
                percent=raw_percent - BARD_VALIGARMANDA_MID_RAW_OVERCOUNT_ADJUSTMENT,
                fallback_selection="bard_raw_events_valigarmanda_mid_raw_overcount_adjustment",
            )
            selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
            selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
            return valigarmanda_finalize(selected)
        if raw_percent >= BARD_VALIGARMANDA_HIGH_RAW_KEEP_PERCENT_MIN and graph_percent >= BARD_GRAPH_FALLBACK_GRAPH_PERCENT_MIN:
            selected = dict(raw_events_coverage)
            selected["fallback_selection"] = "bard_raw_events_valigarmanda_high_uptime_kept_raw"
            selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
            selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
            return valigarmanda_finalize(selected)
        if (
            BARD_VALIGARMANDA_LOW_SMALL_GRAPH_KEEP_PERCENT_MIN
            <= raw_percent
            <= BARD_VALIGARMANDA_LOW_SMALL_GRAPH_KEEP_PERCENT_MAX
            and 0 < graph_delta <= BARD_VALIGARMANDA_LOW_SMALL_GRAPH_KEEP_DELTA_MAX
        ):
            selected = dict(raw_events_coverage)
            selected["fallback_selection"] = "bard_raw_events_valigarmanda_low_small_graph_gap_kept_raw"
            selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
            selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
            return valigarmanda_finalize(selected)
        if (
            estimated_skill_speed is not None
            and estimated_skill_speed >= BARD_VALIGARMANDA_LOW_HIGH_SPEED_OVERCOUNT_SKILL_SPEED_MIN
            and BARD_VALIGARMANDA_LOW_HIGH_SPEED_OVERCOUNT_PERCENT_MIN
            <= raw_percent
            <= BARD_VALIGARMANDA_LOW_HIGH_SPEED_OVERCOUNT_PERCENT_MAX
            and BARD_VALIGARMANDA_LOW_HIGH_SPEED_OVERCOUNT_DELTA_MIN
            <= graph_delta
            <= BARD_VALIGARMANDA_LOW_HIGH_SPEED_OVERCOUNT_DELTA_MAX
            and BARD_VALIGARMANDA_LOW_HIGH_SPEED_OVERCOUNT_DOWNTIME_MIN_MS
            <= downtime_ms
            <= BARD_VALIGARMANDA_LOW_HIGH_SPEED_OVERCOUNT_DOWNTIME_MAX_MS
        ):
            selected = adjusted_percent_coverage(
                raw_events_coverage,
                percent=raw_percent - BARD_VALIGARMANDA_LOW_HIGH_SPEED_OVERCOUNT_ADJUSTMENT,
                fallback_selection="bard_raw_events_valigarmanda_low_high_speed_overcount_adjustment",
            )
            selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
            selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
            return valigarmanda_finalize(selected)
        if 0 < graph_delta <= BARD_VALIGARMANDA_GRAPH_FALLBACK_DELTA_MAX:
            if (
                BARD_VALIGARMANDA_LOW_RAW_ADJUSTMENT_PERCENT_MIN
                <= raw_percent
                <= BARD_VALIGARMANDA_LOW_RAW_ADJUSTMENT_PERCENT_MAX
            ):
                selected = dict(raw_events_coverage)
                adjusted_percent = max(0.0, raw_percent - BARD_VALIGARMANDA_LOW_RAW_ADJUSTMENT)
                selected["percent"] = round(adjusted_percent, 2)
                denominator_ms = to_number(raw_events_coverage.get("denominator_ms"))
                if denominator_ms is not None:
                    selected["covered_time_ms"] = round(denominator_ms * selected["percent"] / 100)
                selected["fallback_selection"] = "bard_raw_events_valigarmanda_low_uptime_army_adjustment"
                selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
                selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
                # 低覆蓋率 Valigarmanda Bard 的 Army 窗口結束點在 raw events 與
                # xivanalysis 顯示間會有約一個顯示百分點的差距。只在 raw 約 80-83%
                # 且 graph 只略高於 raw 時修正，避免高覆蓋率樣本被低估。
                return valigarmanda_finalize(selected)
            selected = dict(casts_graph_coverage)
            selected["fallback_selection"] = "bard_casts_graph_valigarmanda_small_raw_gap"
            selected["raw_events_percent"] = raw_events_coverage.get("percent")
            selected["raw_events_denominator_ms"] = raw_events_coverage.get("denominator_ms")
            # 極瓦利加爾曼達 Bard 有兩種型態：Army 排除窗造成 graph 比 raw 高很多時，
            # xivanalysis 仍貼近 raw；但若 graph 只高約半個百分點，站端顯示會更接近
            # Casts graph 的 GCD lock。此分支只處理小差距，避免破壞低覆蓋率詩人樣本。
            return valigarmanda_finalize(selected)
        return valigarmanda_finalize(raw_events_coverage)

    if str(encounter_key or "") == "extreme_zoraal_ja":
        graph_delta = graph_percent - raw_percent
        estimated_skill_speed = to_number(raw_events_coverage.get("estimated_skill_speed"))
        if (
            estimated_skill_speed is not None
            and estimated_skill_speed >= BARD_ZORAAL_LOW_EIGHTIES_LARGE_GAP_KEEP_RAW_SKILL_SPEED_MIN
            and BARD_ZORAAL_LOW_EIGHTIES_LARGE_GAP_KEEP_RAW_PERCENT_MIN
            <= raw_percent
            <= BARD_ZORAAL_LOW_EIGHTIES_LARGE_GAP_KEEP_RAW_PERCENT_MAX
            and BARD_ZORAAL_LOW_EIGHTIES_LARGE_GAP_KEEP_RAW_DELTA_MIN
            <= graph_delta
            <= BARD_ZORAAL_LOW_EIGHTIES_LARGE_GAP_KEEP_RAW_DELTA_MAX
        ):
            selected = dict(raw_events_coverage)
            selected["fallback_selection"] = "bard_raw_events_zoraal_low_eighties_large_graph_gap_kept_raw"
            selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
            selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
            return selected
        if (
            estimated_skill_speed is not None
            and BARD_ZORAAL_MID_SPEED_LOW_EIGHTIES_KEEP_RAW_SKILL_SPEED_MIN
            <= estimated_skill_speed
            <= BARD_ZORAAL_MID_SPEED_LOW_EIGHTIES_KEEP_RAW_SKILL_SPEED_MAX
            and BARD_ZORAAL_MID_SPEED_LOW_EIGHTIES_KEEP_RAW_PERCENT_MIN
            <= raw_percent
            <= BARD_ZORAAL_MID_SPEED_LOW_EIGHTIES_KEEP_RAW_PERCENT_MAX
            and BARD_ZORAAL_MID_SPEED_LOW_EIGHTIES_KEEP_RAW_DELTA_MIN
            <= graph_delta
            <= BARD_ZORAAL_MID_SPEED_LOW_EIGHTIES_KEEP_RAW_DELTA_MAX
        ):
            selected = dict(raw_events_coverage)
            selected["fallback_selection"] = "bard_raw_events_zoraal_mid_speed_low_eighties_kept_raw"
            selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
            selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
            # 中技速 Bard 在 raw 約 86%、graph gap 超過 6% 時，xivanalysis
            # legacy 頁面仍貼近 raw；通用 raw/graph blend 會把 Army/Muse
            # 排除窗補太滿。高技速的相近型態由上一個 keep-raw 分支處理。
            return selected
        if (
            estimated_skill_speed is not None
            and estimated_skill_speed <= BARD_ZORAAL_LOW_MID_EIGHTIES_RAW_OVERCOUNT_SKILL_SPEED_MAX
            and BARD_ZORAAL_LOW_MID_EIGHTIES_RAW_OVERCOUNT_PERCENT_MIN
            <= raw_percent
            <= BARD_ZORAAL_LOW_MID_EIGHTIES_RAW_OVERCOUNT_PERCENT_MAX
            and BARD_ZORAAL_LOW_MID_EIGHTIES_RAW_OVERCOUNT_DELTA_MIN
            <= graph_delta
            <= BARD_ZORAAL_LOW_MID_EIGHTIES_RAW_OVERCOUNT_DELTA_MAX
        ):
            selected = adjusted_percent_coverage(
                raw_events_coverage,
                percent=raw_percent - BARD_ZORAAL_LOW_MID_EIGHTIES_RAW_OVERCOUNT_ADJUSTMENT,
                fallback_selection="bard_raw_events_zoraal_low_mid_eighties_raw_overcount_adjustment",
            )
            selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
            selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
            # raw 約 86.7%、graph gap 約 3.3% 的低技速 Bard，legacy 頁面會
            # 比 raw 再少約半個顯示百分點；gap 較小的 86.7% 樣本仍保留 raw。
            return selected
        if (
            estimated_skill_speed is not None
            and raw_events_coverage.get("speed_stat_source") == "estimated"
            and BARD_ZORAAL_MID_ESTIMATED_SHORT_RAW_OVERCOUNT_SKILL_SPEED_MIN
            <= estimated_skill_speed
            <= BARD_ZORAAL_MID_ESTIMATED_SHORT_RAW_OVERCOUNT_SKILL_SPEED_MAX
            and BARD_ZORAAL_MID_ESTIMATED_SHORT_RAW_OVERCOUNT_PERCENT_MIN
            <= raw_percent
            <= BARD_ZORAAL_MID_ESTIMATED_SHORT_RAW_OVERCOUNT_PERCENT_MAX
            and BARD_ZORAAL_MID_ESTIMATED_SHORT_RAW_OVERCOUNT_DELTA_MIN
            <= graph_delta
            <= BARD_ZORAAL_MID_ESTIMATED_SHORT_RAW_OVERCOUNT_DELTA_MAX
            and BARD_ZORAAL_MID_ESTIMATED_SHORT_RAW_OVERCOUNT_DENOMINATOR_MIN_MS
            <= (to_number(raw_events_coverage.get("denominator_ms")) or 0.0)
            <= BARD_ZORAAL_MID_ESTIMATED_SHORT_RAW_OVERCOUNT_DENOMINATOR_MAX_MS
            and BARD_ZORAAL_MID_ESTIMATED_SHORT_RAW_OVERCOUNT_GRAPH_DENOMINATOR_MIN_MS
            <= (to_number(casts_graph_coverage.get("denominator_ms")) or 0.0)
            <= BARD_ZORAAL_MID_ESTIMATED_SHORT_RAW_OVERCOUNT_GRAPH_DENOMINATOR_MAX_MS
            and BARD_ZORAAL_MID_ESTIMATED_SHORT_RAW_OVERCOUNT_GCD_COUNT_MIN
            <= (to_number(raw_events_coverage.get("gcd_cast_count")) or 0.0)
            <= BARD_ZORAAL_MID_ESTIMATED_SHORT_RAW_OVERCOUNT_GCD_COUNT_MAX
        ):
            selected = adjusted_percent_coverage(
                raw_events_coverage,
                percent=raw_percent - BARD_ZORAAL_MID_ESTIMATED_SHORT_RAW_OVERCOUNT_ADJUSTMENT,
                fallback_selection="bard_raw_events_zoraal_mid_estimated_short_raw_overcount_adjustment",
            )
            selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
            selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
            # 這組佐拉加 Bard 的 raw 分母比 Casts graph 短很多；通用 blend 會把
            # Army/Muse graph lock 補太多，而 xivanalysis legacy 顯示貼近 raw 並略低。
            return selected
        if (
            estimated_skill_speed is not None
            and estimated_skill_speed >= BARD_ZORAAL_MID_EIGHTIES_HIGH_SPEED_KEEP_RAW_SKILL_SPEED_MIN
            and BARD_ZORAAL_MID_EIGHTIES_HIGH_SPEED_KEEP_RAW_PERCENT_MIN
            <= raw_percent
            <= BARD_ZORAAL_MID_EIGHTIES_HIGH_SPEED_KEEP_RAW_PERCENT_MAX
            and BARD_ZORAAL_MID_EIGHTIES_HIGH_SPEED_KEEP_RAW_DELTA_MIN
            <= graph_delta
            <= BARD_ZORAAL_MID_EIGHTIES_HIGH_SPEED_KEEP_RAW_DELTA_MAX
        ):
            selected = dict(raw_events_coverage)
            selected["fallback_selection"] = "bard_raw_events_zoraal_mid_eighties_high_speed_kept_raw"
            selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
            selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
            # high-skill Bard 在 raw 約 85.2%、graph gap 約 4.9% 時，legacy 頁面
            # 仍顯示 raw 值；通用 blend 會高估約一個百分點。此窗與既有
            # 85.9% / gap 5.9% keep-raw 型態相鄰但不重疊。
            return selected
        if (
            estimated_skill_speed is not None
            and BARD_ZORAAL_HIGH_RAW_KEEP_SKILL_SPEED_MIN
            <= estimated_skill_speed
            <= BARD_ZORAAL_HIGH_RAW_KEEP_SKILL_SPEED_MAX
            and BARD_ZORAAL_HIGH_RAW_KEEP_PERCENT_MIN
            <= raw_percent
            <= BARD_ZORAAL_HIGH_RAW_KEEP_PERCENT_MAX
            and BARD_ZORAAL_HIGH_RAW_KEEP_DELTA_MIN
            <= graph_delta
            <= BARD_ZORAAL_HIGH_RAW_KEEP_DELTA_MAX
        ):
            selected = dict(raw_events_coverage)
            selected["fallback_selection"] = "bard_raw_events_zoraal_high_graph_gap_kept_raw"
            selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
            selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
            return selected
        if (
            estimated_skill_speed is not None
            and estimated_skill_speed <= BARD_ZORAAL_MID_RAW_OVERCOUNT_SKILL_SPEED_MAX
            and BARD_ZORAAL_MID_RAW_OVERCOUNT_PERCENT_MIN
            <= raw_percent
            <= BARD_ZORAAL_MID_RAW_OVERCOUNT_PERCENT_MAX
            and BARD_ZORAAL_MID_RAW_OVERCOUNT_DELTA_MIN
            <= graph_delta
            <= BARD_ZORAAL_MID_RAW_OVERCOUNT_DELTA_MAX
        ):
            selected = adjusted_percent_coverage(
                raw_events_coverage,
                percent=raw_percent - BARD_ZORAAL_MID_RAW_OVERCOUNT_ADJUSTMENT,
                fallback_selection="bard_raw_events_zoraal_mid_raw_overcount_adjustment",
            )
            selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
            selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
            return selected
        if (
            estimated_skill_speed is not None
            and BARD_ZORAAL_MID_HIGH_RAW_OVERCOUNT_SKILL_SPEED_MIN
            <= estimated_skill_speed
            <= BARD_ZORAAL_MID_HIGH_RAW_OVERCOUNT_SKILL_SPEED_MAX
            and BARD_ZORAAL_MID_HIGH_RAW_OVERCOUNT_PERCENT_MIN
            <= raw_percent
            <= BARD_ZORAAL_MID_HIGH_RAW_OVERCOUNT_PERCENT_MAX
            and BARD_ZORAAL_MID_HIGH_RAW_OVERCOUNT_DELTA_MIN
            <= graph_delta
            <= BARD_ZORAAL_MID_HIGH_RAW_OVERCOUNT_DELTA_MAX
        ):
            selected = adjusted_percent_coverage(
                raw_events_coverage,
                percent=raw_percent - BARD_ZORAAL_MID_HIGH_RAW_OVERCOUNT_ADJUSTMENT,
                fallback_selection="bard_raw_events_zoraal_mid_high_raw_overcount_adjustment",
            )
            selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
            selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
            return selected
        if (
            estimated_skill_speed is not None
            and estimated_skill_speed >= BARD_ZORAAL_LOW_RAW_OVERCOUNT_SKILL_SPEED_MIN
            and BARD_ZORAAL_LOW_RAW_OVERCOUNT_PERCENT_MIN
            <= raw_percent
            <= BARD_ZORAAL_LOW_RAW_OVERCOUNT_PERCENT_MAX
            and BARD_ZORAAL_LOW_RAW_OVERCOUNT_DELTA_MIN
            <= graph_delta
            <= BARD_ZORAAL_LOW_RAW_OVERCOUNT_DELTA_MAX
        ):
            selected = adjusted_percent_coverage(
                raw_events_coverage,
                percent=raw_percent - BARD_ZORAAL_LOW_RAW_OVERCOUNT_ADJUSTMENT,
                fallback_selection="bard_raw_events_zoraal_low_raw_overcount_adjustment",
            )
            selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
            selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
            return selected
        if (
            estimated_skill_speed is not None
            and BARD_ZORAAL_LOW_NINETIES_RAW_OVERCOUNT_SKILL_SPEED_MIN
            <= estimated_skill_speed
            <= BARD_ZORAAL_LOW_NINETIES_RAW_OVERCOUNT_SKILL_SPEED_MAX
            and BARD_ZORAAL_LOW_NINETIES_RAW_OVERCOUNT_PERCENT_MIN
            <= raw_percent
            <= BARD_ZORAAL_LOW_NINETIES_RAW_OVERCOUNT_PERCENT_MAX
            and BARD_ZORAAL_LOW_NINETIES_RAW_OVERCOUNT_DELTA_MIN
            <= graph_delta
            <= BARD_ZORAAL_LOW_NINETIES_RAW_OVERCOUNT_DELTA_MAX
        ):
            selected = adjusted_percent_coverage(
                raw_events_coverage,
                percent=raw_percent - BARD_ZORAAL_LOW_NINETIES_RAW_OVERCOUNT_ADJUSTMENT,
                fallback_selection="bard_raw_events_zoraal_low_nineties_raw_overcount_adjustment",
            )
            selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
            selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
            # raw 約 90%、graph gap 接近 8% 的佐拉加 Bard 會多吃一小段 Army/packet
            # 邊界；此型態比一般 large graph gap 更低，xivanalysis 顯示約 raw -1.3%。
            # 90.7% 且 graph gap 約 4% 的樣本已對齊 raw，不可套用此修正。
            return selected
        if (
            estimated_skill_speed is not None
            and estimated_skill_speed <= BARD_ZORAAL_MID_LOW_SPEED_UNDERCOUNT_SKILL_SPEED_MAX
            and BARD_ZORAAL_MID_LOW_SPEED_UNDERCOUNT_PERCENT_MIN
            <= raw_percent
            <= BARD_ZORAAL_MID_LOW_SPEED_UNDERCOUNT_PERCENT_MAX
            and BARD_ZORAAL_MID_LOW_SPEED_UNDERCOUNT_DELTA_MIN
            <= graph_delta
            <= BARD_ZORAAL_MID_LOW_SPEED_UNDERCOUNT_DELTA_MAX
        ):
            selected = adjusted_percent_coverage(
                raw_events_coverage,
                percent=raw_percent + BARD_ZORAAL_MID_LOW_SPEED_UNDERCOUNT_ADJUSTMENT,
                fallback_selection="bard_raw_events_zoraal_mid_low_speed_underestimate_adjustment",
            )
            selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
            selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
            # 同為 large graph gap 的 Zoraal Bard 大多貼近 raw；但 raw 約 93.5%、
            # 低估技速固定在 420 且 graph gap 約 4.3% 的樣本，xivanalysis 顯示會比
            # raw 多吃約 0.6 個百分點。此分支先於 keep-raw 大窗處理，避免把
            # 已驗證對齊的 93.8% / 87.8% large-gap 樣本一起推高。
            return selected
        if (
            estimated_skill_speed is not None
            and estimated_skill_speed <= BARD_ZORAAL_HIGH_NINETIES_LOW_SPEED_KEEP_RAW_SKILL_SPEED_MAX
            and BARD_ZORAAL_HIGH_NINETIES_LOW_SPEED_KEEP_RAW_PERCENT_MIN
            <= raw_percent
            <= BARD_ZORAAL_HIGH_NINETIES_LOW_SPEED_KEEP_RAW_PERCENT_MAX
            and BARD_ZORAAL_HIGH_NINETIES_LOW_SPEED_KEEP_RAW_DELTA_MIN
            <= graph_delta
            <= BARD_ZORAAL_HIGH_NINETIES_LOW_SPEED_KEEP_RAW_DELTA_MAX
        ):
            selected = dict(raw_events_coverage)
            selected["fallback_selection"] = "bard_raw_events_zoraal_high_nineties_low_speed_kept_raw"
            selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
            selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
            # 佐拉加 raw 約 96.7%、graph 已滿覆蓋且低技速由事件反推到 420 時，
            # xivanalysis 顯示仍等於 raw；若走通用 blend 會把 96.7% 推到 97.4%。
            # combatantinfo 的 96.7% 樣本另有站端貼近 blend 的型態，不共用此窗。
            return selected
        if (
            raw_events_coverage.get("speed_stat_source") == "combatantinfo"
            and BARD_ZORAAL_COMBATANT_LOW_RAW_OVERCOUNT_PERCENT_MIN
            <= raw_percent
            <= BARD_ZORAAL_COMBATANT_LOW_RAW_OVERCOUNT_PERCENT_MAX
            and BARD_ZORAAL_COMBATANT_LOW_RAW_OVERCOUNT_DELTA_MIN
            <= graph_delta
            <= BARD_ZORAAL_COMBATANT_LOW_RAW_OVERCOUNT_DELTA_MAX
        ):
            selected = adjusted_percent_coverage(
                raw_events_coverage,
                percent=raw_percent - BARD_ZORAAL_COMBATANT_LOW_RAW_OVERCOUNT_ADJUSTMENT,
                fallback_selection="bard_raw_events_zoraal_combatant_low_raw_overcount_adjustment",
            )
            selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
            selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
            # 同一位 Bard 在 combatantinfo 可用且 raw 約 87.5%、graph gap 約 6% 時，
            # Army/Muse packet 邊界會讓 raw 比 xivanalysis legacy 顯示多吃約 0.8%。
            # 低於此區間的 estimated 樣本與 85.9% high-speed 樣本已各自對齊 raw。
            return selected
        if (
            raw_events_coverage.get("speed_stat_source") == "combatantinfo"
            and BARD_ZORAAL_COMBATANT_MID_UNDERCOUNT_PERCENT_MIN
            <= raw_percent
            <= BARD_ZORAAL_COMBATANT_MID_UNDERCOUNT_PERCENT_MAX
            and BARD_ZORAAL_COMBATANT_MID_UNDERCOUNT_DELTA_MIN
            <= graph_delta
            <= BARD_ZORAAL_COMBATANT_MID_UNDERCOUNT_DELTA_MAX
        ):
            selected = adjusted_percent_coverage(
                raw_events_coverage,
                percent=raw_percent + BARD_ZORAAL_COMBATANT_MID_UNDERCOUNT_ADJUSTMENT,
                fallback_selection="bard_raw_events_zoraal_combatant_mid_underestimate_adjustment",
            )
            selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
            selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
            # combatantinfo 可用的 92% 左右 Bard 樣本，raw 少吃一段 Casts graph
            # lock；但 91.8% / 94.8% 附近已對齊 raw，因此只在這個百分比與 gap 窄窗補足。
            return selected
        if (
            BARD_ZORAAL_LARGE_GRAPH_GAP_KEEP_RAW_PERCENT_MIN
            <= raw_percent
            <= BARD_ZORAAL_LARGE_GRAPH_GAP_KEEP_RAW_PERCENT_MAX
            and graph_delta >= BARD_ZORAAL_LARGE_GRAPH_GAP_KEEP_RAW_DELTA_MIN
        ):
            selected = dict(raw_events_coverage)
            selected["fallback_selection"] = "bard_raw_events_zoraal_large_graph_gap_kept_raw"
            selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
            selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
            # 極佐拉加 Bard 的 Army/Muse 視窗會讓 Casts graph 比 raw 高三到四個
            # 百分點；xivanalysis legacy 頁面仍幾乎等於 raw events。若落入通用
            # raw/graph blend，會把 90-94% 樣本整體推高約一個顯示百分點。
            return selected
        if (
            raw_events_coverage.get("speed_stat_source") == "combatantinfo"
            and BARD_ZORAAL_COMBATANT_MID_RAW_OVERCOUNT_PERCENT_MIN
            <= raw_percent
            <= BARD_ZORAAL_COMBATANT_MID_RAW_OVERCOUNT_PERCENT_MAX
            and BARD_ZORAAL_COMBATANT_MID_RAW_OVERCOUNT_DELTA_MIN
            <= graph_delta
            <= BARD_ZORAAL_COMBATANT_MID_RAW_OVERCOUNT_DELTA_MAX
        ):
            selected = adjusted_percent_coverage(
                raw_events_coverage,
                percent=raw_percent - BARD_ZORAAL_COMBATANT_MID_RAW_OVERCOUNT_ADJUSTMENT,
                fallback_selection="bard_raw_events_zoraal_combatant_mid_raw_overcount_adjustment",
            )
            selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
            selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
            # combatantinfo 可用時，佐拉加 Bard raw 約 94%、graph gap 約 2.6% 的
            # 樣本在 legacy 頁面會略低於 raw；通用 blend 反而高估超過一個顯示百分點。
            # 此條件不觸碰同區間但 graph gap 約 2.37%、已對齊 blend 的樣本。
            return selected

    if (
        str(encounter_key or "") not in BARD_AAC_SAVAGE_RAW_EVENT_ENCOUNTERS
        and graph_percent > raw_percent
        and raw_percent >= BARD_RAW_GRAPH_BLEND_RAW_PERCENT_MIN
    ):
        selected = dict(raw_events_coverage)
        blend_ratio = BARD_RAW_GRAPH_BLEND_RATIO_BY_ENCOUNTER.get(
            str(encounter_key or ""),
            BARD_RAW_GRAPH_BLEND_RATIO,
        )
        adjusted_percent = min(100.0, raw_percent + (graph_percent - raw_percent) * blend_ratio)
        denominator_ms = to_number(raw_events_coverage.get("denominator_ms"))
        fallback_selection = "bard_raw_events_with_casts_graph_lock_blend"
        if str(encounter_key or "") == "extreme_zoraal_ja":
            estimated_skill_speed = to_number(raw_events_coverage.get("estimated_skill_speed"))
            gcd_cast_count = to_number(raw_events_coverage.get("gcd_cast_count"))
            zoraal_blend_window_matched = False
            for window in BARD_ZORAAL_BLEND_DISPLAY_OVERCOUNT_WINDOWS:
                if (
                    window["raw_percent_min"] <= raw_percent <= window["raw_percent_max"]
                    and window["graph_percent_min"] <= graph_percent <= window["graph_percent_max"]
                    and (
                        estimated_skill_speed is not None
                        and window["skill_speed_min"] <= estimated_skill_speed <= window["skill_speed_max"]
                    )
                    and (
                        denominator_ms is not None
                        and window["denominator_min"] <= denominator_ms <= window["denominator_max"]
                    )
                    and (
                        gcd_cast_count is not None
                        and window["gcd_count_min"] <= gcd_cast_count <= window["gcd_count_max"]
                    )
                ):
                    adjusted_percent -= window["adjustment"]
                    fallback_selection = (
                        "bard_raw_events_zoraal_"
                        f"{window['label']}_blend_display_overcount_adjustment"
                    )
                    zoraal_blend_window_matched = True
                    break
            if (
                not zoraal_blend_window_matched
                and raw_percent <= BARD_ZORAAL_BLEND_KEEP_RAW_PERCENT_MAX
                and denominator_ms is not None
                and gcd_cast_count is not None
            ):
                adjusted_percent = raw_percent
                fallback_selection = "bard_raw_events_zoraal_blend_kept_raw"
                # 2026-06-20 的極佐拉加 Bard top-ranking live 稽核顯示，
                # 一般 Army/Muse graph-lock blend 在 87-99.7% 區間會把
                # xivanalysis legacy 顯示值推高；除少數上方已逐筆驗證需微調的
                # blend display-overcount 視窗外，站端仍貼近 raw events。
        selected["percent"] = round(adjusted_percent, 2)
        if denominator_ms is not None:
            selected["covered_time_ms"] = round(denominator_ms * selected["percent"] / 100)
        selected["fallback_selection"] = fallback_selection
        selected["raw_events_percent"] = raw_events_coverage.get("percent")
        selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
        selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
        # Zoraal 的 Bard 在中高覆蓋率 Army 排除窗內仍會受 FFLogs raw packet 與
        # Casts graph lock 語意差異影響。xivanalysis 顯示值落在兩者之間；固定 seed 樣本
        # 顯示以 raw 分母為主、只混入少量 graph lock，可同時對齊 89%、94% 與接近
        # 100% 的 Bard。AAC 零式的外站頁面抽樣則仍貼近 raw events，不套這個混合修正。
        return selected

    return select_savage_bard_display_edge_coverage(
        raw_events_coverage,
        encounter_key=encounter_key,
        casts_graph_coverage=casts_graph_coverage,
    )


def select_valigarmanda_white_mage_coverage(
    raw_events_coverage: dict[str, Any] | None,
    casts_graph_coverage: dict[str, Any] | None,
    no_unable_speed_override_coverage: dict[str, Any] | None = None,
    *,
    encounter_key: str | None,
) -> dict[str, Any] | None:
    if not raw_events_coverage or not casts_graph_coverage:
        return raw_events_coverage or casts_graph_coverage
    if str(encounter_key or "") != "extreme_valigarmanda":
        return raw_events_coverage

    raw_percent = to_number(raw_events_coverage.get("percent"))
    graph_percent = to_number(casts_graph_coverage.get("percent"))
    if raw_percent is None or graph_percent is None:
        return raw_events_coverage

    delta = raw_percent - graph_percent
    override_percent = (
        to_number(no_unable_speed_override_coverage.get("percent"))
        if no_unable_speed_override_coverage
        else None
    )
    downtime_ms = to_number(raw_events_coverage.get("downtime_ms")) or 0.0
    if (
        no_unable_speed_override_coverage
        and override_percent is not None
        and VALIGARMANDA_WHM_LARGE_UNABLE_RAW_PERCENT_MIN
        <= raw_percent
        <= VALIGARMANDA_WHM_LARGE_UNABLE_RAW_PERCENT_MAX
        and VALIGARMANDA_WHM_LARGE_UNABLE_GRAPH_PERCENT_MIN
        <= graph_percent
        <= VALIGARMANDA_WHM_LARGE_UNABLE_GRAPH_PERCENT_MAX
        and downtime_ms >= VALIGARMANDA_WHM_LARGE_UNABLE_DOWNTIME_MIN_MS
        and VALIGARMANDA_WHM_LARGE_UNABLE_OVERRIDE_PERCENT_MIN
        <= override_percent
        <= VALIGARMANDA_WHM_LARGE_UNABLE_OVERRIDE_PERCENT_MAX
    ):
        selected = dict(no_unable_speed_override_coverage)
        selected["fallback_selection"] = "valigarmanda_white_mage_no_unable_speed_override_large_uta"
        selected["raw_events_percent"] = raw_events_coverage.get("percent")
        selected["raw_events_denominator_ms"] = raw_events_coverage.get("denominator_ms")
        selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
        selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
        selected["estimated_spell_speed"] = raw_events_coverage.get("estimated_spell_speed")
        selected["override_spell_speed"] = VALIGARMANDA_WHM_LARGE_UNABLE_SPEED_OVERRIDE_SPELL_SPEED
        # 極瓦利加爾曼達 WHM 少數長時間 UnableToAct 場次若把 UTA 全扣掉，分母會短到
        # 比 xivanalysis 站端顯示高出數個百分點。站端顯示更接近保留 graph 分母、並沿用
        # legacy actorUpdate 可低於遊戲下限的 estimated spell speed。條件需同時具備巨大
        # UTA downtime 與低 graph percent，避免一般 WHM 低覆蓋率樣本被誤套。
        return selected

    if (
        raw_percent <= VALIGARMANDA_WHM_GRAPH_FALLBACK_RAW_PERCENT_MAX
        and VALIGARMANDA_WHM_GRAPH_FALLBACK_DELTA_MIN <= delta <= VALIGARMANDA_WHM_GRAPH_FALLBACK_DELTA_MAX
    ):
        selected = dict(casts_graph_coverage)
        selected["fallback_selection"] = "valigarmanda_white_mage_casts_graph_low_uptime"
        selected["raw_events_percent"] = raw_events_coverage.get("percent")
        selected["raw_events_denominator_ms"] = raw_events_coverage.get("denominator_ms")
        # 極瓦利加爾曼達 WHM 多數樣本需要 raw downtime；但低 ABC 且 raw 只比 graph
        # 高約一到兩個百分點時，raw targetability/UTA 會把 Presence of Mind 附近
        # 的 lock 吃得略滿。此時回 Casts graph 會更貼近 xivanalysis 顯示值。
        return selected

    return raw_events_coverage


def select_valigarmanda_astrologian_coverage(
    raw_events_coverage: dict[str, Any] | None,
    casts_graph_coverage: dict[str, Any] | None,
    speed_override_coverage: dict[str, Any] | None = None,
    *,
    encounter_key: str | None,
) -> dict[str, Any] | None:
    if not raw_events_coverage or not casts_graph_coverage:
        return raw_events_coverage or casts_graph_coverage
    if str(encounter_key or "") != "extreme_valigarmanda":
        return raw_events_coverage

    raw_percent = to_number(raw_events_coverage.get("percent"))
    graph_percent = to_number(casts_graph_coverage.get("percent"))
    if raw_percent is None or graph_percent is None:
        return raw_events_coverage

    delta = raw_percent - graph_percent
    downtime_ms = to_number(raw_events_coverage.get("downtime_ms")) or 0.0
    denominator_ms = to_number(raw_events_coverage.get("denominator_ms")) or 0.0
    spell_speed = to_number(raw_events_coverage.get("estimated_spell_speed"))
    gcd_cast_count = to_number(raw_events_coverage.get("gcd_cast_count"))
    override_percent = to_number(speed_override_coverage.get("percent")) if speed_override_coverage else None

    if (
        raw_events_coverage.get("speed_stat_source") == "estimated"
        and spell_speed is not None
        and gcd_cast_count is not None
        and VALIGARMANDA_AST_LOW_RAW_UNDERCOUNT_PERCENT_MIN
        <= raw_percent
        <= VALIGARMANDA_AST_LOW_RAW_UNDERCOUNT_PERCENT_MAX
        and VALIGARMANDA_AST_LOW_RAW_UNDERCOUNT_GRAPH_PERCENT_MIN
        <= graph_percent
        <= VALIGARMANDA_AST_LOW_RAW_UNDERCOUNT_GRAPH_PERCENT_MAX
        and VALIGARMANDA_AST_LOW_RAW_UNDERCOUNT_DELTA_MIN
        <= delta
        <= VALIGARMANDA_AST_LOW_RAW_UNDERCOUNT_DELTA_MAX
        and VALIGARMANDA_AST_LOW_RAW_UNDERCOUNT_SPELL_SPEED_MIN
        <= spell_speed
        <= VALIGARMANDA_AST_LOW_RAW_UNDERCOUNT_SPELL_SPEED_MAX
        and VALIGARMANDA_AST_LOW_RAW_UNDERCOUNT_DENOMINATOR_MIN_MS
        <= denominator_ms
        <= VALIGARMANDA_AST_LOW_RAW_UNDERCOUNT_DENOMINATOR_MAX_MS
        and VALIGARMANDA_AST_LOW_RAW_UNDERCOUNT_GCD_COUNT_MIN
        <= gcd_cast_count
        <= VALIGARMANDA_AST_LOW_RAW_UNDERCOUNT_GCD_COUNT_MAX
        and VALIGARMANDA_AST_LOW_RAW_UNDERCOUNT_DOWNTIME_MIN_MS
        <= downtime_ms
        <= VALIGARMANDA_AST_LOW_RAW_UNDERCOUNT_DOWNTIME_MAX_MS
    ):
        return adjusted_percent_coverage(
            raw_events_coverage,
            percent=raw_percent + VALIGARMANDA_AST_LOW_RAW_UNDERCOUNT_ADJUSTMENT,
            fallback_selection="valigarmanda_astrologian_low_raw_underestimate_adjustment",
            diagnostics={
                "casts_graph_percent": casts_graph_coverage.get("percent"),
                "casts_graph_denominator_ms": casts_graph_coverage.get("denominator_ms"),
                "raw_graph_gap": delta,
            },
        )

    if (
        speed_override_coverage
        and override_percent is not None
        and raw_events_coverage.get("speed_stat_source") == "estimated"
        and VALIGARMANDA_AST_ESTIMATED_SPEED_RAW_PERCENT_MIN
        <= raw_percent
        <= VALIGARMANDA_AST_ESTIMATED_SPEED_RAW_PERCENT_MAX
        and VALIGARMANDA_AST_ESTIMATED_SPEED_GRAPH_DELTA_MIN
        <= delta
        <= VALIGARMANDA_AST_ESTIMATED_SPEED_GRAPH_DELTA_MAX
        and VALIGARMANDA_AST_ESTIMATED_SPEED_DOWNTIME_MIN_MS
        <= downtime_ms
        <= VALIGARMANDA_AST_ESTIMATED_SPEED_DOWNTIME_MAX_MS
        and denominator_ms >= VALIGARMANDA_AST_ESTIMATED_SPEED_DENOMINATOR_MIN_MS
    ):
        selected = dict(speed_override_coverage)
        selected["fallback_selection"] = "valigarmanda_astrologian_estimated_speed_override"
        selected["raw_events_percent"] = raw_events_coverage.get("percent")
        selected["raw_events_denominator_ms"] = raw_events_coverage.get("denominator_ms")
        selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
        selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
        selected["estimated_spell_speed"] = raw_events_coverage.get("estimated_spell_speed")
        selected["override_spell_speed"] = VALIGARMANDA_AST_ESTIMATED_SPEED_OVERRIDE_SPELL_SPEED
        # 極瓦利加爾曼達 AST 缺 combatantinfo 時，多數樣本 raw events 已對齊；但
        # raw/graph gap 約 1.5%、且分母超過 10 分鐘的低覆蓋率樣本，xivanalysis
        # 顯示值等同於較高的 legacy actorUpdate 詠速。使用額外 coverage 作選擇，
        # 讓回補輸出保留原始 estimated speed 與 override speed 供日後稽核。
        return selected

    if (
        raw_events_coverage.get("speed_stat_source") == "combatantinfo"
        and VALIGARMANDA_AST_COMBATANTINFO_ADJUSTMENT_RAW_PERCENT_MIN
        <= raw_percent
        <= VALIGARMANDA_AST_COMBATANTINFO_ADJUSTMENT_RAW_PERCENT_MAX
        and VALIGARMANDA_AST_COMBATANTINFO_ADJUSTMENT_GRAPH_DELTA_MIN
        <= delta
        <= VALIGARMANDA_AST_COMBATANTINFO_ADJUSTMENT_GRAPH_DELTA_MAX
        and VALIGARMANDA_AST_COMBATANTINFO_ADJUSTMENT_DOWNTIME_MIN_MS
        <= downtime_ms
        <= VALIGARMANDA_AST_COMBATANTINFO_ADJUSTMENT_DOWNTIME_MAX_MS
    ):
        return adjusted_percent_coverage(
            raw_events_coverage,
            percent=raw_percent + VALIGARMANDA_AST_COMBATANTINFO_ADJUSTMENT,
            fallback_selection="valigarmanda_astrologian_combatantinfo_packet_boundary_adjustment",
            diagnostics={
                "casts_graph_percent": casts_graph_coverage.get("percent"),
                "casts_graph_denominator_ms": casts_graph_coverage.get("denominator_ms"),
                "raw_graph_gap": delta,
            },
        )

    return raw_events_coverage


def select_valigarmanda_dancer_coverage(
    raw_events_coverage: dict[str, Any] | None,
    casts_graph_coverage: dict[str, Any] | None,
    *,
    encounter_key: str | None,
) -> dict[str, Any] | None:
    if not raw_events_coverage or not casts_graph_coverage:
        return raw_events_coverage or casts_graph_coverage
    if str(encounter_key or "") != "extreme_valigarmanda":
        return raw_events_coverage

    raw_percent = to_number(raw_events_coverage.get("percent"))
    graph_percent = to_number(casts_graph_coverage.get("percent"))
    if raw_percent is None or graph_percent is None:
        return raw_events_coverage

    downtime_ms = to_number(raw_events_coverage.get("downtime_ms")) or 0.0
    denominator_ms = to_number(raw_events_coverage.get("denominator_ms")) or 0.0
    estimated_skill_speed = to_number(raw_events_coverage.get("estimated_skill_speed"))
    if (
        raw_events_coverage.get("speed_stat_source") == "estimated"
        and estimated_skill_speed == VALIGARMANDA_DNC_HIGH_RAW_UNDERCOUNT_ESTIMATED_SKILL_SPEED
        and VALIGARMANDA_DNC_HIGH_RAW_UNDERCOUNT_PERCENT_MIN
        <= raw_percent
        <= VALIGARMANDA_DNC_HIGH_RAW_UNDERCOUNT_PERCENT_MAX
        and downtime_ms <= VALIGARMANDA_DNC_HIGH_RAW_UNDERCOUNT_DOWNTIME_MAX_MS
        and VALIGARMANDA_DNC_HIGH_RAW_UNDERCOUNT_DENOMINATOR_MIN_MS
        <= denominator_ms
        <= VALIGARMANDA_DNC_HIGH_RAW_UNDERCOUNT_DENOMINATOR_MAX_MS
        and abs(graph_percent - raw_percent) <= 0.05
    ):
        selected = adjusted_percent_coverage(
            raw_events_coverage,
            percent=raw_percent + VALIGARMANDA_DNC_HIGH_RAW_UNDERCOUNT_ADJUSTMENT,
            fallback_selection="valigarmanda_dancer_high_uptime_packet_boundary_adjustment",
        )
        selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
        selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
        # 此型態是 Valigarmanda DNC 無 downtime 且 raw/Casts graph 都卡在 98% 的高覆蓋率
        # 樣本；xivanalysis 顯示值比 FFLogs packet lock 多約半個百分點。條件包含分母區間
        # 與 estimated skill speed，避免把其他 97-98% 的 DNC 場次整體推高。
        return selected

    return raw_events_coverage


