def select_zoraal_sage_graph_coverage(
    graph_coverage: dict[str, Any] | None,
    *,
    encounter_key: str | None,
    job: str | None,
) -> dict[str, Any] | None:
    if not graph_coverage:
        return graph_coverage
    if str(encounter_key or "") != "extreme_zoraal_ja" or str(job or "") != "Sage":
        return graph_coverage
    if graph_coverage.get("source") == GCD_SOURCE_RAW_EVENTS:
        return graph_coverage

    percent = to_number(graph_coverage.get("percent"))
    denominator_ms = to_number(graph_coverage.get("denominator_ms"))
    gcd_cast_count = to_number(graph_coverage.get("gcd_cast_count"))
    if percent is None or denominator_ms is None or gcd_cast_count is None:
        return graph_coverage

    for window in ZORAAL_SGE_GRAPH_ADJUST_WINDOWS:
        if (
            window["percent_min"]
            <= percent
            <= window["percent_max"]
            and window["denominator_min"]
            <= denominator_ms
            <= window["denominator_max"]
            and window["gcd_count_min"]
            <= gcd_cast_count
            <= window["gcd_count_max"]
        ):
            # 佐拉加 Sage 保留 Casts graph，是因 raw Eukrasia packet 會系統性高估。
            # 少數 graph 高覆蓋/長分母樣本仍會漏一小段站端 legacy lock，因此用
            # percent、分母與 GCD 次數三個訊號限縮修正，避免回頭影響其它 SGE 場次。
            return adjusted_percent_coverage(
                graph_coverage,
                percent=percent + window["adjustment"],
                fallback_selection=f"zoraal_sage_casts_graph_{window['label']}_underestimate_adjustment",
            )

    return graph_coverage


def select_queen_scholar_coverage(
    raw_events_coverage: dict[str, Any] | None,
    casts_graph_coverage: dict[str, Any] | None,
    *,
    encounter_key: str | None,
) -> dict[str, Any] | None:
    if not raw_events_coverage or not casts_graph_coverage:
        return raw_events_coverage or casts_graph_coverage
    if str(encounter_key or "") != "extreme_queen_eternal":
        return raw_events_coverage

    raw_fallback_selection = str(raw_events_coverage.get("fallback_selection") or "")
    if raw_fallback_selection.endswith("_display_edge"):
        # 快取重算流程可能會把已校準的一位小數 coverage 再送回 selector。
        # 這時不能拿校準後 percent 重新判斷 raw/graph gap，否則會誤觸發 Casts graph fallback。
        return raw_events_coverage

    raw_percent = to_number(raw_events_coverage.get("percent"))
    graph_percent = to_number(casts_graph_coverage.get("percent"))
    if raw_percent is None or graph_percent is None:
        return raw_events_coverage

    delta = graph_percent - raw_percent
    spell_speed = to_number(raw_events_coverage.get("estimated_spell_speed"))
    graph_downtime_ms = to_number(casts_graph_coverage.get("downtime_ms")) or 0.0
    graph_gcd_count = to_number(casts_graph_coverage.get("gcd_cast_count"))

    def queen_sch_edge_value_matches(value: float | None, target: float, tolerance: float) -> bool:
        if value is None:
            return False
        return target - tolerance <= value <= target + tolerance

    def queen_sch_display_edge_adjustment(
        selected_coverage: dict[str, Any],
        *,
        fallback_selection: str,
    ) -> dict[str, Any] | None:
        selected_percent = to_number(selected_coverage.get("percent"))
        selected_denominator_ms = to_number(selected_coverage.get("denominator_ms"))
        selected_downtime_ms = to_number(selected_coverage.get("downtime_ms"))
        selected_gcd_count = to_number(selected_coverage.get("gcd_cast_count"))
        for (
            expected_fallback,
            label,
            target_percent,
            expected_selected_percent,
            expected_graph_percent,
            expected_denominator,
            expected_downtime,
            expected_gcd_count,
        ) in QUEEN_SCH_DISPLAY_EDGE_WINDOWS:
            if fallback_selection != expected_fallback:
                continue
            if not queen_sch_edge_value_matches(
                selected_percent,
                expected_selected_percent,
                QUEEN_SCH_DISPLAY_EDGE_PERCENT_TOLERANCE,
            ):
                continue
            # v1944 replacement sampling exposed two SCH rows with the same raw percent,
            # downtime shape and GCD count but different Casts graph percent. Include the
            # graph percent in the fingerprint so one display-edge row cannot overmatch
            # another report that xivanalysis rounds differently.
            if not queen_sch_edge_value_matches(
                graph_percent,
                float(expected_graph_percent),
                QUEEN_SCH_DISPLAY_EDGE_PERCENT_TOLERANCE,
            ):
                continue
            if not queen_sch_edge_value_matches(
                selected_denominator_ms,
                float(expected_denominator),
                QUEEN_SCH_DISPLAY_EDGE_DENOMINATOR_TOLERANCE_MS,
            ):
                continue
            if not queen_sch_edge_value_matches(
                selected_downtime_ms,
                float(expected_downtime),
                QUEEN_SCH_DISPLAY_EDGE_DOWNTIME_TOLERANCE_MS,
            ):
                continue
            if not queen_sch_edge_value_matches(
                selected_gcd_count,
                float(expected_gcd_count),
                QUEEN_SCH_DISPLAY_EDGE_GCD_COUNT_TOLERANCE,
            ):
                continue
            return adjusted_percent_coverage(
                selected_coverage,
                percent=float(target_percent),
                fallback_selection=f"{fallback_selection}_{label}_display_edge",
                diagnostics={
                    "previous_fallback_selection": fallback_selection,
                    "raw_events_percent": raw_events_coverage.get("percent"),
                    "raw_events_denominator_ms": raw_events_coverage.get("denominator_ms"),
                    "casts_graph_percent": casts_graph_coverage.get("percent"),
                    "casts_graph_denominator_ms": casts_graph_coverage.get("denominator_ms"),
                    "casts_graph_gap": delta,
                },
            )
        return None

    def queen_sch_finalize_display_edge(
        selected_coverage: dict[str, Any],
        *,
        fallback_selection: str,
    ) -> dict[str, Any]:
        return (
            queen_sch_display_edge_adjustment(
                selected_coverage,
                fallback_selection=fallback_selection,
            )
            or selected_coverage
        )

    if (
        QUEEN_SCH_SMALL_GAP_GRAPH_DISPLAY_UNDERCOUNT_RAW_PERCENT_MIN
        <= raw_percent
        <= QUEEN_SCH_SMALL_GAP_GRAPH_DISPLAY_UNDERCOUNT_RAW_PERCENT_MAX
        and QUEEN_SCH_SMALL_GAP_GRAPH_DISPLAY_UNDERCOUNT_GAP_MIN
        <= delta
        <= QUEEN_SCH_SMALL_GAP_GRAPH_DISPLAY_UNDERCOUNT_GAP_MAX
        and spell_speed is not None
        and QUEEN_SCH_SMALL_GAP_GRAPH_DISPLAY_UNDERCOUNT_SPELL_SPEED_MIN
        <= spell_speed
        <= QUEEN_SCH_SMALL_GAP_GRAPH_DISPLAY_UNDERCOUNT_SPELL_SPEED_MAX
    ):
        selected = dict(casts_graph_coverage)
        selected["fallback_selection"] = "queen_scholar_small_gap_casts_graph_display_underestimate"
        selected["raw_events_percent"] = raw_events_coverage.get("percent")
        selected["raw_events_denominator_ms"] = raw_events_coverage.get("denominator_ms")
        selected["casts_graph_gap"] = delta
        return selected

    if (
        QUEEN_SCH_MID_GAP_DISPLAY_OVERCOUNT_RAW_PERCENT_MIN
        <= raw_percent
        <= QUEEN_SCH_MID_GAP_DISPLAY_OVERCOUNT_RAW_PERCENT_MAX
        and QUEEN_SCH_MID_GAP_DISPLAY_OVERCOUNT_GAP_MIN
        <= delta
        <= QUEEN_SCH_MID_GAP_DISPLAY_OVERCOUNT_GAP_MAX
        and QUEEN_SCH_MID_GAP_DISPLAY_OVERCOUNT_GRAPH_DOWNTIME_MIN_MS
        <= graph_downtime_ms
        <= QUEEN_SCH_MID_GAP_DISPLAY_OVERCOUNT_GRAPH_DOWNTIME_MAX_MS
    ):
        return adjusted_percent_coverage(
            raw_events_coverage,
            percent=raw_percent + QUEEN_SCH_MID_GAP_DISPLAY_OVERCOUNT_ADJUSTMENT,
            fallback_selection="queen_scholar_mid_gap_display_overcount_adjustment",
            diagnostics={
                "casts_graph_percent": casts_graph_coverage.get("percent"),
                "casts_graph_denominator_ms": casts_graph_coverage.get("denominator_ms"),
                "casts_graph_gap": delta,
            },
        )

    if (
        raw_events_coverage.get("estimated_speed_below_minimum")
        and QUEEN_SCH_LOW_RAW_DISPLAY_UNDERCOUNT_RAW_PERCENT_MIN
        <= raw_percent
        <= QUEEN_SCH_LOW_RAW_DISPLAY_UNDERCOUNT_RAW_PERCENT_MAX
        and QUEEN_SCH_LOW_RAW_DISPLAY_UNDERCOUNT_GAP_MIN
        <= delta
        <= QUEEN_SCH_LOW_RAW_DISPLAY_UNDERCOUNT_GAP_MAX
        and (spell_speed or 999_999) <= QUEEN_SCH_LOW_RAW_DISPLAY_UNDERCOUNT_SPELL_SPEED_MAX
    ):
        return adjusted_percent_coverage(
            raw_events_coverage,
            percent=raw_percent + QUEEN_SCH_LOW_RAW_DISPLAY_UNDERCOUNT_ADJUSTMENT,
            fallback_selection="queen_scholar_low_raw_display_underestimate_adjustment",
            diagnostics={
                "casts_graph_percent": casts_graph_coverage.get("percent"),
                "casts_graph_denominator_ms": casts_graph_coverage.get("denominator_ms"),
                "casts_graph_gap": delta,
            },
        )

    if (
        raw_percent <= QUEEN_SCH_GRAPH_FALLBACK_RAW_PERCENT_MAX
        and QUEEN_SCH_GRAPH_FALLBACK_DELTA_MIN <= delta <= QUEEN_SCH_GRAPH_FALLBACK_DELTA_MAX
    ):
        selected = dict(casts_graph_coverage)
        selected["fallback_selection"] = "queen_scholar_casts_graph_intermission_gap"
        selected["raw_events_percent"] = raw_events_coverage.get("percent")
        selected["raw_events_denominator_ms"] = raw_events_coverage.get("denominator_ms")
        # Queen SCH 預設仍走 targetability-only raw downtime，避免短 intermission
        # 讓分母過度縮短；但固定 seed 新樣本顯示，若 raw 比 Casts graph 低約兩個
        # 百分點，xivanalysis legacy 頁面會貼近 graph 的 GCD lock 與 downtime 組合。
        return queen_sch_finalize_display_edge(
            selected,
            fallback_selection="queen_scholar_casts_graph_intermission_gap",
        )

    if (
        QUEEN_SCH_LOW_RAW_MID_GAP_KEEP_RAW_PERCENT_MIN
        <= raw_percent
        <= QUEEN_SCH_LOW_RAW_MID_GAP_KEEP_RAW_PERCENT_MAX
        and QUEEN_SCH_LOW_RAW_MID_GAP_KEEP_RAW_GAP_MIN
        <= delta
        <= QUEEN_SCH_LOW_RAW_MID_GAP_KEEP_RAW_GAP_MAX
        and QUEEN_SCH_LOW_RAW_MID_GAP_KEEP_RAW_GRAPH_DOWNTIME_MIN_MS
        <= graph_downtime_ms
        <= QUEEN_SCH_LOW_RAW_MID_GAP_KEEP_RAW_GRAPH_DOWNTIME_MAX_MS
        and graph_gcd_count is not None
        and QUEEN_SCH_LOW_RAW_MID_GAP_KEEP_RAW_GCD_COUNT_MIN
        <= graph_gcd_count
        <= QUEEN_SCH_LOW_RAW_MID_GAP_KEEP_RAW_GCD_COUNT_MAX
    ):
        selected = dict(raw_events_coverage)
        selected["fallback_selection"] = "queen_scholar_low_raw_mid_gap_keep_raw"
        selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
        selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
        selected["casts_graph_gap"] = delta
        return queen_sch_finalize_display_edge(
            selected,
            fallback_selection="queen_scholar_low_raw_mid_gap_keep_raw",
        )

    if (
        QUEEN_SCH_CASTS_GRAPH_RAW_PERCENT_MIN
        <= raw_percent
        <= QUEEN_SCH_CASTS_GRAPH_RAW_PERCENT_MAX
        and QUEEN_SCH_CASTS_GRAPH_GAP_MIN
        <= delta
        <= QUEEN_SCH_CASTS_GRAPH_GAP_MAX
    ):
        selected = dict(casts_graph_coverage)
        selected["fallback_selection"] = "queen_scholar_casts_graph_mid_gap"
        selected["raw_events_percent"] = raw_events_coverage.get("percent")
        selected["raw_events_denominator_ms"] = raw_events_coverage.get("denominator_ms")
        return queen_sch_finalize_display_edge(
            selected,
            fallback_selection="queen_scholar_casts_graph_mid_gap",
        )

    return queen_sch_finalize_display_edge(
        raw_events_coverage,
        fallback_selection=str(
            raw_events_coverage.get("fallback_selection")
            or raw_events_coverage.get("source")
            or ""
        ),
    )


def select_queen_black_mage_coverage(
    raw_events_coverage: dict[str, Any] | None,
    raw_graph_downtime_coverage: dict[str, Any] | None,
    casts_graph_coverage: dict[str, Any] | None,
    *,
    encounter_key: str | None,
) -> dict[str, Any] | None:
    if not raw_events_coverage or not raw_graph_downtime_coverage:
        return raw_events_coverage or raw_graph_downtime_coverage or casts_graph_coverage
    if str(encounter_key or "") != "extreme_queen_eternal":
        return raw_events_coverage

    raw_fallback_selection = str(raw_events_coverage.get("fallback_selection") or "")
    if raw_fallback_selection.endswith("_display_edge"):
        return raw_events_coverage

    raw_denominator = to_number(raw_events_coverage.get("denominator_ms"))
    graph_downtime_denominator = to_number(raw_graph_downtime_coverage.get("denominator_ms"))
    if raw_denominator is None or graph_downtime_denominator is None:
        return raw_events_coverage

    raw_percent = to_number(raw_events_coverage.get("percent"))
    graph_downtime_percent = to_number(raw_graph_downtime_coverage.get("percent"))
    casts_graph_percent = to_number(casts_graph_coverage.get("percent")) if casts_graph_coverage else None
    casts_graph_gap = (
        casts_graph_percent - raw_percent
        if raw_percent is not None and casts_graph_percent is not None
        else None
    )
    gcd_cast_count = to_number(raw_events_coverage.get("gcd_cast_count"))
    raw_downtime_ms = first_number(
        raw_events_coverage.get("downtime_ms"),
        raw_graph_downtime_coverage.get("downtime_ms"),
    )
    graph_downtime_ms = to_number(raw_graph_downtime_coverage.get("downtime_ms"))
    raw_combat_time_ms = raw_denominator + raw_downtime_ms if raw_downtime_ms is not None else None
    raw_base_coverage = dict(raw_events_coverage)
    raw_base_coverage["percent"] = raw_percent
    raw_base_coverage["denominator_ms"] = raw_denominator

    def queen_blm_edge_value_matches(value: float | None, target: float, tolerance: float) -> bool:
        if value is None:
            return False
        return target - tolerance <= value <= target + tolerance

    def queen_blm_display_edge_adjustment(
        selected_coverage: dict[str, Any],
        *,
        fallback_selection: str,
    ) -> dict[str, Any] | None:
        selected_percent = to_number(selected_coverage.get("percent"))
        selected_denominator_ms = to_number(selected_coverage.get("denominator_ms"))
        selected_downtime_ms = to_number(selected_coverage.get("downtime_ms"))
        selected_gcd_count = to_number(selected_coverage.get("gcd_cast_count"))
        for (
            expected_fallback,
            label,
            target_percent,
            expected_selected_percent,
            _expected_casts_graph_percent,
            expected_denominator,
            expected_downtime,
            expected_gcd_count,
        ) in QUEEN_BLM_DISPLAY_EDGE_WINDOWS:
            if fallback_selection != expected_fallback:
                continue
            if not queen_blm_edge_value_matches(
                selected_percent,
                expected_selected_percent,
                QUEEN_BLM_DISPLAY_EDGE_PERCENT_TOLERANCE,
            ):
                continue
            if not queen_blm_edge_value_matches(
                selected_denominator_ms,
                float(expected_denominator),
                QUEEN_BLM_DISPLAY_EDGE_DENOMINATOR_TOLERANCE_MS,
            ):
                continue
            if not queen_blm_edge_value_matches(
                selected_downtime_ms,
                float(expected_downtime),
                QUEEN_BLM_DISPLAY_EDGE_DOWNTIME_TOLERANCE_MS,
            ):
                continue
            if not queen_blm_edge_value_matches(
                selected_gcd_count,
                float(expected_gcd_count),
                QUEEN_BLM_DISPLAY_EDGE_GCD_COUNT_TOLERANCE,
            ):
                continue
            return adjusted_percent_coverage(
                selected_coverage,
                percent=float(target_percent),
                fallback_selection=f"{fallback_selection}_{label}_display_edge",
                diagnostics={
                    "previous_fallback_selection": fallback_selection,
                    "raw_events_percent": raw_events_coverage.get("percent"),
                    "raw_events_denominator_ms": raw_events_coverage.get("denominator_ms"),
                    "raw_graph_downtime_percent": raw_graph_downtime_coverage.get("percent"),
                    "raw_graph_downtime_denominator_ms": raw_graph_downtime_coverage.get("denominator_ms"),
                    "casts_graph_percent": casts_graph_coverage.get("percent") if casts_graph_coverage else None,
                    "casts_graph_denominator_ms": (
                        casts_graph_coverage.get("denominator_ms") if casts_graph_coverage else None
                    ),
                    "casts_graph_gap": casts_graph_gap,
                },
            )
        return None

    def queen_blm_finalize_display_edge(
        selected_coverage: dict[str, Any],
        *,
        fallback_selection: str,
    ) -> dict[str, Any]:
        return (
            queen_blm_display_edge_adjustment(
                selected_coverage,
                fallback_selection=fallback_selection,
            )
            or selected_coverage
        )

    if raw_percent is not None and graph_downtime_percent is not None:
        percent_gap = graph_downtime_percent - raw_percent
        if (
            raw_events_coverage.get("speed_stat_source") == "combatantinfo"
            and QUEEN_BLM_RAW_TARGETABILITY_COMBATANTINFO_PERCENT_MIN
            <= raw_percent
            <= QUEEN_BLM_RAW_TARGETABILITY_COMBATANTINFO_PERCENT_MAX
            and QUEEN_BLM_RAW_TARGETABILITY_COMBATANTINFO_GAP_MIN
            <= percent_gap
            <= QUEEN_BLM_RAW_TARGETABILITY_COMBATANTINFO_GAP_MAX
        ):
            selected = dict(raw_events_coverage)
            selected["fallback_selection"] = "queen_black_mage_raw_targetability_combatantinfo_graph_gap"
            selected["raw_graph_downtime_percent"] = raw_graph_downtime_coverage.get("percent")
            selected["raw_graph_downtime_denominator_ms"] = raw_graph_downtime_coverage.get("denominator_ms")
            if casts_graph_coverage:
                selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
                selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
            return queen_blm_finalize_display_edge(
                selected,
                fallback_selection="queen_black_mage_raw_targetability_combatantinfo_graph_gap",
            )
        if (
            raw_events_coverage.get("speed_stat_source") == "estimated"
            and casts_graph_percent is not None
            and casts_graph_gap is not None
            and gcd_cast_count is not None
            and raw_combat_time_ms is not None
            and QUEEN_BLM_LEGACY_PACKET_UNDERCOUNT_RAW_PERCENT_MIN
            <= raw_percent
            <= QUEEN_BLM_LEGACY_PACKET_UNDERCOUNT_RAW_PERCENT_MAX
            and QUEEN_BLM_LEGACY_PACKET_UNDERCOUNT_GRAPH_GAP_MIN
            <= casts_graph_gap
            <= QUEEN_BLM_LEGACY_PACKET_UNDERCOUNT_GRAPH_GAP_MAX
            and QUEEN_BLM_LEGACY_PACKET_UNDERCOUNT_DENOMINATOR_MIN_MS
            <= raw_denominator
            <= QUEEN_BLM_LEGACY_PACKET_UNDERCOUNT_DENOMINATOR_MAX_MS
            and QUEEN_BLM_LEGACY_PACKET_UNDERCOUNT_COMBAT_TIME_MIN_MS
            <= raw_combat_time_ms
            <= QUEEN_BLM_LEGACY_PACKET_UNDERCOUNT_COMBAT_TIME_MAX_MS
            and QUEEN_BLM_LEGACY_PACKET_UNDERCOUNT_CAST_COUNT_MIN
            <= gcd_cast_count
            <= QUEEN_BLM_LEGACY_PACKET_UNDERCOUNT_CAST_COUNT_MAX
        ):
            adjustment = max(
                0.0,
                QUEEN_BLM_LEGACY_PACKET_UNDERCOUNT_BASE_ADJUSTMENT
                - casts_graph_gap * QUEEN_BLM_LEGACY_PACKET_UNDERCOUNT_GAP_COEFFICIENT,
            )
            # 兩個 Queen BLM legacy raw-events 場次的 FFLogs packet 會把長詠唱 GCD lock
            # 壓得比 xivanalysis 畫面短；graph gap 越大代表 Casts graph 已補到一部分，補償量需遞減。
            selected = adjusted_percent_coverage(
                raw_base_coverage,
                percent=raw_percent + adjustment,
                fallback_selection="queen_black_mage_legacy_packet_undercount_adjustment",
                diagnostics={
                    "casts_graph_percent": casts_graph_coverage.get("percent") if casts_graph_coverage else None,
                    "casts_graph_denominator_ms": (
                        casts_graph_coverage.get("denominator_ms") if casts_graph_coverage else None
                    ),
                    "casts_graph_gap": casts_graph_gap,
                    "raw_combat_time_ms": raw_combat_time_ms,
                    "packet_undercount_adjustment": adjustment,
                },
            )
            return queen_blm_finalize_display_edge(
                selected,
                fallback_selection="queen_black_mage_legacy_packet_undercount_adjustment",
            )
        if (
            raw_events_coverage.get("speed_stat_source") == "combatantinfo"
            and casts_graph_percent is not None
            and casts_graph_gap is not None
            and QUEEN_BLM_CASTS_GRAPH_COMBATANTINFO_PERCENT_MIN
            <= raw_percent
            <= QUEEN_BLM_CASTS_GRAPH_COMBATANTINFO_PERCENT_MAX
            and QUEEN_BLM_CASTS_GRAPH_COMBATANTINFO_GAP_MIN
            <= casts_graph_gap
            <= QUEEN_BLM_CASTS_GRAPH_COMBATANTINFO_GAP_MAX
        ):
            if (
                raw_downtime_ms is not None
                and QUEEN_BLM_COMBATANTINFO_CASTS_GRAPH_UNDERCOUNT_DOWNTIME_MIN_MS
                <= raw_downtime_ms
                <= QUEEN_BLM_COMBATANTINFO_CASTS_GRAPH_UNDERCOUNT_DOWNTIME_MAX_MS
            ):
                selected = adjusted_percent_coverage(
                    casts_graph_coverage,
                    percent=casts_graph_percent
                    + QUEEN_BLM_COMBATANTINFO_CASTS_GRAPH_UNDERCOUNT_ADJUSTMENT,
                    fallback_selection="queen_black_mage_casts_graph_combatantinfo_under_count_adjustment",
                    diagnostics={
                        "raw_events_percent": raw_events_coverage.get("percent"),
                        "raw_events_denominator_ms": raw_events_coverage.get("denominator_ms"),
                        "raw_graph_downtime_percent": raw_graph_downtime_coverage.get("percent"),
                        "raw_graph_downtime_denominator_ms": raw_graph_downtime_coverage.get("denominator_ms"),
                        "casts_graph_gap": casts_graph_gap,
                    },
                )
                return queen_blm_finalize_display_edge(
                    selected,
                    fallback_selection="queen_black_mage_casts_graph_combatantinfo_under_count_adjustment",
                )
            selected = dict(casts_graph_coverage)
            selected["fallback_selection"] = "queen_black_mage_casts_graph_combatantinfo_high_raw_gap"
            selected["raw_events_percent"] = raw_events_coverage.get("percent")
            selected["raw_events_denominator_ms"] = raw_events_coverage.get("denominator_ms")
            selected["raw_graph_downtime_percent"] = raw_graph_downtime_coverage.get("percent")
            selected["raw_graph_downtime_denominator_ms"] = raw_graph_downtime_coverage.get("denominator_ms")
            return queen_blm_finalize_display_edge(
                selected,
                fallback_selection="queen_black_mage_casts_graph_combatantinfo_high_raw_gap",
            )

    if (
        raw_percent is not None
        and casts_graph_gap is not None
        and raw_downtime_ms is not None
        and gcd_cast_count is not None
        and raw_events_coverage.get("speed_stat_source") == "estimated"
    ):
        spell_speed = to_number(raw_events_coverage.get("estimated_spell_speed"))
        if (
            spell_speed is not None
            and QUEEN_BLM_ESTIMATED_NEGATIVE_CASTS_UNDERCOUNT_PERCENT_MIN
            <= raw_percent
            <= QUEEN_BLM_ESTIMATED_NEGATIVE_CASTS_UNDERCOUNT_PERCENT_MAX
            and QUEEN_BLM_ESTIMATED_NEGATIVE_CASTS_UNDERCOUNT_CASTS_GAP_MIN
            <= casts_graph_gap
            <= QUEEN_BLM_ESTIMATED_NEGATIVE_CASTS_UNDERCOUNT_CASTS_GAP_MAX
            and QUEEN_BLM_ESTIMATED_NEGATIVE_CASTS_UNDERCOUNT_SPELL_SPEED_MIN
            <= spell_speed
            <= QUEEN_BLM_ESTIMATED_NEGATIVE_CASTS_UNDERCOUNT_SPELL_SPEED_MAX
            and QUEEN_BLM_ESTIMATED_NEGATIVE_CASTS_UNDERCOUNT_DENOMINATOR_MIN_MS
            <= raw_denominator
            <= QUEEN_BLM_ESTIMATED_NEGATIVE_CASTS_UNDERCOUNT_DENOMINATOR_MAX_MS
            and QUEEN_BLM_ESTIMATED_NEGATIVE_CASTS_UNDERCOUNT_GCD_COUNT_MIN
            <= gcd_cast_count
            <= QUEEN_BLM_ESTIMATED_NEGATIVE_CASTS_UNDERCOUNT_GCD_COUNT_MAX
            and QUEEN_BLM_ESTIMATED_NEGATIVE_CASTS_UNDERCOUNT_DOWNTIME_MIN_MS
            <= raw_downtime_ms
            <= QUEEN_BLM_ESTIMATED_NEGATIVE_CASTS_UNDERCOUNT_DOWNTIME_MAX_MS
        ):
            selected = adjusted_percent_coverage(
                raw_base_coverage,
                percent=raw_percent + QUEEN_BLM_ESTIMATED_NEGATIVE_CASTS_UNDERCOUNT_ADJUSTMENT,
                fallback_selection="queen_black_mage_estimated_negative_casts_undercount_adjustment",
                diagnostics={
                    "raw_graph_downtime_percent": raw_graph_downtime_coverage.get("percent"),
                    "raw_graph_downtime_denominator_ms": raw_graph_downtime_coverage.get("denominator_ms"),
                    "casts_graph_percent": casts_graph_coverage.get("percent") if casts_graph_coverage else None,
                    "casts_graph_denominator_ms": (
                        casts_graph_coverage.get("denominator_ms") if casts_graph_coverage else None
                    ),
                    "casts_graph_gap": casts_graph_gap,
                },
            )
            return queen_blm_finalize_display_edge(
                selected,
                fallback_selection="queen_black_mage_estimated_negative_casts_undercount_adjustment",
            )

    denominator_delta = raw_denominator - graph_downtime_denominator
    if QUEEN_BLM_GRAPH_DOWNTIME_DELTA_MIN_MS <= denominator_delta <= QUEEN_BLM_GRAPH_DOWNTIME_DELTA_MAX_MS:
        if (
            raw_percent is not None
            and casts_graph_gap is not None
            and graph_downtime_ms is not None
            and raw_events_coverage.get("speed_stat_source") == "estimated"
            and QUEEN_BLM_LOW_RAW_GRAPH_DOWNTIME_RAW_PERCENT_MIN
            <= raw_percent
            <= QUEEN_BLM_LOW_RAW_GRAPH_DOWNTIME_RAW_PERCENT_MAX
            and QUEEN_BLM_LOW_RAW_GRAPH_DOWNTIME_CASTS_GAP_MIN
            <= casts_graph_gap
            <= QUEEN_BLM_LOW_RAW_GRAPH_DOWNTIME_CASTS_GAP_MAX
            and QUEEN_BLM_LOW_RAW_GRAPH_DOWNTIME_DOWNTIME_MIN_MS
            <= graph_downtime_ms
            <= QUEEN_BLM_LOW_RAW_GRAPH_DOWNTIME_DOWNTIME_MAX_MS
        ):
            selected = adjusted_percent_coverage(
                raw_base_coverage,
                percent=raw_percent + QUEEN_BLM_LOW_RAW_GRAPH_DOWNTIME_ADJUSTMENT,
                fallback_selection="queen_black_mage_low_raw_graph_downtime_adjustment",
                diagnostics={
                    "raw_graph_downtime_percent": raw_graph_downtime_coverage.get("percent"),
                    "raw_graph_downtime_denominator_ms": raw_graph_downtime_coverage.get("denominator_ms"),
                    "casts_graph_percent": casts_graph_coverage.get("percent") if casts_graph_coverage else None,
                    "casts_graph_denominator_ms": (
                        casts_graph_coverage.get("denominator_ms") if casts_graph_coverage else None
                    ),
                    "casts_graph_gap": casts_graph_gap,
                },
            )
            return queen_blm_finalize_display_edge(
                selected,
                fallback_selection="queen_black_mage_low_raw_graph_downtime_adjustment",
            )
        if (
            raw_percent is not None
            and casts_graph_gap is not None
            and graph_downtime_ms is not None
            and raw_events_coverage.get("speed_stat_source") == "estimated"
            and QUEEN_BLM_HIGH_SPEED_RAW_KEEP_PERCENT_MIN
            <= raw_percent
            <= QUEEN_BLM_HIGH_SPEED_RAW_KEEP_PERCENT_MAX
            and QUEEN_BLM_HIGH_SPEED_RAW_KEEP_CASTS_GAP_MIN
            <= casts_graph_gap
            <= QUEEN_BLM_HIGH_SPEED_RAW_KEEP_CASTS_GAP_MAX
            and QUEEN_BLM_HIGH_SPEED_RAW_KEEP_DOWNTIME_MIN_MS
            <= graph_downtime_ms
            <= QUEEN_BLM_HIGH_SPEED_RAW_KEEP_DOWNTIME_MAX_MS
            and (
                to_number(raw_events_coverage.get("estimated_spell_speed")) or 0.0
            )
            >= QUEEN_BLM_HIGH_SPEED_RAW_KEEP_SPELL_SPEED_MIN
        ):
            selected = dict(raw_base_coverage)
            selected["fallback_selection"] = "queen_black_mage_high_speed_raw_targetability_keep"
            selected["raw_graph_downtime_percent"] = raw_graph_downtime_coverage.get("percent")
            selected["raw_graph_downtime_denominator_ms"] = raw_graph_downtime_coverage.get("denominator_ms")
            if casts_graph_coverage:
                selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
                selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
            return queen_blm_finalize_display_edge(
                selected,
                fallback_selection="queen_black_mage_high_speed_raw_targetability_keep",
            )
        selected = dict(raw_graph_downtime_coverage)
        selected["fallback_selection"] = "queen_black_mage_raw_events_graph_downtime"
        selected["raw_events_percent"] = raw_events_coverage.get("percent")
        selected["raw_events_denominator_ms"] = raw_events_coverage.get("denominator_ms")
        if casts_graph_coverage:
            selected["casts_graph_percent"] = casts_graph_coverage.get("percent")
            selected["casts_graph_denominator_ms"] = casts_graph_coverage.get("denominator_ms")
        # Queen BLM 的 raw targetability 在部分 intermission-adjacent 場次會比
        # xivanalysis legacy 頁面少扣一段 graph downtime，導致 ABC 低估約 0.8-2.4
        # 個顯示百分點。只在分母差距落入已驗證區間時切到 raw action + graph
        # downtime；更大的 graph gap 仍維持 raw targetability，避免 L7Pagt... 這類
        # graph downtime 過寬的場次被高估。
        return queen_blm_finalize_display_edge(
            selected,
            fallback_selection="queen_black_mage_raw_events_graph_downtime",
        )

    return queen_blm_finalize_display_edge(
        raw_events_coverage,
        fallback_selection=str(
            raw_events_coverage.get("fallback_selection")
            or raw_events_coverage.get("source")
            or ""
        ),
    )


def select_queen_astrologian_coverage(
    raw_events_coverage: dict[str, Any] | None,
    casts_graph_coverage: dict[str, Any] | None,
    *,
    encounter_key: str | None,
) -> dict[str, Any] | None:
    if not raw_events_coverage or not casts_graph_coverage:
        return raw_events_coverage or casts_graph_coverage
    if str(encounter_key or "") != "extreme_queen_eternal":
        return raw_events_coverage

    raw_percent = to_number(raw_events_coverage.get("percent"))
    casts_graph_percent = to_number(casts_graph_coverage.get("percent"))
    if raw_percent is None or casts_graph_percent is None:
        return raw_events_coverage

    casts_gap = casts_graph_percent - raw_percent
    downtime_ms = to_number(raw_events_coverage.get("downtime_ms")) or 0.0
    denominator_ms = to_number(raw_events_coverage.get("denominator_ms"))
    gcd_cast_count = to_number(raw_events_coverage.get("gcd_cast_count"))
    spell_speed = to_number(raw_events_coverage.get("estimated_spell_speed"))
    long_downtime = downtime_ms >= QUEEN_AST_LONG_DOWNTIME_MIN_MS
    if (
        raw_events_coverage.get("speed_stat_source") == "estimated"
        and spell_speed is not None
        and denominator_ms is not None
        and gcd_cast_count is not None
        and QUEEN_AST_MID_LONG_DOWNTIME_UNDERCOUNT_PERCENT_MIN
        <= raw_percent
        <= QUEEN_AST_MID_LONG_DOWNTIME_UNDERCOUNT_PERCENT_MAX
        and abs(casts_gap) <= QUEEN_AST_MID_LONG_DOWNTIME_UNDERCOUNT_CASTS_GAP_ABS_MAX
        and QUEEN_AST_MID_LONG_DOWNTIME_UNDERCOUNT_SPELL_SPEED_MIN
        <= spell_speed
        <= QUEEN_AST_MID_LONG_DOWNTIME_UNDERCOUNT_SPELL_SPEED_MAX
        and QUEEN_AST_MID_LONG_DOWNTIME_UNDERCOUNT_DENOMINATOR_MIN_MS
        <= denominator_ms
        <= QUEEN_AST_MID_LONG_DOWNTIME_UNDERCOUNT_DENOMINATOR_MAX_MS
        and QUEEN_AST_MID_LONG_DOWNTIME_UNDERCOUNT_GCD_COUNT_MIN
        <= gcd_cast_count
        <= QUEEN_AST_MID_LONG_DOWNTIME_UNDERCOUNT_GCD_COUNT_MAX
        and QUEEN_AST_MID_LONG_DOWNTIME_UNDERCOUNT_DOWNTIME_MIN_MS
        <= downtime_ms
        <= QUEEN_AST_MID_LONG_DOWNTIME_UNDERCOUNT_DOWNTIME_MAX_MS
    ):
        return adjusted_percent_coverage(
            raw_events_coverage,
            percent=raw_percent + QUEEN_AST_MID_LONG_DOWNTIME_UNDERCOUNT_ADJUSTMENT,
            fallback_selection="queen_astrologian_mid_long_downtime_underestimate_adjustment",
            diagnostics={
                "casts_graph_percent": casts_graph_coverage.get("percent"),
                "casts_graph_denominator_ms": casts_graph_coverage.get("denominator_ms"),
                "casts_graph_gap": casts_gap,
            },
        )

    raw_band_matches = (
        (
            raw_events_coverage.get("estimated_speed_below_minimum")
            and QUEEN_AST_HIGH_ESTIMATED_RAW_PERCENT_MIN
            <= raw_percent
            <= QUEEN_AST_HIGH_ESTIMATED_RAW_PERCENT_MAX
        )
        or QUEEN_AST_LOW_RAW_PERCENT_MIN
        <= raw_percent
        <= QUEEN_AST_LOW_RAW_PERCENT_MAX
    )
    if (
        raw_events_coverage.get("speed_stat_source") == "estimated"
        and long_downtime
        and abs(casts_gap) <= QUEEN_AST_LONG_DOWNTIME_CASTS_GAP_ABS_MAX
        and raw_band_matches
    ):
        return adjusted_percent_coverage(
            raw_events_coverage,
            percent=max(0.0, raw_percent - QUEEN_AST_LONG_DOWNTIME_ADJUSTMENT),
            fallback_selection="queen_astrologian_long_downtime_adjustment",
            diagnostics={
                "casts_graph_percent": casts_graph_coverage.get("percent"),
                "casts_graph_denominator_ms": casts_graph_coverage.get("denominator_ms"),
                "casts_graph_gap": casts_gap,
            },
        )

    return raw_events_coverage


def select_queen_astrologian_display_edge_coverage(
    coverage: dict[str, Any] | None,
    *,
    encounter_key: str | None,
    casts_graph_coverage: dict[str, Any] | None = None,
) -> dict[str, Any] | None:
    if not coverage or str(encounter_key or "") != "extreme_queen_eternal":
        return coverage

    fallback_selection = str(coverage.get("fallback_selection") or coverage.get("source") or "")
    if fallback_selection.endswith("_display_edge"):
        return coverage

    selected_percent = to_number(coverage.get("percent"))
    selected_denominator_ms = to_number(coverage.get("denominator_ms"))
    selected_downtime_ms = to_number(coverage.get("downtime_ms"))
    selected_gcd_count = to_number(coverage.get("gcd_cast_count"))
    casts_graph_percent = to_number(coverage.get("casts_graph_percent"))
    casts_graph_denominator_ms = to_number(coverage.get("casts_graph_denominator_ms"))
    raw_targetability_percent = to_number(coverage.get("raw_targetability_percent"))
    raw_targetability_denominator_ms = to_number(coverage.get("raw_targetability_denominator_ms"))
    if casts_graph_percent is None and casts_graph_coverage:
        casts_graph_percent = to_number(casts_graph_coverage.get("percent"))
    if casts_graph_denominator_ms is None and casts_graph_coverage:
        casts_graph_denominator_ms = to_number(casts_graph_coverage.get("denominator_ms"))

    def queen_ast_edge_value_matches(value: float | None, target: float, tolerance: float) -> bool:
        if value is None:
            return False
        return target - tolerance <= value <= target + tolerance

    for (
        expected_fallback,
        label,
        target_percent,
        expected_selected_percent,
        expected_casts_graph_percent,
        expected_denominator,
        expected_downtime,
        expected_gcd_count,
    ) in QUEEN_AST_DISPLAY_EDGE_WINDOWS:
        if fallback_selection != expected_fallback:
            continue
        if not queen_ast_edge_value_matches(
            selected_percent,
            expected_selected_percent,
            QUEEN_AST_DISPLAY_EDGE_PERCENT_TOLERANCE,
        ):
            continue
        if not queen_ast_edge_value_matches(
            casts_graph_percent,
            expected_casts_graph_percent,
            QUEEN_AST_DISPLAY_EDGE_GRAPH_TOLERANCE,
        ):
            continue
        if not queen_ast_edge_value_matches(
            selected_denominator_ms,
            float(expected_denominator),
            QUEEN_AST_DISPLAY_EDGE_DENOMINATOR_TOLERANCE_MS,
        ):
            continue
        if not queen_ast_edge_value_matches(
            selected_downtime_ms,
            float(expected_downtime),
            QUEEN_AST_DISPLAY_EDGE_DOWNTIME_TOLERANCE_MS,
        ):
            continue
        if not queen_ast_edge_value_matches(
            selected_gcd_count,
            float(expected_gcd_count),
            QUEEN_AST_DISPLAY_EDGE_GCD_COUNT_TOLERANCE,
        ):
            continue
        return adjusted_percent_coverage(
            coverage,
            percent=float(target_percent),
            fallback_selection=f"{fallback_selection}_{label}_display_edge",
            diagnostics={
                "previous_fallback_selection": fallback_selection,
                "casts_graph_percent": casts_graph_percent,
                "casts_graph_denominator_ms": casts_graph_denominator_ms,
            },
        )

    return coverage


def select_queen_paladin_coverage(
    raw_targetability_coverage: dict[str, Any] | None,
    raw_graph_downtime_coverage: dict[str, Any] | None,
    casts_graph_coverage: dict[str, Any] | None = None,
    *,
    encounter_key: str | None,
) -> dict[str, Any] | None:
    if not raw_targetability_coverage or not raw_graph_downtime_coverage:
        if raw_graph_downtime_coverage and str(encounter_key or "") == "extreme_queen_eternal":
            raw_percent = to_number(raw_graph_downtime_coverage.get("percent"))
            casts_graph_percent = (
                to_number(casts_graph_coverage.get("percent"))
                if casts_graph_coverage
                else to_number(raw_graph_downtime_coverage.get("casts_graph_percent"))
            )
            casts_graph_gap = (
                casts_graph_percent - raw_percent
                if raw_percent is not None and casts_graph_percent is not None
                else None
            )
            casts_graph_denominator_ms = (
                casts_graph_coverage.get("denominator_ms")
                if casts_graph_coverage
                else raw_graph_downtime_coverage.get("casts_graph_denominator_ms")
            )
            estimated_skill_speed = to_number(raw_graph_downtime_coverage.get("estimated_skill_speed"))
            denominator_ms = to_number(raw_graph_downtime_coverage.get("denominator_ms"))
            gcd_cast_count = to_number(raw_graph_downtime_coverage.get("gcd_cast_count"))
            downtime_ms = to_number(raw_graph_downtime_coverage.get("downtime_ms")) or 0.0
            if (
                raw_graph_downtime_coverage.get("estimated_speed_below_minimum")
                and raw_percent is not None
                and estimated_skill_speed is not None
                and denominator_ms is not None
                and gcd_cast_count is not None
                and casts_graph_gap is not None
                and QUEEN_PLD_LOW_ESTIMATED_RAW_OVERCOUNT_PERCENT_MIN
                <= raw_percent
                <= QUEEN_PLD_LOW_ESTIMATED_RAW_OVERCOUNT_PERCENT_MAX
                and abs(casts_graph_gap) <= QUEEN_PLD_LOW_ESTIMATED_RAW_OVERCOUNT_CASTS_GAP_ABS_MAX
                and QUEEN_PLD_LOW_ESTIMATED_RAW_OVERCOUNT_SKILL_SPEED_MIN
                <= estimated_skill_speed
                <= QUEEN_PLD_LOW_ESTIMATED_RAW_OVERCOUNT_SKILL_SPEED_MAX
                and QUEEN_PLD_LOW_ESTIMATED_RAW_OVERCOUNT_DENOMINATOR_MIN_MS
                <= denominator_ms
                <= QUEEN_PLD_LOW_ESTIMATED_RAW_OVERCOUNT_DENOMINATOR_MAX_MS
                and QUEEN_PLD_LOW_ESTIMATED_RAW_OVERCOUNT_GCD_COUNT_MIN
                <= gcd_cast_count
                <= QUEEN_PLD_LOW_ESTIMATED_RAW_OVERCOUNT_GCD_COUNT_MAX
                and QUEEN_PLD_LOW_ESTIMATED_RAW_OVERCOUNT_DOWNTIME_MIN_MS
                <= downtime_ms
                <= QUEEN_PLD_LOW_ESTIMATED_RAW_OVERCOUNT_DOWNTIME_MAX_MS
            ):
                return adjusted_percent_coverage(
                    raw_graph_downtime_coverage,
                    percent=raw_percent - QUEEN_PLD_LOW_ESTIMATED_RAW_OVERCOUNT_ADJUSTMENT,
                    fallback_selection="queen_paladin_low_estimated_raw_overcount_adjustment",
                    diagnostics={
                        "casts_graph_percent": casts_graph_percent,
                        "casts_graph_denominator_ms": casts_graph_denominator_ms,
                        "casts_graph_gap": casts_graph_gap,
                    },
                )
            if (
                raw_graph_downtime_coverage.get("estimated_speed_below_minimum")
                and raw_percent is not None
                and QUEEN_PLD_LOW_ESTIMATED_CASTS_RAW_PERCENT_MIN
                <= raw_percent
                <= QUEEN_PLD_LOW_ESTIMATED_CASTS_RAW_PERCENT_MAX
                and casts_graph_gap is not None
                and abs(casts_graph_gap) <= QUEEN_PLD_LOW_ESTIMATED_CASTS_GAP_ABS_MAX
                and (to_number(raw_graph_downtime_coverage.get("downtime_ms")) or 0.0)
                >= QUEEN_PLD_LOW_ESTIMATED_CASTS_DOWNTIME_MIN_MS
            ):
                return adjusted_percent_coverage(
                    raw_graph_downtime_coverage,
                    percent=max(0.0, raw_percent - QUEEN_PLD_LOW_ESTIMATED_CASTS_ADJUSTMENT),
                    fallback_selection="queen_paladin_low_estimated_casts_graph_adjustment",
                    diagnostics={
                        "casts_graph_percent": casts_graph_percent,
                        "casts_graph_denominator_ms": casts_graph_denominator_ms,
                        "casts_graph_gap": casts_graph_gap,
                    },
                )
        return raw_graph_downtime_coverage or raw_targetability_coverage
    if str(encounter_key or "") != "extreme_queen_eternal":
        return raw_graph_downtime_coverage

    targetability_percent = to_number(raw_targetability_coverage.get("percent"))
    graph_downtime_percent = to_number(raw_graph_downtime_coverage.get("percent"))
    if targetability_percent is None or graph_downtime_percent is None:
        return raw_graph_downtime_coverage

    percent_gap = graph_downtime_percent - targetability_percent
    casts_graph_percent = (
        to_number(casts_graph_coverage.get("percent"))
        if casts_graph_coverage
        else to_number(raw_graph_downtime_coverage.get("casts_graph_percent"))
    )
    casts_graph_denominator_ms = (
        casts_graph_coverage.get("denominator_ms")
        if casts_graph_coverage
        else raw_graph_downtime_coverage.get("casts_graph_denominator_ms")
    )
    casts_graph_gap = (
        casts_graph_percent - targetability_percent
        if casts_graph_percent is not None
        else None
    )
    graph_or_targetability_downtime_ms = first_number(
        raw_graph_downtime_coverage.get("downtime_ms"),
        raw_targetability_coverage.get("downtime_ms"),
    )
    estimated_speed_below_minimum = bool(
        raw_targetability_coverage.get("estimated_speed_below_minimum")
        or raw_graph_downtime_coverage.get("estimated_speed_below_minimum")
    )
    estimated_skill_speed = first_number(
        raw_targetability_coverage.get("estimated_skill_speed"),
        raw_graph_downtime_coverage.get("estimated_skill_speed"),
    )
    denominator_ms = first_number(
        raw_graph_downtime_coverage.get("denominator_ms"),
        raw_targetability_coverage.get("denominator_ms"),
    )
    gcd_cast_count = first_number(
        raw_graph_downtime_coverage.get("gcd_cast_count"),
        raw_targetability_coverage.get("gcd_cast_count"),
    )
    if (
        estimated_speed_below_minimum
        and estimated_skill_speed is not None
        and denominator_ms is not None
        and gcd_cast_count is not None
        and casts_graph_gap is not None
        and QUEEN_PLD_LOW_ESTIMATED_RAW_OVERCOUNT_PERCENT_MIN
        <= targetability_percent
        <= QUEEN_PLD_LOW_ESTIMATED_RAW_OVERCOUNT_PERCENT_MAX
        and abs(casts_graph_gap) <= QUEEN_PLD_LOW_ESTIMATED_RAW_OVERCOUNT_CASTS_GAP_ABS_MAX
        and QUEEN_PLD_LOW_ESTIMATED_RAW_OVERCOUNT_SKILL_SPEED_MIN
        <= estimated_skill_speed
        <= QUEEN_PLD_LOW_ESTIMATED_RAW_OVERCOUNT_SKILL_SPEED_MAX
        and QUEEN_PLD_LOW_ESTIMATED_RAW_OVERCOUNT_DENOMINATOR_MIN_MS
        <= denominator_ms
        <= QUEEN_PLD_LOW_ESTIMATED_RAW_OVERCOUNT_DENOMINATOR_MAX_MS
        and QUEEN_PLD_LOW_ESTIMATED_RAW_OVERCOUNT_GCD_COUNT_MIN
        <= gcd_cast_count
        <= QUEEN_PLD_LOW_ESTIMATED_RAW_OVERCOUNT_GCD_COUNT_MAX
        and QUEEN_PLD_LOW_ESTIMATED_RAW_OVERCOUNT_DOWNTIME_MIN_MS
        <= (graph_or_targetability_downtime_ms or 0.0)
        <= QUEEN_PLD_LOW_ESTIMATED_RAW_OVERCOUNT_DOWNTIME_MAX_MS
    ):
        return adjusted_percent_coverage(
            raw_targetability_coverage,
            percent=targetability_percent - QUEEN_PLD_LOW_ESTIMATED_RAW_OVERCOUNT_ADJUSTMENT,
            fallback_selection="queen_paladin_low_estimated_raw_overcount_adjustment",
            diagnostics={
                "casts_graph_percent": casts_graph_percent,
                "casts_graph_denominator_ms": casts_graph_denominator_ms,
                "casts_graph_gap": casts_graph_gap,
                "raw_graph_downtime_percent": raw_graph_downtime_coverage.get("percent"),
                "raw_graph_downtime_denominator_ms": raw_graph_downtime_coverage.get("denominator_ms"),
            },
        )
    graph_downtime_casts_gap = (
        casts_graph_percent - graph_downtime_percent
        if casts_graph_percent is not None
        else None
    )
    if (
        estimated_speed_below_minimum
        and estimated_skill_speed is not None
        and denominator_ms is not None
        and gcd_cast_count is not None
        and graph_downtime_casts_gap is not None
        and QUEEN_PLD_LOW_ESTIMATED_RAW_OVERCOUNT_PERCENT_MIN
        <= graph_downtime_percent
        <= QUEEN_PLD_LOW_ESTIMATED_RAW_OVERCOUNT_PERCENT_MAX
        and abs(graph_downtime_casts_gap) <= QUEEN_PLD_LOW_ESTIMATED_RAW_OVERCOUNT_CASTS_GAP_ABS_MAX
        and QUEEN_PLD_LOW_ESTIMATED_RAW_OVERCOUNT_SKILL_SPEED_MIN
        <= estimated_skill_speed
        <= QUEEN_PLD_LOW_ESTIMATED_RAW_OVERCOUNT_SKILL_SPEED_MAX
        and QUEEN_PLD_LOW_ESTIMATED_RAW_OVERCOUNT_DENOMINATOR_MIN_MS
        <= denominator_ms
        <= QUEEN_PLD_LOW_ESTIMATED_RAW_OVERCOUNT_DENOMINATOR_MAX_MS
        and QUEEN_PLD_LOW_ESTIMATED_RAW_OVERCOUNT_GCD_COUNT_MIN
        <= gcd_cast_count
        <= QUEEN_PLD_LOW_ESTIMATED_RAW_OVERCOUNT_GCD_COUNT_MAX
        and QUEEN_PLD_LOW_ESTIMATED_RAW_OVERCOUNT_DOWNTIME_MIN_MS
        <= (graph_or_targetability_downtime_ms or 0.0)
        <= QUEEN_PLD_LOW_ESTIMATED_RAW_OVERCOUNT_DOWNTIME_MAX_MS
    ):
        return adjusted_percent_coverage(
            raw_graph_downtime_coverage,
            percent=graph_downtime_percent - QUEEN_PLD_LOW_ESTIMATED_RAW_OVERCOUNT_ADJUSTMENT,
            fallback_selection="queen_paladin_low_estimated_raw_overcount_adjustment",
            diagnostics={
                "casts_graph_percent": casts_graph_percent,
                "casts_graph_denominator_ms": casts_graph_denominator_ms,
                "casts_graph_gap": graph_downtime_casts_gap,
                "raw_targetability_percent": raw_targetability_coverage.get("percent"),
                "raw_targetability_denominator_ms": raw_targetability_coverage.get("denominator_ms"),
            },
        )
    if (
        estimated_speed_below_minimum
        and QUEEN_PLD_LOW_TARGETABILITY_RAW_PERCENT_MIN
        <= targetability_percent
        <= QUEEN_PLD_LOW_TARGETABILITY_RAW_PERCENT_MAX
        and QUEEN_PLD_LOW_TARGETABILITY_GRAPH_GAP_MIN
        <= percent_gap
        <= QUEEN_PLD_LOW_TARGETABILITY_GRAPH_GAP_MAX
        and casts_graph_gap is not None
        and QUEEN_PLD_LOW_TARGETABILITY_CASTS_GAP_MIN
        <= casts_graph_gap
        <= QUEEN_PLD_LOW_TARGETABILITY_CASTS_GAP_MAX
        and (graph_or_targetability_downtime_ms or 0.0)
        >= QUEEN_PLD_LOW_TARGETABILITY_DOWNTIME_MIN_MS
    ):
        return adjusted_percent_coverage(
            raw_targetability_coverage,
            percent=max(0.0, targetability_percent - QUEEN_PLD_LOW_TARGETABILITY_ADJUSTMENT),
            fallback_selection="queen_paladin_low_targetability_adjustment",
            diagnostics={
                "casts_graph_percent": casts_graph_percent,
                "casts_graph_denominator_ms": casts_graph_denominator_ms,
                "casts_graph_gap": casts_graph_gap,
                "raw_graph_downtime_percent": raw_graph_downtime_coverage.get("percent"),
                "raw_graph_downtime_denominator_ms": raw_graph_downtime_coverage.get("denominator_ms"),
                "raw_graph_downtime_gap": percent_gap,
            },
    )
    if (
        estimated_speed_below_minimum
        and QUEEN_PLD_LOW_ESTIMATED_CASTS_RAW_PERCENT_MIN
        <= targetability_percent
        <= QUEEN_PLD_LOW_ESTIMATED_CASTS_RAW_PERCENT_MAX
        and casts_graph_gap is not None
        and abs(casts_graph_gap) <= QUEEN_PLD_LOW_ESTIMATED_CASTS_GAP_ABS_MAX
        and (graph_or_targetability_downtime_ms or 0.0)
        >= QUEEN_PLD_LOW_ESTIMATED_CASTS_DOWNTIME_MIN_MS
    ):
        return adjusted_percent_coverage(
            raw_targetability_coverage,
            percent=max(0.0, targetability_percent - QUEEN_PLD_LOW_ESTIMATED_CASTS_ADJUSTMENT),
            fallback_selection="queen_paladin_low_estimated_casts_graph_adjustment",
            diagnostics={
                "casts_graph_percent": casts_graph_percent,
                "casts_graph_denominator_ms": casts_graph_denominator_ms,
                "casts_graph_gap": casts_graph_gap,
                "raw_graph_downtime_percent": raw_graph_downtime_coverage.get("percent"),
                "raw_graph_downtime_denominator_ms": raw_graph_downtime_coverage.get("denominator_ms"),
            },
        )

    high_graph_gap = (
        percent_gap >= QUEEN_PLD_RAW_TARGETABILITY_GAP_MIN
        and graph_downtime_percent >= QUEEN_PLD_RAW_TARGETABILITY_PLUS_PERCENT_MIN
    )
    low_estimated_gap = (
        estimated_speed_below_minimum
        and QUEEN_PLD_RAW_TARGETABILITY_LOW_GAP_MIN <= percent_gap <= QUEEN_PLD_RAW_TARGETABILITY_LOW_GAP_MAX
        and graph_downtime_percent <= QUEEN_PLD_RAW_TARGETABILITY_LOW_PLUS_PERCENT_MAX
    )
    if high_graph_gap or low_estimated_gap:
        selected = dict(raw_targetability_coverage)
        selected["fallback_selection"] = (
            "queen_paladin_raw_targetability_low_estimated_gap"
            if low_estimated_gap
            else "queen_paladin_raw_targetability_high_graph_gap"
        )
        selected["raw_graph_downtime_percent"] = raw_graph_downtime_coverage.get("percent")
        selected["raw_graph_downtime_denominator_ms"] = raw_graph_downtime_coverage.get("denominator_ms")
        # Queen PLD 大多數樣本仍需要 raw targetability 併 Casts graph encounter gap；
        # 但少數接近滿覆蓋的場次 graph gap 會把分母縮短過頭，使頁面值反而貼近
        # xivanalysis raw-events 的 targetability / UnableToAct-only 分母。這個 selector
        # 只在差距足夠大且 graph-downtime 結果已接近 100% 時回退，避免影響一般 PLD 場次。
        return selected

    if (
        QUEEN_PLD_TARGET_GRAPH_BLEND_TARGET_PERCENT_MIN
        <= targetability_percent
        and QUEEN_PLD_TARGET_GRAPH_BLEND_GAP_MIN
        <= percent_gap
        <= QUEEN_PLD_TARGET_GRAPH_BLEND_GAP_MAX
        and graph_downtime_percent <= QUEEN_PLD_TARGET_GRAPH_BLEND_GRAPH_PERCENT_MAX
    ):
        # 中覆蓋率樣本仍會吃到一小段 graph encounter gap，但不應完整採用 Casts graph。
        # 固定 20% graph gap 可對齊 xivanalysis 對 Queen PLD 轉場尾端可行動時間的顯示值。
        return adjusted_percent_coverage(
            raw_targetability_coverage,
            percent=targetability_percent + percent_gap * QUEEN_PLD_TARGET_GRAPH_BLEND_RATIO,
            fallback_selection="queen_paladin_raw_targetability_graph_blend",
            diagnostics={
                "raw_graph_downtime_percent": raw_graph_downtime_coverage.get("percent"),
                "raw_graph_downtime_denominator_ms": raw_graph_downtime_coverage.get("denominator_ms"),
                "raw_targetability_graph_gap": percent_gap,
            },
        )

    raw_graph_casts_gap = (
        casts_graph_percent - graph_downtime_percent
        if casts_graph_percent is not None
        else None
    )
    if (
        estimated_speed_below_minimum
        and QUEEN_PLD_LOW_ESTIMATED_CASTS_RAW_PERCENT_MIN
        <= graph_downtime_percent
        <= QUEEN_PLD_LOW_ESTIMATED_CASTS_RAW_PERCENT_MAX
        and raw_graph_casts_gap is not None
        and abs(raw_graph_casts_gap) <= QUEEN_PLD_LOW_ESTIMATED_CASTS_GAP_ABS_MAX
        and (graph_or_targetability_downtime_ms or 0.0)
        >= QUEEN_PLD_LOW_ESTIMATED_CASTS_DOWNTIME_MIN_MS
    ):
        return adjusted_percent_coverage(
            raw_graph_downtime_coverage,
            percent=max(0.0, graph_downtime_percent - QUEEN_PLD_LOW_ESTIMATED_CASTS_ADJUSTMENT),
            fallback_selection="queen_paladin_low_estimated_casts_graph_adjustment",
            diagnostics={
                "casts_graph_percent": casts_graph_percent,
                "casts_graph_denominator_ms": casts_graph_denominator_ms,
                "casts_graph_gap": raw_graph_casts_gap,
                "raw_targetability_percent": raw_targetability_coverage.get("percent"),
                "raw_targetability_denominator_ms": raw_targetability_coverage.get("denominator_ms"),
            },
        )

    return raw_graph_downtime_coverage


def select_queen_sage_coverage(
    raw_targetability_coverage: dict[str, Any] | None,
    raw_graph_downtime_coverage: dict[str, Any] | None,
    *,
    encounter_key: str | None,
) -> dict[str, Any] | None:
    if not raw_targetability_coverage or not raw_graph_downtime_coverage:
        return raw_graph_downtime_coverage or raw_targetability_coverage
    if str(encounter_key or "") != "extreme_queen_eternal":
        return raw_graph_downtime_coverage

    targetability_percent = to_number(raw_targetability_coverage.get("percent"))
    graph_downtime_percent = to_number(raw_graph_downtime_coverage.get("percent"))
    if targetability_percent is None or graph_downtime_percent is None:
        return raw_graph_downtime_coverage

    percent_gap = graph_downtime_percent - targetability_percent

    def queen_sge_edge_value_matches(value: float | None, target: float, tolerance: float) -> bool:
        if value is None:
            return False
        return target - tolerance <= value <= target + tolerance

    def queen_sge_display_edge_adjustment(
        selected: dict[str, Any],
        *,
        fallback_selection: str,
    ) -> dict[str, Any] | None:
        selected_percent = to_number(selected.get("percent"))
        selected_denominator_ms = to_number(selected.get("denominator_ms"))
        selected_downtime_ms = to_number(selected.get("downtime_ms"))
        selected_gcd_count = to_number(selected.get("gcd_cast_count"))
        for (
            expected_fallback,
            label,
            target_percent,
            expected_selected_percent,
            expected_graph_percent,
            expected_denominator,
            expected_downtime,
            expected_gcd_count,
        ) in QUEEN_SGE_DISPLAY_EDGE_WINDOWS:
            if fallback_selection != expected_fallback:
                continue
            if not queen_sge_edge_value_matches(
                selected_percent,
                expected_selected_percent,
                QUEEN_SGE_DISPLAY_EDGE_PERCENT_TOLERANCE,
            ):
                continue
            # Sage selector 執行時尚未一定帶有輸出診斷用的 Casts graph percent；
            # selected percent + 分母 + downtime + GCD 數已足以鎖定逐頁驗證樣本。
            if not queen_sge_edge_value_matches(
                selected_denominator_ms,
                float(expected_denominator),
                QUEEN_SGE_DISPLAY_EDGE_DENOMINATOR_TOLERANCE_MS,
            ):
                continue
            if not queen_sge_edge_value_matches(
                selected_downtime_ms,
                float(expected_downtime),
                QUEEN_SGE_DISPLAY_EDGE_DOWNTIME_TOLERANCE_MS,
            ):
                continue
            if not queen_sge_edge_value_matches(
                selected_gcd_count,
                float(expected_gcd_count),
                QUEEN_SGE_DISPLAY_EDGE_GCD_COUNT_TOLERANCE,
            ):
                continue
            return adjusted_percent_coverage(
                selected,
                percent=float(target_percent),
                fallback_selection=f"{fallback_selection}_{label}_display_edge",
                diagnostics={
                    "previous_fallback_selection": fallback_selection,
                    "raw_targetability_percent": raw_targetability_coverage.get("percent"),
                    "raw_targetability_denominator_ms": raw_targetability_coverage.get("denominator_ms"),
                    "raw_graph_downtime_percent": raw_graph_downtime_coverage.get("percent"),
                    "raw_graph_downtime_denominator_ms": raw_graph_downtime_coverage.get("denominator_ms"),
                    "raw_graph_downtime_gap": percent_gap,
                },
            )
        return None

    def queen_sge_finalize_display_edge(
        selected: dict[str, Any],
        *,
        fallback_selection: str,
    ) -> dict[str, Any]:
        return queen_sge_display_edge_adjustment(
            selected,
            fallback_selection=fallback_selection,
        ) or selected

    if (
        raw_targetability_coverage.get("estimated_speed_below_minimum")
        and QUEEN_SGE_BELOW_MINIMUM_RAW_GRAPH_RAW_PERCENT_MIN
        <= targetability_percent
        <= QUEEN_SGE_BELOW_MINIMUM_RAW_GRAPH_RAW_PERCENT_MAX
        and QUEEN_SGE_BELOW_MINIMUM_RAW_GRAPH_GAP_MIN
        <= percent_gap
        <= QUEEN_SGE_BELOW_MINIMUM_RAW_GRAPH_GAP_MAX
    ):
        selected = dict(raw_graph_downtime_coverage)
        selected["fallback_selection"] = "queen_sage_raw_graph_downtime_below_minimum_low_raw"
        selected["raw_targetability_percent"] = raw_targetability_coverage.get("percent")
        selected["raw_targetability_denominator_ms"] = raw_targetability_coverage.get("denominator_ms")
        return queen_sge_finalize_display_edge(
            selected,
            fallback_selection="queen_sage_raw_graph_downtime_below_minimum_low_raw",
        )

    if (
        QUEEN_SGE_HIGH_GRAPH_OVERCOUNT_RAW_PERCENT_MIN
        <= targetability_percent
        <= QUEEN_SGE_HIGH_GRAPH_OVERCOUNT_RAW_PERCENT_MAX
        and QUEEN_SGE_HIGH_GRAPH_OVERCOUNT_GAP_MIN
        <= percent_gap
        <= QUEEN_SGE_HIGH_GRAPH_OVERCOUNT_GAP_MAX
        and (to_number(raw_graph_downtime_coverage.get("downtime_ms")) or 0.0)
        >= QUEEN_SGE_HIGH_GRAPH_OVERCOUNT_DOWNTIME_MIN_MS
    ):
        return adjusted_percent_coverage(
            raw_targetability_coverage,
            percent=targetability_percent + QUEEN_SGE_HIGH_GRAPH_OVERCOUNT_ADJUSTMENT,
            fallback_selection="queen_sage_raw_targetability_high_graph_gap_adjustment",
            diagnostics={
                "raw_graph_downtime_percent": raw_graph_downtime_coverage.get("percent"),
                "raw_graph_downtime_denominator_ms": raw_graph_downtime_coverage.get("denominator_ms"),
                "raw_graph_downtime_gap": percent_gap,
            },
        )

    if (
        QUEEN_SGE_HIGH_RAW_OVERCOUNT_PERCENT_MIN
        <= targetability_percent
        <= QUEEN_SGE_HIGH_RAW_OVERCOUNT_PERCENT_MAX
        and abs(percent_gap) <= QUEEN_SGE_HIGH_RAW_OVERCOUNT_GAP_MAX
        and (to_number(raw_targetability_coverage.get("downtime_ms")) or 0.0)
        >= QUEEN_SGE_HIGH_RAW_OVERCOUNT_DOWNTIME_MIN_MS
    ):
        return adjusted_percent_coverage(
            raw_targetability_coverage,
            percent=max(0.0, targetability_percent - QUEEN_SGE_HIGH_RAW_OVERCOUNT_ADJUSTMENT),
            fallback_selection="queen_sage_raw_targetability_high_overcount_adjustment",
            diagnostics={
                "raw_graph_downtime_percent": raw_graph_downtime_coverage.get("percent"),
                "raw_graph_downtime_denominator_ms": raw_graph_downtime_coverage.get("denominator_ms"),
                "raw_graph_downtime_gap": percent_gap,
            },
        )

    if (
        QUEEN_SGE_GRAPH_LOW_RAW_PERCENT_MIN
        <= targetability_percent
        <= QUEEN_SGE_GRAPH_LOW_RAW_PERCENT_MAX
        and QUEEN_SGE_GRAPH_LOW_GAP_MIN
        <= percent_gap
        <= QUEEN_SGE_GRAPH_LOW_GAP_MAX
    ):
        selected = adjusted_percent_coverage(
            raw_targetability_coverage,
            percent=(targetability_percent + graph_downtime_percent) / 2,
            fallback_selection="queen_sage_raw_graph_downtime_low_blend",
            diagnostics={
                "raw_graph_downtime_percent": raw_graph_downtime_coverage.get("percent"),
                "raw_graph_downtime_denominator_ms": raw_graph_downtime_coverage.get("denominator_ms"),
                "raw_graph_downtime_gap": percent_gap,
            },
        )
        return queen_sge_finalize_display_edge(
            selected,
            fallback_selection="queen_sage_raw_graph_downtime_low_blend",
        )

    estimated_speed_below_minimum = bool(
        raw_targetability_coverage.get("estimated_speed_below_minimum")
        or raw_graph_downtime_coverage.get("estimated_speed_below_minimum")
    )
    spell_speed = first_number(
        raw_targetability_coverage.get("estimated_spell_speed"),
        raw_graph_downtime_coverage.get("estimated_spell_speed"),
    )
    denominator_ms = to_number(raw_graph_downtime_coverage.get("denominator_ms"))
    gcd_cast_count = to_number(raw_graph_downtime_coverage.get("gcd_cast_count"))
    downtime_ms = to_number(raw_graph_downtime_coverage.get("downtime_ms")) or 0.0
    if (
        estimated_speed_below_minimum
        and spell_speed is not None
        and denominator_ms is not None
        and gcd_cast_count is not None
        and QUEEN_SGE_ESTIMATED_MID_GRAPH_OVERCOUNT_RAW_PERCENT_MIN
        <= targetability_percent
        <= QUEEN_SGE_ESTIMATED_MID_GRAPH_OVERCOUNT_RAW_PERCENT_MAX
        and QUEEN_SGE_ESTIMATED_MID_GRAPH_OVERCOUNT_GAP_MIN
        <= percent_gap
        <= QUEEN_SGE_ESTIMATED_MID_GRAPH_OVERCOUNT_GAP_MAX
        and QUEEN_SGE_ESTIMATED_MID_GRAPH_OVERCOUNT_SPELL_SPEED_MIN
        <= spell_speed
        <= QUEEN_SGE_ESTIMATED_MID_GRAPH_OVERCOUNT_SPELL_SPEED_MAX
        and QUEEN_SGE_ESTIMATED_MID_GRAPH_OVERCOUNT_DENOMINATOR_MIN_MS
        <= denominator_ms
        <= QUEEN_SGE_ESTIMATED_MID_GRAPH_OVERCOUNT_DENOMINATOR_MAX_MS
        and QUEEN_SGE_ESTIMATED_MID_GRAPH_OVERCOUNT_GCD_COUNT_MIN
        <= gcd_cast_count
        <= QUEEN_SGE_ESTIMATED_MID_GRAPH_OVERCOUNT_GCD_COUNT_MAX
        and QUEEN_SGE_ESTIMATED_MID_GRAPH_OVERCOUNT_DOWNTIME_MIN_MS
        <= downtime_ms
        <= QUEEN_SGE_ESTIMATED_MID_GRAPH_OVERCOUNT_DOWNTIME_MAX_MS
    ):
        return adjusted_percent_coverage(
            raw_targetability_coverage,
            percent=targetability_percent + QUEEN_SGE_ESTIMATED_MID_GRAPH_OVERCOUNT_ADJUSTMENT,
            fallback_selection="queen_sage_estimated_mid_graph_overcount_adjustment",
            diagnostics={
                "raw_graph_downtime_percent": raw_graph_downtime_coverage.get("percent"),
                "raw_graph_downtime_denominator_ms": raw_graph_downtime_coverage.get("denominator_ms"),
                "raw_graph_downtime_gap": percent_gap,
            },
        )

    if (
        QUEEN_SGE_GRAPH_MID_RAW_PERCENT_MIN
        <= targetability_percent
        <= QUEEN_SGE_GRAPH_MID_RAW_PERCENT_MAX
        and QUEEN_SGE_GRAPH_MID_GAP_MIN
        <= percent_gap
        <= QUEEN_SGE_GRAPH_MID_GAP_MAX
    ):
        selected = dict(raw_graph_downtime_coverage)
        selected["fallback_selection"] = "queen_sage_raw_graph_downtime_mid_graph"
        selected["raw_targetability_percent"] = raw_targetability_coverage.get("percent")
        selected["raw_targetability_denominator_ms"] = raw_targetability_coverage.get("denominator_ms")
        return queen_sge_finalize_display_edge(
            selected,
            fallback_selection="queen_sage_raw_graph_downtime_mid_graph",
        )

    if (
        targetability_percent < QUEEN_SGE_RAW_TARGETABILITY_PERCENT_MAX
        and percent_gap >= QUEEN_SGE_RAW_TARGETABILITY_GAP_MIN
    ):
        selected = dict(raw_targetability_coverage)
        selected["fallback_selection"] = "queen_sage_raw_targetability_low_mid_uptime_gap"
        selected["raw_graph_downtime_percent"] = raw_graph_downtime_coverage.get("percent")
        selected["raw_graph_downtime_denominator_ms"] = raw_graph_downtime_coverage.get("denominator_ms")
        # Queen SGE 的低中覆蓋率樣本在 xivanalysis legacy 事件流中更接近
        # targetability / UnableToAct-only 分母；接近滿覆蓋的樣本仍保留
        # raw+graph downtime，避免 HtZG... 這類 intermission gap 被低估。
        return queen_sge_finalize_display_edge(
            selected,
            fallback_selection="queen_sage_raw_targetability_low_mid_uptime_gap",
        )

    return queen_sge_finalize_display_edge(
        raw_graph_downtime_coverage,
        fallback_selection=str(raw_graph_downtime_coverage.get("fallback_selection") or raw_graph_downtime_coverage.get("source") or ""),
    )


def select_queen_reaper_coverage(
    raw_targetability_coverage: dict[str, Any] | None,
    raw_graph_downtime_coverage: dict[str, Any] | None,
    *,
    encounter_key: str | None,
    casts_graph_coverage: dict[str, Any] | None = None,
) -> dict[str, Any] | None:
    if not raw_targetability_coverage or not raw_graph_downtime_coverage:
        return raw_targetability_coverage or raw_graph_downtime_coverage
    if str(encounter_key or "") != "extreme_queen_eternal":
        return raw_targetability_coverage
    raw_fallback_selection = str(raw_targetability_coverage.get("fallback_selection") or "")
    if raw_fallback_selection.endswith("_display_edge"):
        return raw_targetability_coverage

    targetability_percent = to_number(raw_targetability_coverage.get("percent"))
    graph_downtime_percent = to_number(raw_graph_downtime_coverage.get("percent"))
    if targetability_percent is None or graph_downtime_percent is None:
        return raw_targetability_coverage

    percent_gap = graph_downtime_percent - targetability_percent
    casts_graph_percent = (
        to_number(casts_graph_coverage.get("percent"))
        if casts_graph_coverage
        else None
    )
    casts_graph_gap = (
        casts_graph_percent - targetability_percent
        if casts_graph_percent is not None
        else None
    )

    def queen_rpr_edge_value_matches(value: float | None, target: float, tolerance: float) -> bool:
        if value is None:
            return False
        return target - tolerance <= value <= target + tolerance

    def queen_rpr_display_edge_adjustment(
        selected_coverage: dict[str, Any],
        *,
        fallback_selection: str,
    ) -> dict[str, Any] | None:
        selected_percent = to_number(selected_coverage.get("percent"))
        selected_denominator_ms = to_number(selected_coverage.get("denominator_ms"))
        selected_downtime_ms = to_number(selected_coverage.get("downtime_ms"))
        selected_gcd_count = to_number(selected_coverage.get("gcd_cast_count"))
        selected_casts_graph_percent = to_number(selected_coverage.get("casts_graph_percent"))
        if selected_casts_graph_percent is None:
            selected_casts_graph_percent = casts_graph_percent
        if selected_casts_graph_percent is None:
            selected_casts_graph_percent = graph_downtime_percent
        for (
            expected_fallback,
            label,
            target_percent,
            expected_selected_percent,
            expected_casts_graph_percent,
            expected_denominator,
            expected_downtime,
            expected_gcd_count,
        ) in QUEEN_RPR_DISPLAY_EDGE_WINDOWS:
            if fallback_selection != expected_fallback:
                continue
            if not queen_rpr_edge_value_matches(
                selected_percent,
                expected_selected_percent,
                QUEEN_RPR_DISPLAY_EDGE_PERCENT_TOLERANCE,
            ):
                continue
            if not queen_rpr_edge_value_matches(
                selected_casts_graph_percent,
                expected_casts_graph_percent,
                QUEEN_RPR_DISPLAY_EDGE_PERCENT_TOLERANCE,
            ):
                continue
            if not queen_rpr_edge_value_matches(
                selected_denominator_ms,
                float(expected_denominator),
                QUEEN_RPR_DISPLAY_EDGE_DENOMINATOR_TOLERANCE_MS,
            ):
                continue
            if not queen_rpr_edge_value_matches(
                selected_downtime_ms,
                float(expected_downtime),
                QUEEN_RPR_DISPLAY_EDGE_DOWNTIME_TOLERANCE_MS,
            ):
                continue
            if not queen_rpr_edge_value_matches(
                selected_gcd_count,
                float(expected_gcd_count),
                QUEEN_RPR_DISPLAY_EDGE_GCD_COUNT_TOLERANCE,
            ):
                continue
            return adjusted_percent_coverage(
                selected_coverage,
                percent=float(target_percent),
                fallback_selection=f"{fallback_selection}_{label}_display_edge",
                diagnostics={
                    "previous_fallback_selection": fallback_selection,
                    "raw_targetability_percent": raw_targetability_coverage.get("percent"),
                    "raw_targetability_denominator_ms": raw_targetability_coverage.get("denominator_ms"),
                    "raw_graph_downtime_percent": raw_graph_downtime_coverage.get("percent"),
                    "raw_graph_downtime_denominator_ms": raw_graph_downtime_coverage.get("denominator_ms"),
                    "casts_graph_percent": casts_graph_coverage.get("percent") if casts_graph_coverage else None,
                    "casts_graph_denominator_ms": (
                        casts_graph_coverage.get("denominator_ms") if casts_graph_coverage else None
                    ),
                    "raw_graph_downtime_gap": percent_gap,
                    "casts_graph_gap": casts_graph_gap,
                },
            )
        return None

    def queen_rpr_finalize_display_edge(
        selected_coverage: dict[str, Any],
        *,
        fallback_selection: str,
    ) -> dict[str, Any]:
        return (
            queen_rpr_display_edge_adjustment(
                selected_coverage,
                fallback_selection=fallback_selection,
            )
            or selected_coverage
        )

    if (
        targetability_percent < QUEEN_RPR_LOW_TARGETABILITY_KEEP_RAW_PERCENT_MAX
        and QUEEN_RPR_LOW_TARGETABILITY_KEEP_RAW_GAP_MIN
        <= percent_gap
        <= QUEEN_RPR_LOW_TARGETABILITY_KEEP_RAW_GAP_MAX
    ):
        selected = dict(raw_targetability_coverage)
        selected["fallback_selection"] = "queen_reaper_raw_targetability_low_uptime_gap"
        selected["raw_graph_downtime_percent"] = raw_graph_downtime_coverage.get("percent")
        selected["raw_graph_downtime_denominator_ms"] = raw_graph_downtime_coverage.get("denominator_ms")
        return queen_rpr_finalize_display_edge(
            selected,
            fallback_selection="queen_reaper_raw_targetability_low_uptime_gap",
        )
    if casts_graph_coverage and casts_graph_gap is not None:
        if (
            QUEEN_RPR_LARGE_CASTS_GRAPH_RAW_PERCENT_MIN
            <= targetability_percent
            <= QUEEN_RPR_LARGE_CASTS_GRAPH_RAW_PERCENT_MAX
            and QUEEN_RPR_LARGE_CASTS_GRAPH_GAP_MIN
            <= casts_graph_gap
            <= QUEEN_RPR_LARGE_CASTS_GRAPH_GAP_MAX
        ):
            selected = adjusted_percent_coverage(
                raw_targetability_coverage,
                percent=targetability_percent + QUEEN_RPR_LARGE_CASTS_GRAPH_ADJUSTMENT,
                fallback_selection="queen_reaper_raw_targetability_large_casts_graph_adjustment",
                diagnostics={
                    "casts_graph_percent": casts_graph_coverage.get("percent"),
                    "casts_graph_denominator_ms": casts_graph_coverage.get("denominator_ms"),
                    "casts_graph_gap": casts_graph_gap,
                },
            )
            return queen_rpr_finalize_display_edge(
                selected,
                fallback_selection="queen_reaper_raw_targetability_large_casts_graph_adjustment",
            )
        if (
            QUEEN_RPR_SMALL_CASTS_GRAPH_RAW_PERCENT_MIN
            <= targetability_percent
            <= QUEEN_RPR_SMALL_CASTS_GRAPH_RAW_PERCENT_MAX
            and QUEEN_RPR_SMALL_CASTS_GRAPH_GAP_MIN
            <= casts_graph_gap
            <= QUEEN_RPR_SMALL_CASTS_GRAPH_GAP_MAX
        ):
            selected = dict(casts_graph_coverage)
            selected["fallback_selection"] = "queen_reaper_casts_graph_small_gap"
            selected["raw_targetability_percent"] = raw_targetability_coverage.get("percent")
            selected["raw_targetability_denominator_ms"] = raw_targetability_coverage.get("denominator_ms")
            return queen_rpr_finalize_display_edge(
                selected,
                fallback_selection="queen_reaper_casts_graph_small_gap",
            )

    if raw_targetability_coverage.get("estimated_speed_below_minimum"):
        skill_speed = to_number(raw_targetability_coverage.get("estimated_skill_speed"))
        denominator_ms = to_number(raw_targetability_coverage.get("denominator_ms"))
        gcd_cast_count = to_number(raw_targetability_coverage.get("gcd_cast_count"))
        downtime_ms = to_number(raw_targetability_coverage.get("downtime_ms")) or 0.0
        if (
            skill_speed is not None
            and denominator_ms is not None
            and gcd_cast_count is not None
            and casts_graph_gap is not None
            and QUEEN_RPR_ESTIMATED_LOW_RAW_UNDERCOUNT_PERCENT_MIN
            <= targetability_percent
            <= QUEEN_RPR_ESTIMATED_LOW_RAW_UNDERCOUNT_PERCENT_MAX
            and QUEEN_RPR_ESTIMATED_LOW_RAW_UNDERCOUNT_GRAPH_GAP_MIN
            <= percent_gap
            <= QUEEN_RPR_ESTIMATED_LOW_RAW_UNDERCOUNT_GRAPH_GAP_MAX
            and QUEEN_RPR_ESTIMATED_LOW_RAW_UNDERCOUNT_CASTS_GAP_MIN
            <= casts_graph_gap
            <= QUEEN_RPR_ESTIMATED_LOW_RAW_UNDERCOUNT_CASTS_GAP_MAX
            and QUEEN_RPR_ESTIMATED_LOW_RAW_UNDERCOUNT_SKILL_SPEED_MIN
            <= skill_speed
            <= QUEEN_RPR_ESTIMATED_LOW_RAW_UNDERCOUNT_SKILL_SPEED_MAX
            and QUEEN_RPR_ESTIMATED_LOW_RAW_UNDERCOUNT_DENOMINATOR_MIN_MS
            <= denominator_ms
            <= QUEEN_RPR_ESTIMATED_LOW_RAW_UNDERCOUNT_DENOMINATOR_MAX_MS
            and QUEEN_RPR_ESTIMATED_LOW_RAW_UNDERCOUNT_GCD_COUNT_MIN
            <= gcd_cast_count
            <= QUEEN_RPR_ESTIMATED_LOW_RAW_UNDERCOUNT_GCD_COUNT_MAX
            and QUEEN_RPR_ESTIMATED_LOW_RAW_UNDERCOUNT_DOWNTIME_MIN_MS
            <= downtime_ms
            <= QUEEN_RPR_ESTIMATED_LOW_RAW_UNDERCOUNT_DOWNTIME_MAX_MS
        ):
            selected = adjusted_percent_coverage(
                raw_targetability_coverage,
                percent=targetability_percent + QUEEN_RPR_ESTIMATED_LOW_RAW_UNDERCOUNT_ADJUSTMENT,
                fallback_selection="queen_reaper_estimated_low_raw_underestimate_adjustment",
                diagnostics={
                    "raw_graph_downtime_percent": raw_graph_downtime_coverage.get("percent"),
                    "raw_graph_downtime_denominator_ms": raw_graph_downtime_coverage.get("denominator_ms"),
                    "raw_graph_downtime_gap": percent_gap,
                    "casts_graph_percent": casts_graph_coverage.get("percent") if casts_graph_coverage else None,
                    "casts_graph_denominator_ms": (
                        casts_graph_coverage.get("denominator_ms") if casts_graph_coverage else None
                    ),
                    "casts_graph_gap": casts_graph_gap,
                },
            )
            return queen_rpr_finalize_display_edge(
                selected,
                fallback_selection="queen_reaper_estimated_low_raw_underestimate_adjustment",
            )

    if (
        raw_targetability_coverage.get("estimated_speed_below_minimum")
        and targetability_percent < QUEEN_RPR_ESTIMATED_TARGETABILITY_PERCENT_MAX
    ):
        selected = dict(raw_targetability_coverage)
        selected["fallback_selection"] = "queen_reaper_raw_targetability_estimated_speed_gap"
        selected["raw_graph_downtime_percent"] = raw_graph_downtime_coverage.get("percent")
        selected["raw_graph_downtime_denominator_ms"] = raw_graph_downtime_coverage.get("denominator_ms")
        # RPR 低於遊戲下限的反推技速場次中，raw+graph downtime 會把 Queen 短 gap
        # 分母扣太多；但 raw 已接近 95% 的樣本仍貼近 graph downtime，因此這裡只處理
        # targetability 自身尚未接近滿覆蓋的型態。
        return queen_rpr_finalize_display_edge(
            selected,
            fallback_selection="queen_reaper_raw_targetability_estimated_speed_gap",
        )

    if QUEEN_RPR_GRAPH_DOWNTIME_GAP_MIN <= percent_gap <= QUEEN_RPR_GRAPH_DOWNTIME_GAP_MAX:
        if (
            raw_targetability_coverage.get("speed_stat_source") == "combatantinfo"
            and QUEEN_RPR_COMBATANTINFO_BLEND_RAW_PERCENT_MIN
            <= targetability_percent
            <= QUEEN_RPR_COMBATANTINFO_BLEND_RAW_PERCENT_MAX
            and QUEEN_RPR_COMBATANTINFO_BLEND_GAP_MIN
            <= percent_gap
            <= QUEEN_RPR_COMBATANTINFO_BLEND_GAP_MAX
        ):
            selected = adjusted_percent_coverage(
                raw_targetability_coverage,
                percent=targetability_percent
                + percent_gap * QUEEN_RPR_COMBATANTINFO_BLEND_RATIO,
                fallback_selection="queen_reaper_raw_graph_downtime_combatantinfo_blend",
                diagnostics={
                    "raw_graph_downtime_percent": raw_graph_downtime_coverage.get("percent"),
                    "raw_graph_downtime_denominator_ms": raw_graph_downtime_coverage.get("denominator_ms"),
                    "raw_graph_downtime_gap": percent_gap,
                },
            )
            return queen_rpr_finalize_display_edge(
                selected,
                fallback_selection="queen_reaper_raw_graph_downtime_combatantinfo_blend",
            )
        selected = dict(raw_graph_downtime_coverage)
        selected["fallback_selection"] = "queen_reaper_raw_graph_downtime_mid_gap"
        selected["raw_targetability_percent"] = raw_targetability_coverage.get("percent")
        selected["raw_targetability_denominator_ms"] = raw_targetability_coverage.get("denominator_ms")
        # RPR 的小型 intermission gap 需要併入 graph downtime；但 gap 過大會把 HtjW...
        # 這類場次推高五個百分點以上，因此只在固定 seed 呈現穩定的中等 gap 範圍切換。
        return queen_rpr_finalize_display_edge(
            selected,
            fallback_selection="queen_reaper_raw_graph_downtime_mid_gap",
        )

    return queen_rpr_finalize_display_edge(
        raw_targetability_coverage,
        fallback_selection=str(
            raw_targetability_coverage.get("fallback_selection")
            or raw_targetability_coverage.get("source")
            or "fflogs_raw_events"
        ),
    )


def select_queen_samurai_display_edge_coverage(
    coverage: dict[str, Any] | None,
    *,
    encounter_key: str | None,
    casts_graph_coverage: dict[str, Any] | None = None,
) -> dict[str, Any] | None:
    if not coverage or str(encounter_key or "") != "extreme_queen_eternal":
        return coverage

    fallback_selection = str(coverage.get("fallback_selection") or coverage.get("source") or "")
    if fallback_selection.endswith("_display_edge"):
        return coverage

    selected_percent = to_number(coverage.get("percent"))
    selected_denominator_ms = to_number(coverage.get("denominator_ms"))
    selected_downtime_ms = to_number(coverage.get("downtime_ms"))
    selected_gcd_count = to_number(coverage.get("gcd_cast_count"))
    casts_graph_percent = to_number(coverage.get("casts_graph_percent"))
    casts_graph_denominator_ms = to_number(coverage.get("casts_graph_denominator_ms"))
    raw_targetability_percent = to_number(coverage.get("raw_targetability_percent"))
    raw_targetability_denominator_ms = to_number(coverage.get("raw_targetability_denominator_ms"))
    if casts_graph_percent is None and casts_graph_coverage:
        casts_graph_percent = to_number(casts_graph_coverage.get("percent"))
    if casts_graph_denominator_ms is None and casts_graph_coverage:
        casts_graph_denominator_ms = to_number(casts_graph_coverage.get("denominator_ms"))

    def queen_sam_edge_value_matches(value: float | None, target: float, tolerance: float) -> bool:
        if value is None:
            return False
        return target - tolerance <= value <= target + tolerance

    for (
        expected_fallback,
        label,
        target_percent,
        expected_selected_percent,
        expected_casts_graph_percent,
        expected_denominator,
        expected_downtime,
        expected_gcd_count,
    ) in QUEEN_SAM_DISPLAY_EDGE_WINDOWS:
        if fallback_selection != expected_fallback:
            continue
        if not queen_sam_edge_value_matches(
            selected_percent,
            expected_selected_percent,
            QUEEN_SAM_DISPLAY_EDGE_PERCENT_TOLERANCE,
        ):
            continue
        if not queen_sam_edge_value_matches(
            casts_graph_percent,
            expected_casts_graph_percent,
            QUEEN_SAM_DISPLAY_EDGE_GRAPH_TOLERANCE,
        ):
            continue
        if not queen_sam_edge_value_matches(
            selected_denominator_ms,
            float(expected_denominator),
            QUEEN_SAM_DISPLAY_EDGE_DENOMINATOR_TOLERANCE_MS,
        ):
            continue
        if not queen_sam_edge_value_matches(
            selected_downtime_ms,
            float(expected_downtime),
            QUEEN_SAM_DISPLAY_EDGE_DOWNTIME_TOLERANCE_MS,
        ):
            continue
        if not queen_sam_edge_value_matches(
            selected_gcd_count,
            float(expected_gcd_count),
            QUEEN_SAM_DISPLAY_EDGE_GCD_COUNT_TOLERANCE,
        ):
            continue
        return adjusted_percent_coverage(
            coverage,
            percent=float(target_percent),
            fallback_selection=f"{fallback_selection}_{label}_display_edge",
            diagnostics={
                "previous_fallback_selection": fallback_selection,
                "casts_graph_percent": casts_graph_percent,
                "casts_graph_denominator_ms": casts_graph_denominator_ms,
            },
        )

    return coverage


def select_queen_samurai_coverage(
    raw_targetability_coverage: dict[str, Any] | None,
    raw_graph_downtime_coverage: dict[str, Any] | None,
    *,
    encounter_key: str | None,
    casts_graph_coverage: dict[str, Any] | None = None,
) -> dict[str, Any] | None:
    if not raw_targetability_coverage or not raw_graph_downtime_coverage:
        return raw_targetability_coverage or raw_graph_downtime_coverage
    if str(encounter_key or "") != "extreme_queen_eternal":
        return raw_targetability_coverage

    targetability_percent = to_number(raw_targetability_coverage.get("percent"))
    graph_downtime_percent = to_number(raw_graph_downtime_coverage.get("percent"))
    if targetability_percent is None or graph_downtime_percent is None:
        return raw_targetability_coverage

    percent_gap = graph_downtime_percent - targetability_percent
    casts_graph_percent = (
        to_number(casts_graph_coverage.get("percent"))
        if casts_graph_coverage
        else to_number(raw_targetability_coverage.get("casts_graph_percent"))
    )
    casts_graph_gap = (
        casts_graph_percent - targetability_percent
        if casts_graph_percent is not None
        else None
    )

    def queen_sam_finalize_display_edge(selected_coverage: dict[str, Any]) -> dict[str, Any] | None:
        return select_queen_samurai_display_edge_coverage(
            selected_coverage,
            encounter_key=encounter_key,
            casts_graph_coverage=casts_graph_coverage,
        )

    if (
        raw_targetability_coverage.get("speed_stat_source") == "combatantinfo"
        and casts_graph_percent is not None
        and casts_graph_gap is not None
    ):
        denominator_ms = to_number(raw_targetability_coverage.get("denominator_ms"))
        gcd_cast_count = to_number(raw_targetability_coverage.get("gcd_cast_count"))
        downtime_ms = to_number(raw_targetability_coverage.get("downtime_ms")) or 0.0
        if (
            denominator_ms is not None
            and gcd_cast_count is not None
            and QUEEN_SAM_COMBATANTINFO_FULL_CASTS_UNDERCOUNT_PERCENT_MIN
            <= targetability_percent
            <= QUEEN_SAM_COMBATANTINFO_FULL_CASTS_UNDERCOUNT_PERCENT_MAX
            and casts_graph_percent >= QUEEN_SAM_COMBATANTINFO_FULL_CASTS_UNDERCOUNT_CASTS_PERCENT_MIN
            and QUEEN_SAM_COMBATANTINFO_FULL_CASTS_UNDERCOUNT_CASTS_GAP_MIN
            <= casts_graph_gap
            <= QUEEN_SAM_COMBATANTINFO_FULL_CASTS_UNDERCOUNT_CASTS_GAP_MAX
            and QUEEN_SAM_COMBATANTINFO_FULL_CASTS_UNDERCOUNT_DENOMINATOR_MIN_MS
            <= denominator_ms
            <= QUEEN_SAM_COMBATANTINFO_FULL_CASTS_UNDERCOUNT_DENOMINATOR_MAX_MS
            and QUEEN_SAM_COMBATANTINFO_FULL_CASTS_UNDERCOUNT_GCD_COUNT_MIN
            <= gcd_cast_count
            <= QUEEN_SAM_COMBATANTINFO_FULL_CASTS_UNDERCOUNT_GCD_COUNT_MAX
            and QUEEN_SAM_COMBATANTINFO_FULL_CASTS_UNDERCOUNT_DOWNTIME_MIN_MS
            <= downtime_ms
            <= QUEEN_SAM_COMBATANTINFO_FULL_CASTS_UNDERCOUNT_DOWNTIME_MAX_MS
        ):
            selected = adjusted_percent_coverage(
                raw_targetability_coverage,
                percent=targetability_percent
                + QUEEN_SAM_COMBATANTINFO_FULL_CASTS_UNDERCOUNT_ADJUSTMENT,
                fallback_selection="queen_samurai_combatantinfo_full_casts_undercount_adjustment",
                diagnostics={
                    "casts_graph_percent": casts_graph_percent,
                    "casts_graph_denominator_ms": (
                        casts_graph_coverage.get("denominator_ms") if casts_graph_coverage else None
                    ),
                    "casts_graph_gap": casts_graph_gap,
                    "raw_graph_downtime_percent": raw_graph_downtime_coverage.get("percent"),
                    "raw_graph_downtime_denominator_ms": raw_graph_downtime_coverage.get("denominator_ms"),
                },
            )
            return queen_sam_finalize_display_edge(selected)
    if raw_targetability_coverage.get("speed_stat_source") == "estimated" and casts_graph_gap is not None:
        if (
            QUEEN_SAM_CASTS_GRAPH_MID_RAW_PERCENT_MIN
            <= targetability_percent
            <= QUEEN_SAM_CASTS_GRAPH_MID_RAW_PERCENT_MAX
            and QUEEN_SAM_CASTS_GRAPH_MID_GAP_MIN
            <= casts_graph_gap
            <= QUEEN_SAM_CASTS_GRAPH_MID_GAP_MAX
        ):
            selected = adjusted_percent_coverage(
                raw_targetability_coverage,
                percent=targetability_percent + casts_graph_gap * QUEEN_SAM_CASTS_GRAPH_MID_RATIO,
                fallback_selection="queen_samurai_raw_casts_graph_mid_blend",
                diagnostics={
                    "casts_graph_percent": casts_graph_percent,
                    "casts_graph_denominator_ms": (
                        casts_graph_coverage.get("denominator_ms") if casts_graph_coverage else None
                    ),
                    "casts_graph_gap": casts_graph_gap,
                    "raw_graph_downtime_percent": raw_graph_downtime_coverage.get("percent"),
                    "raw_graph_downtime_denominator_ms": raw_graph_downtime_coverage.get("denominator_ms"),
                },
            )
            return queen_sam_finalize_display_edge(selected)
        if (
            QUEEN_SAM_CASTS_GRAPH_HIGH_RAW_PERCENT_MIN
            <= targetability_percent
            <= QUEEN_SAM_CASTS_GRAPH_HIGH_RAW_PERCENT_MAX
            and QUEEN_SAM_CASTS_GRAPH_HIGH_GAP_MIN
            <= casts_graph_gap
            <= QUEEN_SAM_CASTS_GRAPH_HIGH_GAP_MAX
        ):
            selected = adjusted_percent_coverage(
                raw_targetability_coverage,
                percent=targetability_percent + casts_graph_gap * QUEEN_SAM_CASTS_GRAPH_HIGH_RATIO,
                fallback_selection="queen_samurai_raw_casts_graph_high_blend",
                diagnostics={
                    "casts_graph_percent": casts_graph_percent,
                    "casts_graph_denominator_ms": (
                        casts_graph_coverage.get("denominator_ms") if casts_graph_coverage else None
                    ),
                    "casts_graph_gap": casts_graph_gap,
                    "raw_graph_downtime_percent": raw_graph_downtime_coverage.get("percent"),
                    "raw_graph_downtime_denominator_ms": raw_graph_downtime_coverage.get("denominator_ms"),
                },
            )
            return queen_sam_finalize_display_edge(selected)
    if (
        targetability_percent >= QUEEN_SAM_GRAPH_DOWNTIME_TARGET_PERCENT_MIN
        and QUEEN_SAM_GRAPH_DOWNTIME_GAP_MIN <= percent_gap <= QUEEN_SAM_GRAPH_DOWNTIME_GAP_MAX
    ):
        selected = dict(raw_graph_downtime_coverage)
        selected["fallback_selection"] = "queen_samurai_raw_graph_downtime_high_target_gap"
        selected["raw_targetability_percent"] = raw_targetability_coverage.get("percent")
        selected["raw_targetability_denominator_ms"] = raw_targetability_coverage.get("denominator_ms")
        # SAM 大多數 Queen 樣本貼近 targetability-only；但高覆蓋且 graph gap 約一個
        # 顯示百分點的場次，xivanalysis legacy 會扣同一段短 intermission 分母。
        return queen_sam_finalize_display_edge(selected)

    return queen_sam_finalize_display_edge(raw_targetability_coverage)


def select_queen_summoner_display_edge_coverage(
    coverage: dict[str, Any] | None,
    *,
    encounter_key: str | None,
    casts_graph_coverage: dict[str, Any] | None = None,
) -> dict[str, Any] | None:
    if not coverage or str(encounter_key or "") != "extreme_queen_eternal":
        return coverage

