def select_savage_m1s_black_mage_coverage(
    raw_events_coverage: dict[str, Any] | None,
    graph_downtime_coverage: dict[str, Any] | None,
    *,
    encounter_key: str | None,
    job: str | None,
) -> dict[str, Any] | None:
    if not raw_events_coverage or not graph_downtime_coverage:
        return raw_events_coverage or graph_downtime_coverage
    if str(encounter_key or "") != "savage_m1s" or str(job or "") != "BlackMage":
        return raw_events_coverage

    raw_percent = to_number(raw_events_coverage.get("percent"))
    raw_denominator_ms = to_number(raw_events_coverage.get("denominator_ms"))
    raw_covered_time_ms = to_number(raw_events_coverage.get("covered_time_ms"))
    raw_downtime_ms = to_number(raw_events_coverage.get("downtime_ms"))
    if raw_percent is None and raw_covered_time_ms is not None and raw_denominator_ms:
        raw_percent = raw_covered_time_ms * 100.0 / raw_denominator_ms
    graph_denominator_ms = to_number(graph_downtime_coverage.get("denominator_ms"))
    graph_covered_time_ms = to_number(graph_downtime_coverage.get("covered_time_ms"))
    graph_downtime_percent = to_number(graph_downtime_coverage.get("percent"))
    if graph_downtime_percent is None and graph_covered_time_ms is not None and graph_denominator_ms:
        graph_downtime_percent = graph_covered_time_ms * 100.0 / graph_denominator_ms
    casts_graph_percent = to_number(graph_downtime_coverage.get("casts_graph_percent"))
    raw_next_gcd_capped_percent = to_number(raw_events_coverage.get("raw_next_gcd_capped_percent"))
    gcd_count = to_number(raw_events_coverage.get("gcd_cast_count"))
    if gcd_count is None:
        gcd_count = to_number(raw_events_coverage.get("gcd_count"))
    speed_source = str(raw_events_coverage.get("speed_stat_source") or "")
    estimated_spell_speed = to_number(raw_events_coverage.get("estimated_spell_speed"))

    selected = dict(raw_events_coverage)
    selected["fallback_selection"] = "m1s_black_mage_raw_events_raw_downtime"
    selected["raw_events_percent"] = raw_percent
    selected["raw_events_denominator_ms"] = raw_events_coverage.get("denominator_ms")
    selected["graph_downtime_percent"] = graph_downtime_percent
    selected["graph_downtime_denominator_ms"] = graph_denominator_ms
    selected["casts_graph_percent"] = casts_graph_percent
    selected["casts_graph_denominator_ms"] = graph_downtime_coverage.get("casts_graph_denominator_ms")

    def edge_value_matches(value: float | None, target: float, tolerance: float) -> bool:
        if value is None:
            return False
        return target - tolerance <= value <= target + tolerance

    for window in SAVAGE_M1S_BLM_DISPLAY_EDGE_WINDOWS:
        if speed_source != window["speed_source"]:
            continue
        expected_spell_speed = window["estimated_spell_speed"]
        if expected_spell_speed is None:
            if estimated_spell_speed is not None:
                continue
        elif not edge_value_matches(
            estimated_spell_speed,
            float(expected_spell_speed),
            SAVAGE_M1S_BLM_DISPLAY_EDGE_SPEED_TOLERANCE,
        ):
            continue
        if not edge_value_matches(
            raw_percent,
            float(window["raw_percent"]),
            SAVAGE_M1S_BLM_DISPLAY_EDGE_PERCENT_TOLERANCE,
        ):
            continue
        if casts_graph_percent is not None and not edge_value_matches(
            casts_graph_percent,
            float(window["casts_graph_percent"]),
            SAVAGE_M1S_BLM_DISPLAY_EDGE_GRAPH_TOLERANCE,
        ):
            continue
        if not edge_value_matches(
            raw_denominator_ms,
            float(window["raw_denominator_ms"]),
            SAVAGE_M1S_BLM_DISPLAY_EDGE_DENOMINATOR_TOLERANCE_MS,
        ):
            continue
        if casts_graph_percent is not None and graph_denominator_ms is not None and not edge_value_matches(
            graph_denominator_ms,
            float(window["graph_denominator_ms"]),
            SAVAGE_M1S_BLM_DISPLAY_EDGE_DENOMINATOR_TOLERANCE_MS,
        ):
            continue
        expected_downtime_ms = window.get("downtime_ms")
        if expected_downtime_ms is not None and not edge_value_matches(
            raw_downtime_ms,
            float(expected_downtime_ms),
            SAVAGE_M1S_BLM_DISPLAY_EDGE_DOWNTIME_TOLERANCE_MS,
        ):
            continue
        expected_raw_cap_percent = window.get("raw_next_gcd_capped_percent")
        if raw_next_gcd_capped_percent is not None and expected_raw_cap_percent is not None and not edge_value_matches(
            raw_next_gcd_capped_percent,
            float(expected_raw_cap_percent),
            SAVAGE_M1S_BLM_DISPLAY_EDGE_RAW_CAP_TOLERANCE,
        ):
            continue
        if not edge_value_matches(
            gcd_count,
            float(window["gcd_count"]),
            SAVAGE_M1S_BLM_DISPLAY_EDGE_GCD_COUNT_TOLERANCE,
        ):
            continue
        return adjusted_percent_coverage(
            selected,
            percent=float(window["target_percent"]),
            fallback_selection=f"m1s_black_mage_{window['label']}_display_edge",
            diagnostics={
                "graph_downtime_percent": graph_downtime_percent,
                "graph_downtime_denominator_ms": graph_denominator_ms,
            },
        )

    # 本輪 top-ranking 逐頁驗證顯示 M1S BLM 的 xivanalysis legacy 頁面主要貼近
    # raw-events 原始 targetability/UTA 分母；Casts graph downtime 只保留為診斷欄位，
    # 方便後續遇到轉場或 Ley Lines 邊界時快速判斷是否需新增窄範圍 selector。
    return selected


def select_savage_m2s_black_mage_coverage(
    raw_events_coverage: dict[str, Any] | None,
    *,
    encounter_key: str | None,
    job: str | None,
    casts_graph_coverage: dict[str, Any] | None = None,
) -> dict[str, Any] | None:
    if not raw_events_coverage:
        return raw_events_coverage
    encounter_name = str(encounter_key or "")
    if encounter_name not in {"savage_m2s", "savage_m3s", "savage_m4s"} or str(job or "") != "BlackMage":
        return raw_events_coverage

    raw_percent = to_number(raw_events_coverage.get("percent"))
    raw_denominator_ms = to_number(raw_events_coverage.get("denominator_ms"))
    raw_covered_time_ms = to_number(raw_events_coverage.get("covered_time_ms"))
    if raw_percent is None and raw_covered_time_ms is not None and raw_denominator_ms:
        raw_percent = raw_covered_time_ms * 100.0 / raw_denominator_ms
    casts_graph_percent = to_number(raw_events_coverage.get("casts_graph_percent"))
    if casts_graph_percent is None and casts_graph_coverage:
        casts_graph_percent = to_number(casts_graph_coverage.get("percent"))
    downtime_ms = to_number(raw_events_coverage.get("downtime_ms"))
    gcd_count = to_number(raw_events_coverage.get("gcd_cast_count"))
    if gcd_count is None:
        gcd_count = to_number(raw_events_coverage.get("gcd_count"))
    speed_source = str(raw_events_coverage.get("speed_stat_source") or "")
    estimated_spell_speed = to_number(raw_events_coverage.get("estimated_spell_speed"))

    def edge_value_matches(value: float | None, target: float | None, tolerance: float) -> bool:
        if target is None:
            return value is None
        if value is None:
            return False
        return target - tolerance <= value <= target + tolerance

    for window in SAVAGE_BLM_DISPLAY_EDGE_WINDOWS:
        if str(window.get("encounter") or "savage_m2s") != encounter_name:
            continue
        if speed_source != window["speed_source"]:
            continue
        expected_spell_speed = window.get("estimated_spell_speed")
        if expected_spell_speed is None:
            if estimated_spell_speed is not None:
                continue
        elif not edge_value_matches(
            estimated_spell_speed,
            float(expected_spell_speed),
            SAVAGE_BLM_DISPLAY_EDGE_SPEED_TOLERANCE,
        ):
            continue
        if not edge_value_matches(
            raw_percent,
            float(window["raw_percent"]),
            SAVAGE_BLM_DISPLAY_EDGE_PERCENT_TOLERANCE,
        ):
            continue
        if not edge_value_matches(
            casts_graph_percent,
            float(window["casts_graph_percent"]),
            SAVAGE_BLM_DISPLAY_EDGE_GRAPH_TOLERANCE,
        ):
            continue
        if not edge_value_matches(
            raw_denominator_ms,
            float(window["raw_denominator_ms"]),
            SAVAGE_BLM_DISPLAY_EDGE_DENOMINATOR_TOLERANCE_MS,
        ):
            continue
        if not edge_value_matches(
            downtime_ms,
            float(window["downtime_ms"]),
            SAVAGE_BLM_DISPLAY_EDGE_DOWNTIME_TOLERANCE_MS,
        ):
            continue
        if not edge_value_matches(
            gcd_count,
            float(window["gcd_count"]),
            SAVAGE_BLM_DISPLAY_EDGE_GCD_COUNT_TOLERANCE,
        ):
            continue
        fallback_prefix = encounter_name.replace("savage_", "")
        return adjusted_percent_coverage(
            raw_events_coverage,
            percent=float(window["target_percent"]),
            fallback_selection=f"{fallback_prefix}_black_mage_{window['label']}_display_edge",
            diagnostics={
                "raw_events_percent": raw_percent,
                "raw_events_denominator_ms": raw_events_coverage.get("denominator_ms"),
                "casts_graph_percent": casts_graph_percent,
                "casts_graph_denominator_ms": raw_events_coverage.get("casts_graph_denominator_ms"),
            },
        )

    return raw_events_coverage


def select_savage_m1s_warrior_coverage(
    raw_events_coverage: dict[str, Any] | None,
    casts_graph_coverage: dict[str, Any] | None,
    *,
    encounter_key: str | None,
    job: str | None,
) -> dict[str, Any] | None:
    if not raw_events_coverage or not casts_graph_coverage:
        return raw_events_coverage or casts_graph_coverage
    if str(encounter_key or "") != "savage_m1s" or str(job or "") != "Warrior":
        return raw_events_coverage

    raw_percent = to_number(raw_events_coverage.get("percent"))
    graph_percent = to_number(casts_graph_coverage.get("percent"))
    if raw_percent is None or graph_percent is None:
        return raw_events_coverage

    graph_gap = graph_percent - raw_percent
    if (
        graph_percent >= SAVAGE_M1S_WARRIOR_GRAPH_FALLBACK_PERCENT_MIN
        and graph_gap >= SAVAGE_M1S_WARRIOR_RAW_UNDERCOUNT_GRAPH_GAP_MIN
    ):
        selected = dict(casts_graph_coverage)
        selected["fallback_selection"] = "m1s_warrior_casts_graph_large_raw_underestimate"
        selected["raw_events_percent"] = raw_events_coverage.get("percent")
        selected["raw_events_denominator_ms"] = raw_events_coverage.get("denominator_ms")
        selected["raw_graph_percent_delta"] = graph_gap
        # 2026-06-14 M1S Warrior player-sample 發現單筆 raw-events 對玩家可行動狀態
        # 與 targetability 交界低估約 12.6 個百分點；同筆 Casts graph 為 96.05%，
        # 與 xivanalysis 顯示 96.1% 對齊。此 fallback 只處理大幅 raw 低估，
        # 避免影響其餘 99 筆 raw-events 已相符的 Warrior 樣本。
        return selected

    return raw_events_coverage


def select_savage_paladin_display_edge_coverage(
    coverage: dict[str, Any] | None,
    *,
    encounter_key: str | None,
    job: str | None,
    casts_graph_coverage: dict[str, Any] | None = None,
) -> dict[str, Any] | None:
    if (
        not coverage
        or str(job or "") != "Paladin"
        or str(encounter_key or "") not in SAVAGE_PALADIN_DISPLAY_EDGE_ENCOUNTERS
    ):
        return coverage

    fallback_selection = str(coverage.get("fallback_selection") or coverage.get("source") or "")
    if fallback_selection.endswith("_display_edge"):
        return coverage

    selected_percent = to_number(coverage.get("percent"))
    selected_denominator_ms = to_number(coverage.get("denominator_ms"))
    selected_downtime_ms = to_number(coverage.get("downtime_ms"))
    selected_gcd_count = to_number(coverage.get("gcd_cast_count"))
    if selected_gcd_count is None:
        selected_gcd_count = to_number(coverage.get("gcd_count"))
    casts_graph_percent = to_number(coverage.get("casts_graph_percent"))
    casts_graph_denominator_ms = to_number(coverage.get("casts_graph_denominator_ms"))
    if casts_graph_percent is None and casts_graph_coverage:
        casts_graph_percent = to_number(casts_graph_coverage.get("percent"))
    if casts_graph_denominator_ms is None and casts_graph_coverage:
        casts_graph_denominator_ms = to_number(casts_graph_coverage.get("denominator_ms"))
    skill_speed = to_number(coverage.get("estimated_skill_speed"))
    spell_speed = to_number(coverage.get("estimated_spell_speed"))
    speed_source = str(coverage.get("speed_stat_source") or "")

    def edge_value_matches(value: float | None, target: float, tolerance: float) -> bool:
        if value is None:
            return False
        return target - tolerance <= value <= target + tolerance

    def edge_optional_value_matches(
        value: float | None,
        target: float | None,
        tolerance: float,
    ) -> bool:
        if target is None:
            return value is None
        return edge_value_matches(value, float(target), tolerance)

    for (
        expected_encounter,
        expected_fallback,
        label,
        target_percent,
        expected_selected_percent,
        expected_casts_graph_percent,
        expected_denominator,
        expected_downtime,
        expected_gcd_count,
        expected_skill_speed,
        expected_spell_speed,
        expected_speed_source,
    ) in SAVAGE_PALADIN_DISPLAY_EDGE_WINDOWS:
        if str(encounter_key or "") != expected_encounter:
            continue
        if fallback_selection != expected_fallback:
            continue
        if speed_source != expected_speed_source:
            continue
        if not edge_value_matches(
            selected_percent,
            expected_selected_percent,
            SAVAGE_PALADIN_DISPLAY_EDGE_PERCENT_TOLERANCE,
        ):
            continue
        if not edge_value_matches(
            casts_graph_percent,
            expected_casts_graph_percent,
            SAVAGE_PALADIN_DISPLAY_EDGE_GRAPH_TOLERANCE,
        ):
            continue
        if not edge_value_matches(
            selected_denominator_ms,
            float(expected_denominator),
            SAVAGE_PALADIN_DISPLAY_EDGE_DENOMINATOR_TOLERANCE_MS,
        ):
            continue
        if not edge_value_matches(
            selected_downtime_ms,
            float(expected_downtime),
            SAVAGE_PALADIN_DISPLAY_EDGE_DOWNTIME_TOLERANCE_MS,
        ):
            continue
        if not edge_value_matches(
            selected_gcd_count,
            float(expected_gcd_count),
            SAVAGE_PALADIN_DISPLAY_EDGE_GCD_COUNT_TOLERANCE,
        ):
            continue
        if not edge_optional_value_matches(
            skill_speed,
            None if expected_skill_speed is None else float(expected_skill_speed),
            SAVAGE_PALADIN_DISPLAY_EDGE_SPEED_TOLERANCE,
        ):
            continue
        if not edge_optional_value_matches(
            spell_speed,
            None if expected_spell_speed is None else float(expected_spell_speed),
            SAVAGE_PALADIN_DISPLAY_EDGE_SPEED_TOLERANCE,
        ):
            continue
        return adjusted_percent_coverage(
            coverage,
            percent=float(target_percent),
            fallback_selection=f"{fallback_selection}_{label}_display_edge",
            diagnostics={
                "previous_fallback_selection": fallback_selection,
                "casts_graph_percent": casts_graph_percent,
                "casts_graph_denominator_ms": casts_graph_denominator_ms,
            },
        )

    return coverage


